// v5.11.2 — erpV5Nav router and the entire "إدارة المؤسسة المتقدّمة"
// section have been removed. ERPv5 / ERPv54 modules are no longer loaded.

function erpNav(sectionId) {
  // Save last section for persistence across refreshes
  try { localStorage.setItem('pos_last_section', 'erp:' + sectionId); } catch(e) {}
  // Lazy-mount the section on first access
  if (typeof mountSection === 'function') mountSection(sectionId);
  // Update active state on sidebar
  document.querySelectorAll('[data-erp-nav]').forEach(el => el.classList.remove('active'));
  var activeNavEl = document.querySelector('[data-erp-nav="'+sectionId+'"]');
  if (activeNavEl) {
    activeNavEl.classList.add('active');
    // Auto-open parent submenu if collapsed
    var parent = activeNavEl.closest('.submenu');
    if (parent && !parent.classList.contains('open')) {
      parent.classList.add('open');
      var toggle = parent.previousElementSibling;
      if (toggle && toggle.classList.contains('has-submenu')) toggle.classList.add('open');
    }
  }
  // Hide all POS admin sections
  document.querySelectorAll('.admin-section').forEach(s => s.classList.remove('active'));
  // Hide all ERP dash sections
  document.querySelectorAll('.dash-section').forEach(s => s.classList.add('hidden'));
  const target = document.getElementById(sectionId);
  if (target) {
    target.classList.remove('hidden');
    // Load data for the section
    switch(sectionId) {
      case 'erpDashHome': erpLoadDashboard(); break;
      case 'erpCustomers': erpLoadCustomers(); break;
      case 'erpSuppliers': erpLoadSuppliers(); break;
      case 'erpGLAccounts': erpLoadAccounts(); break;
      case 'erpGLJournals': erpLoadJournals(); break;
      case 'erpPurchaseOrders': erpLoadPOs(); break;
      case 'erpVATReports': erpLoadVATReports(); break;
      case 'erpZATCA': erpLoadZATCA(); break;
      case 'erpInventoryMethod': erpLoadInventoryMethod(); break;
      case 'erpRptHub':          erpLoadReportsHub(); break;
      // Legacy alias — old erpFinReports redirects to the new hub
      case 'erpFinReports':      erpLoadReportsHub(); break;
      // NEW IFRS reports (added in 2026)
      case 'erpRptEquityChanges': erpLoadEquityChanges(); break;
      case 'erpRptFinRatios':    erpLoadFinRatios(); break;
      case 'erpRptBankRecon':    erpLoadBankRecon(); break;
      case 'erpRptAuditLog':     erpLoadAuditLog(); break;
      case 'erpBrands': erpLoadBrands(); break;
      case 'erpPurchaseReports': erpInitPurchaseReports(); break;
      case 'erpCostCenters': erpLoadCostCenters(); break;
      case 'erpDimensionsHub': erpLoadDimensionsHub(); break;
      case 'erpMultiWarehouses': erpLoadMultiWarehouses(); break;
      case 'erpBranches': erpLoadBranchesFull(); break;
      case 'erpPeriods': erpLoadPeriods(); break;
      case 'erpAuditLog': erpLoadAuditLog(); break;
      case 'erpCreditNotes': erpLoadNotes(); break;
      /* legacy warehouse nav cases removed */
      case 'erpARAging': erpLoadARAging(); break;
      case 'erpAPAging': erpLoadAPAging(); break;
      case 'erpCustomerStatement': erpLoadCustomerStatementPage(); break;
      case 'erpSupplierStatement': erpLoadSupplierStatementPage(); break;
      case 'erpGLLedgerReport': erpInitGLLedgerReport(); break;
      case 'erpWfPositions': wfLoadPositions(); break;
      case 'erpWfTypes': wfLoadTypes(); break;
      case 'erpWfDefs': wfLoadPositionSummary(); break;
      // ═══ ERP v3 standard reports ═══
      case 'erpRptTrialBalance':   erpLoadTrialBalance(); break;
      case 'erpRptPnL':             erpLoadPnL(); break;
      case 'erpRptBalanceSheet':   erpLoadBalanceSheet(); break;
      case 'erpRptCashFlow':       erpLoadCashFlow(); break;
      case 'erpRptProfitability':  erpLoadProfitability(); break;
      case 'erpRptInventoryVal':   erpLoadRptInventoryVal(); break;
      case 'erpRptWarehouseLedger': if (typeof erpLoadWarehouseLedger === 'function') erpLoadWarehouseLedger(); break;
      case 'erpRptSalesAnalytics': erpLoadSalesAnalytics(); break;
      case 'erpRptSalesByChannel': if (typeof erpLoadSalesByChannel === 'function') erpLoadSalesByChannel(); break;
      case 'erpRptDiscountsGiven': if (typeof erpLoadDiscountsGiven === 'function') erpLoadDiscountsGiven(); break;
      case 'erpRptWasteAnalytics': erpLoadWasteAnalytics(); break;
      case 'erpRptRoyaltyRecon':   erpLoadRoyaltyRecon(); break;
      // v5.10.5 — Fixed Assets registry
      case 'erpFixedAssets':       if (typeof erpLoadFixedAssets === 'function') erpLoadFixedAssets(); break;
      // ═══ Entity management ═══
      case 'erpCompanies':       erpLoadCompanies(); break;
      case 'erpPriceLists':      erpLoadPriceLists(); break;
      // ═══ Payment / Channels / Discounts (V3) ═══
      case 'erpPaymentMethodsV3':  if (typeof erpLoadPaymentMethodsV3 === 'function') erpLoadPaymentMethodsV3(); break;
      case 'erpSalesChannels':     if (typeof erpLoadSalesChannels === 'function') erpLoadSalesChannels(); break;
      case 'erpDiscountsV3':       if (typeof erpLoadDiscountsV3 === 'function') erpLoadDiscountsV3(); break;
      case 'erpShiftCloseAdmin':   if (typeof erpLoadShiftCloseAdmin === 'function') erpLoadShiftCloseAdmin(); break;
      // ═══ Menu / Brands / Production (V3) ═══
      case 'erpMenuHub':           if (typeof erpLoadMenuHub === 'function') erpLoadMenuHub(); break;
      case 'erpPermsMatrix':       if (typeof loadPermsMatrix === 'function') loadPermsMatrix(); break;
      case 'erpBrandMenu':         if (typeof erpLoadBrandMenu === 'function') erpLoadBrandMenu(); break;
      case 'erpSemiFinished':      if (typeof erpLoadSemiFinished === 'function') erpLoadSemiFinished(); break;
      case 'erpProductionOrders':  if (typeof erpLoadProductionOrders === 'function') erpLoadProductionOrders(); break;
      case 'erpBOM':             erpLoadBOM(); break;
      case 'erpWasteEntries':    erpLoadWasteEntries(); break;
      case 'erpRoyaltyRuns':     erpLoadRoyaltyRuns(); break;
      case 'erpPosTerminals':    erpLoadPosTerminals(); break;
      case 'erpItemCategories':  erpLoadItemCategories(); break;
      case 'erpWfInbox': wfLoadInbox(); break;
      case 'erpWfDashboard': wfInitDashboard(); break;
      case 'erpWfIncoming': wfLoadIncoming(); break;
      case 'erpWfOutgoing': wfLoadOutbox(); break;
      case 'erpWfOrgTree': wfLoadOrgTree(); break;
      case 'erpHrDashboard': hrLoadDashboard(); break;
      case 'erpHrEmployees': hrLoadEmployees(); break;
      case 'erpHrDepartments': hrLoadDepartments(); break;
      case 'erpHrAttendance': hrLoadAttendance(); break;
      case 'erpHrLeave': hrLoadLeaveRequests(); break;
      case 'erpHrPayroll': hrLoadPayrollRuns(); break;
      case 'erpHrAdvances': hrLoadAdvances(); break;
      case 'erpHrShifts': hrLoadShifts(); break;
      case 'erpHrOvertime': hrLoadOvertimeEntries(); break;
      case 'erpHrExceptions': hrLoadExceptions(); break;
      case 'erpCashDash': cashLoadDashboard(); break;
      case 'erpCashBoxes': cashLoadBoxes(); break;
      case 'erpBankAccounts': cashLoadBanks(); break;
      case 'erpCashReceipts': cashLoadReceipts(); break;
      case 'erpCashPayments': cashLoadPayments(); break;
      case 'erpCashTransfers': cashLoadTransfers(); break;
      // ═══ Warehouse Phase 1/2/3 ═══
      case 'erpWhHierarchy':     if (typeof whhLoad === 'function') whhLoad(); break;
      case 'erpStockIssues':     if (typeof siLoad === 'function') siLoad(); break;
      case 'erpProductionOrders':if (typeof prdLoadInit === 'function') prdLoadInit(); break;
      case 'erpExpiryAlerts':    if (typeof expLoad === 'function') expLoad(); break;
      case 'erpSlowMoving':      if (typeof slowLoad === 'function') slowLoad(); break;
      case 'erpTurnover':        if (typeof turnLoad === 'function') turnLoad(); break;
      case 'erpReorderAlerts':   if (typeof reorderLoad === 'function') reorderLoad(); break;
      case 'erpDaysOfStock':     if (typeof dosLoad === 'function') dosLoad(); break;
      case 'erpAbcAnalysis':     if (typeof abcLoad === 'function') abcLoad(); break;
      case 'erpStocktakeHistory':if (typeof sthLoad === 'function') sthLoad(); break;
    }
  }
  // Update sidebar active state
  document.querySelectorAll('.sidebar-item').forEach(i => i.classList.remove('active'));
  const activeItem = document.querySelector(`[data-erp-nav="${sectionId}"]`);
  if (activeItem) activeItem.classList.add('active');
}

