// ERP DASHBOARD
// ═══════════════════════════════════════
function erpLoadDashboard() { return erpLoadDashHome(); }

function erpLoadDashHome() {
  var fmt = function(v) { return Number(v||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}); };
  var setT = function(id, val) { var el = document.getElementById(id); if (el) el.textContent = val; };

  // Main financial + counts from legacy endpoint
  window._apiBridge.withSuccessHandler(function(data) {
    if (!data || !data.success) return;
    setT('erpCustCount',  data.counts.customers || 0);
    setT('erpSupCount',   data.counts.suppliers || 0);
    setT('erpJrnCount',   data.counts.journals  || 0);
    setT('erpBrCount',    data.counts.branches  || 0);
    setT('erpTotalAssets', fmt(data.financial.totalAssets));
    setT('erpTotalLiab',   fmt(data.financial.totalLiabilities));
    setT('erpTotalEquity', fmt(data.financial.totalEquity));
    setT('erpTotalRev',    fmt(data.financial.totalRevenue));
    setT('erpTotalExp',    fmt(data.financial.totalExpenses));
    var ni = data.financial.netIncome || 0;
    setT('erpNetIncome', fmt(ni));
    var niEl = document.getElementById('erpNetIncome');
    if (niEl) niEl.className = 'wo-metric-value wo-money ' + (ni >= 0 ? 'pos' : 'neg');
    setT('erpVATOutput', fmt(data.vat.totalOutputVAT));
    setT('erpVATInput',  fmt(data.vat.totalInputVAT));
    setT('erpVATNet',    fmt(data.vat.netVAT));
  }).getERPDashboardData();

  // New: Workflow KPIs (Phase D) — read from /api/workflow/inbox + /api/erp/payments
  var token = localStorage.getItem('pos_token') || '';
  var username = (typeof state !== 'undefined' && state.user) || '';
  Promise.all([
    fetch('/api/workflow/transactions?status=pending&limit=1000', { headers: { 'Authorization': 'Bearer ' + token } }).then(function(r){return r.json();}).catch(function(){return [];}),
    fetch('/api/erp/payments?status=authorized',                   { headers: { 'Authorization': 'Bearer ' + token } }).then(function(r){return r.json();}).catch(function(){return [];}),
    fetch('/api/erp/payments?status=closed&dateFrom=' + new Date().toISOString().slice(0,10), { headers: { 'Authorization': 'Bearer ' + token } }).then(function(r){return r.json();}).catch(function(){return [];}),
    fetch('/api/workflow/incoming' + (username ? '?username=' + encodeURIComponent(username) : ''), { headers: { 'Authorization': 'Bearer ' + token } }).then(function(r){return r.json();}).catch(function(){return [];})
  ]).then(function(all) {
    var pendingTxns = Array.isArray(all[0]) ? all[0].length : 0;
    var pendingPayments = Array.isArray(all[1]) ? all[1].length : 0;
    var closedToday = Array.isArray(all[2]) ? all[2].length : 0;
    var myInbox = Array.isArray(all[3]) ? all[3].length : 0;
    setT('dhPendingTxns', pendingTxns);
    setT('dhPendingPayments', pendingPayments);
    setT('dhClosedToday', closedToday);
    setT('dhMyInbox', myInbox);
  }).catch(function(){ /* silent */ });
}
window.erpLoadDashHome = erpLoadDashHome;

// ═══════════════════════════════════════
// CUSTOMERS CRUD
// ═══════════════════════════════════════
let _erpCustomers = [];
function erpLoadCustomers() {
  window._apiBridge.withSuccessHandler(function(list) {
    _erpCustomers = list || [];
    const tbody = document.getElementById('erpCustomersBody');
    if (_erpCustomers.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="empty-msg">لا يوجد عملاء</td></tr>';
      return;
    }
    tbody.innerHTML = _erpCustomers.map(c => `<tr>
      <td>${c.id||''}</td><td><strong>${c.name||''}</strong></td><td>${c.vatNumber||'-'}</td>
      <td>${c.phone||'-'}</td><td><span class="badge badge-${c.customerType==='B2B'?'blue':'green'}">${c.customerType||'B2C'}</span></td>
      <td>${(Number(c.balance)||0).toFixed(2)}</td>
      <td><span class="badge badge-${c.isActive!==false?'green':'red'}">${c.isActive!==false?'نشط':'معطل'}</span></td>
      <td><button class="btn-icon" onclick="erpEditCustomer('${c.id}')"><i class="fas fa-edit"></i></button>
      <button class="btn-icon text-red" onclick="erpDeactivateCustomer('${c.id}')"><i class="fas fa-ban"></i></button></td>
    </tr>`).join('');
  }).getCustomers();
}

function erpOpenCustomerModal(data) {
  const d = data || {};
  document.getElementById('erpModalTitle').textContent = d.id ? 'تعديل عميل' : 'إضافة عميل جديد';
  document.getElementById('erpModalBody').innerHTML = `
    <input type="hidden" id="erpCustID" value="${d.id||''}">
    <div class="form-row"><label>الاسم (عربي) *</label><input class="form-control" id="erpCustName" value="${d.name||''}"></div>
    <div class="form-row"><label>الاسم (إنجليزي)</label><input class="form-control" id="erpCustNameEN" value="${d.nameEn||''}"></div>
    <div class="form-row"><label>الرقم الضريبي</label><input class="form-control" id="erpCustVAT" value="${d.vatNumber||''}"></div>
    <div class="form-row"><label>الهاتف</label><input class="form-control" id="erpCustPhone" value="${d.phone||''}"></div>
    <div class="form-row"><label>البريد الإلكتروني</label><input class="form-control" id="erpCustEmail" value="${d.email||''}"></div>
    <div class="form-row"><label>العنوان</label><input class="form-control" id="erpCustAddr" value="${d.address||''}"></div>
    <div class="form-row"><label>المدينة</label><input class="form-control" id="erpCustCity" value="${d.city||''}"></div>
    <div class="form-row"><label>نوع العميل</label><select class="form-control" id="erpCustType"><option value="B2C" ${d.customerType==='B2C'?'selected':''}>B2C — مستهلك</option><option value="B2B" ${d.customerType==='B2B'?'selected':''}>B2B — شركة</option><option value="B2G" ${d.customerType==='B2G'?'selected':''}>B2G — جهة حكومية</option></select></div>
    <div class="form-row"><label>حد الائتمان</label><input type="number" class="form-control" id="erpCustCredit" value="${d.creditLimit||0}"></div>`;
  document.getElementById('erpModalSaveBtn').onclick = erpSaveCustomer;
  document.getElementById('erpModal').classList.remove('hidden');
}

function erpEditCustomer(id) {
  const c = _erpCustomers.find(x => String(x.id) === String(id));
  if (c) erpOpenCustomerModal(c);
}

function erpSaveCustomer() {
  const data = {
    id: document.getElementById('erpCustID').value || '',
    name: (document.getElementById('erpCustName').value || '').trim(),
    nameEn: document.getElementById('erpCustNameEN').value || '',
    vatNumber: document.getElementById('erpCustVAT').value || '',
    phone: document.getElementById('erpCustPhone').value || '',
    email: document.getElementById('erpCustEmail').value || '',
    address: document.getElementById('erpCustAddr').value || '',
    city: document.getElementById('erpCustCity').value || '',
    customerType: document.getElementById('erpCustType').value || 'B2C',
    creditLimit: Number(document.getElementById('erpCustCredit').value) || 0,
    username: currentUser || ''
  };
  if (!data.name) return showToast('الاسم مطلوب', 'error');
  loader(true);
  window._apiBridge.withSuccessHandler(function(res) {
    loader(false);
    if (res && res.success) { showToast('تم الحفظ بنجاح'); erpCloseModal(); erpLoadCustomers(); }
    else showToast((res && res.error) || 'فشل الحفظ', 'error');
  }).withFailureHandler(function(e) {
    loader(false);
    showToast('خطأ في الاتصال: ' + e.message, 'error');
  }).saveCustomer(data, currentUser);
}

function erpDeactivateCustomer(id) {
  if (!confirm('هل تريد تعطيل هذا العميل؟')) return;
  window._apiBridge.withSuccessHandler(function(res) {
    if (res.success) { showToast('تم التعطيل'); erpLoadCustomers(); }
    else showToast(res.error, 'error');
  }).deleteCustomer(id, currentUser);
}

// ═══════════════════════════════════════
// SUPPLIERS CRUD
// ═══════════════════════════════════════
let _erpSuppliers = [];
let _erpSupBrandsCache = null;
function erpLoadSuppliers() {
  var tbody = document.getElementById('erpSuppliersBody');
  if (tbody) tbody.innerHTML = '<tr><td colspan="9" class="empty-msg"><i class="fas fa-spinner fa-spin"></i> جاري التحميل...</td></tr>';
  // Populate brand filter once
  if (!_erpSupBrandsCache) {
    _erpGet('/erp/brands', function(brs){
      _erpSupBrandsCache = brs || [];
      var sel = document.getElementById('erpSupFBrand');
      if (sel) sel.innerHTML = '<option value="">كل البراندات</option>' + _erpSupBrandsCache.map(function(b){return '<option value="'+b.id+'">'+_woEscapeHtml(b.name||'')+'</option>';}).join('');
    });
  }
  window._apiBridge
    .withSuccessHandler(function(list) {
      _erpSuppliers = list || [];
      erpRenderSuppliersTable(_erpSuppliers);
    })
    .withFailureHandler(function(e) {
      if (tbody) tbody.innerHTML = '<tr><td colspan="9" class="empty-msg" style="color:red;">خطأ: ' + e.message + '</td></tr>';
    })
    .getSuppliers();
}

function erpFilterSuppliersTable() {
  const q = (document.getElementById('erpSupSearch')?.value || '').toLowerCase();
  const bId = (document.getElementById('erpSupFBrand')?.value || '');
  const st  = (document.getElementById('erpSupFStatus')?.value || '');
  const noBrandChip = document.querySelector('[data-sup-qf="nobrand"].active');
  const balChip     = document.querySelector('[data-sup-qf="withBalance"].active');
  let filtered = _erpSuppliers;
  if (q)   filtered = filtered.filter(s => (s.name||'').toLowerCase().includes(q) || (s.phone||'').includes(q) || (s.vatNumber||'').includes(q));
  if (bId) filtered = filtered.filter(s => String(s.brandId||'') === String(bId));
  if (st === 'active')   filtered = filtered.filter(s => s.isActive !== false);
  if (st === 'inactive') filtered = filtered.filter(s => s.isActive === false);
  if (noBrandChip) filtered = filtered.filter(s => !s.brandId);
  if (balChip)     filtered = filtered.filter(s => Number(s.balance||0) > 0);
  var rc = document.getElementById('erpSupResultsCount');
  if (rc) {
    var totalBal = filtered.reduce(function(sum,x){return sum + Number(x.balance||0);},0);
    rc.innerHTML = '<i class="fas fa-circle-info"></i> <b>'+filtered.length+'</b> مورد · رصيد إجمالي: <b>'+totalBal.toLocaleString('en',{minimumFractionDigits:2})+'</b>';
  }
  erpRenderSuppliersTable(filtered);
}

function _erpSupSetQuickChip(k) {
  document.querySelectorAll('[data-sup-qf]').forEach(function(el){
    el.classList.toggle('active', el.getAttribute('data-sup-qf') === k);
  });
}
function erpSupQuickFilter(k) {
  _erpSupSetQuickChip(k);
  var st = document.getElementById('erpSupFStatus');
  if (st) st.value = '';
  if (k === 'active')   st.value = 'active';
  else if (k === 'inactive') st.value = 'inactive';
  erpFilterSuppliersTable();
}
function erpSupResetFilters() {
  ['erpSupSearch','erpSupFBrand','erpSupFStatus'].forEach(function(id){
    var e = document.getElementById(id); if (e) e.value = '';
  });
  _erpSupSetQuickChip('');
  erpFilterSuppliersTable();
}

function erpRenderSuppliersTable(list) {
  const tbody = document.getElementById('erpSuppliersBody');
  if (!tbody) return;
  if (!list || list.length === 0) {
    tbody.innerHTML = '<tr><td colspan="9" class="empty-msg">لا يوجد موردين</td></tr>';
    return;
  }
  tbody.innerHTML = list.map(s => {
    var brandChip = s.brandName
      ? `<span class="wo-chip purple"><i class="fas fa-store"></i> ${_woEscapeHtml(s.brandName)}</span>`
      : '<span class="wo-text-subtle wo-text-caption">عام</span>';
    return `<tr>
    <td><code style="font-size:11px;">${s.id||''}</code></td>
    <td><strong>${s.name||''}</strong>${s.nameEn ? `<br><small style="color:#64748b;">${s.nameEn}</small>` : ''}</td>
    <td>${brandChip}</td>
    <td>${s.vatNumber||'—'}</td>
    <td>${s.phone||'—'}</td>
    <td><span class="badge badge-blue">${s.paymentTerms||'Cash'}</span></td>
    <td><strong>${(Number(s.balance)||0).toFixed(2)}</strong></td>
    <td><span class="badge badge-${s.isActive!==false?'green':'red'}">${s.isActive!==false?'نشط':'معطل'}</span></td>
    <td style="white-space:nowrap;">
      <button class="btn-icon" title="تعديل" onclick="erpEditSupplier('${s.id}')"><i class="fas fa-edit"></i></button>
      <button class="btn-icon text-red" title="حذف" onclick="erpDeleteSupplier('${s.id}','${(s.name||'').replace(/'/g,"\\'")}')"><i class="fas fa-trash"></i></button>
    </td>
  </tr>`;
  }).join('');
}

function erpOpenSupplierModal(data) {
  const d = data || {};
  document.getElementById('erpModalTitle').textContent = d.id ? 'تعديل مورد' : 'إضافة مورد جديد';
  _erpGet('/erp/brands', function(brs){
    var brandOpts = '<option value="">— مورد عام (كل البراندات) —</option>' +
      (brs||[]).map(function(b){
        var sel = (d.brandId === b.id) ? ' selected' : '';
        return '<option value="'+b.id+'"'+sel+'>'+_woEscapeHtml(b.name||'')+'</option>';
      }).join('');
    document.getElementById('erpModalBody').innerHTML = `
      <input type="hidden" id="erpSupID" value="${d.id||''}">
      <div class="form-row"><label>الاسم (عربي) *</label><input class="form-control" id="erpSupName" value="${d.name||''}"></div>
      <div class="form-row"><label>الاسم (إنجليزي)</label><input class="form-control" id="erpSupNameEN" value="${d.nameEn||''}"></div>
      <div class="form-row"><label><i class="fas fa-store" style="color:#8b5cf6;"></i> البراند</label><select class="form-control" id="erpSupBrand">${brandOpts}</select><small style="color:#64748b;">اختر البراند لتصفية هذا المورد ضمن قسم البراند — اتركه فارغاً للموردين العامين.</small></div>
      <div class="form-row"><label>الرقم الضريبي</label><input class="form-control" id="erpSupVAT" value="${d.vatNumber||''}"></div>
      <div class="form-row"><label>الهاتف</label><input class="form-control" id="erpSupPhone" value="${d.phone||''}"></div>
      <div class="form-row"><label>البريد الإلكتروني</label><input class="form-control" id="erpSupEmail" value="${d.email||''}"></div>
      <div class="form-row"><label>العنوان</label><input class="form-control" id="erpSupAddr" value="${d.address||''}"></div>
      <div class="form-row"><label>المدينة</label><input class="form-control" id="erpSupCity" value="${d.city||''}"></div>
      <div class="form-row"><label>شروط الدفع</label><select class="form-control" id="erpSupTerms"><option value="Cash" ${d.paymentTerms==='Cash'?'selected':''}>نقدي</option><option value="Net30" ${d.paymentTerms==='Net30'?'selected':''}>30 يوم</option><option value="Net60" ${d.paymentTerms==='Net60'?'selected':''}>60 يوم</option></select></div>`;
    document.getElementById('erpModalSaveBtn').onclick = erpSaveSupplier;
    document.getElementById('erpModal').classList.remove('hidden');
  });
}

function erpEditSupplier(id) {
  const s = _erpSuppliers.find(x => String(x.id) === String(id));
  if (s) erpOpenSupplierModal(s);
}

function erpSaveSupplier() {
  const data = {
    id: document.getElementById('erpSupID').value || '',
    name: (document.getElementById('erpSupName').value || '').trim(),
    nameEn: document.getElementById('erpSupNameEN').value || '',
    brandId: (document.getElementById('erpSupBrand') && document.getElementById('erpSupBrand').value) || null,
    vatNumber: document.getElementById('erpSupVAT').value || '',
    phone: document.getElementById('erpSupPhone').value || '',
    email: document.getElementById('erpSupEmail').value || '',
    address: document.getElementById('erpSupAddr').value || '',
    city: document.getElementById('erpSupCity').value || '',
    paymentTerms: document.getElementById('erpSupTerms').value || 'Cash',
    username: currentUser || ''
  };
  if (!data.name) return showToast('اسم المورد مطلوب', 'error');
  const btn = document.getElementById('erpModalSaveBtn');
  if (btn) btn.disabled = true;
  loader(true);
  window._apiBridge
    .withSuccessHandler(function(res) {
      loader(false);
      if (btn) btn.disabled = false;
      if (res && res.success) {
        showToast('تم حفظ المورد بنجاح');
        erpCloseModal();
        erpLoadSuppliers();
      } else {
        showToast((res && res.error) || 'فشل الحفظ', 'error');
      }
    })
    .withFailureHandler(function(e) {
      loader(false);
      if (btn) btn.disabled = false;
      showToast('خطأ في الاتصال: ' + e.message, 'error');
    })
    .saveSupplier(data, currentUser);
}

function erpDeleteSupplier(id, name) {
  if (!confirm('هل تريد حذف المورد "' + (name||id) + '" نهائياً؟')) return;
  loader(true);
  window._apiBridge
    .withSuccessHandler(function(res) {
      loader(false);
      if (res && res.success) { showToast('تم حذف المورد'); erpLoadSuppliers(); }
      else showToast((res && res.error) || 'خطأ', 'error');
    })
    .withFailureHandler(function(e) { loader(false); showToast('خطأ: ' + e.message, 'error'); })
    .deleteSupplier(id, currentUser);
}

// ═══════════════════════════════════════
// GL ACCOUNTS — Tree View (دليل الحسابات)
// ═══════════════════════════════════════
let _erpAccounts = [];
var _coaSelectedId = null;
// v5.10.35 — type filter state (one of '', 'asset','liability','equity','revenue','expense')
window._coaTypeFilter = window._coaTypeFilter || '';
// v5.10.35 — diagnose snapshot
window._coaDiagSnap = null;
// v5.10.45 — single source of truth for which folders are open in the tree.
// Replaces the depth-based heuristic that lost user state on every rebuild.
// Persisted to localStorage so it survives reload and any data refresh.
window._coaOpenSet = window._coaOpenSet || null;
function _coaPersistOpenSet() {
  try {
    if (window._coaOpenSet) {
      localStorage.setItem('coa_open_set', JSON.stringify(Array.from(window._coaOpenSet)));
    }
  } catch (_) {}
}
function _coaRestoreOpenSet() {
  try {
    var raw = localStorage.getItem('coa_open_set');
    if (raw) {
      var arr = JSON.parse(raw);
      if (Array.isArray(arr)) window._coaOpenSet = new Set(arr);
    }
  } catch (_) {}
}
function _coaSeedOpenSetIfEmpty() {
  if (window._coaOpenSet && window._coaOpenSet.size > 0) return;
  if (!window._coaOpenSet) window._coaOpenSet = new Set();
  // First run: open the 5 IFRS roots so the user sees the structure immediately.
  (_erpAccounts || []).forEach(function(a){
    if (['1','2','3','4','5'].indexOf(String(a.code)) >= 0) window._coaOpenSet.add(a.id);
  });
}

function erpLoadAccounts() {
  window._apiBridge.withSuccessHandler(function() {
    erpLoadAccountsList_();
  }).seedCafeGLAccounts();
}
function erpLoadAccountsList_() {
  // Sync inventory values to GL first (perpetual method)
  window._apiBridge.withSuccessHandler(function() {
    // Then load accounts
    window._apiBridge.withSuccessHandler(function(list) {
      // v5.10.42 — preserve isFolder, movementCount, storedBalance from
      // the v5.10.38+ endpoints. Without this mapping, _coaIsGroup never
      // sees user-promoted folders and _coaHasMovements always returns 0.
      _erpAccounts = (list || []).map(function(a) {
        return {
          id: a.id, code: a.code, nameAr: a.nameAr, nameEn: a.nameEn,
          type: a.type, parentId: a.parentId, level: Number(a.level) || 1,
          isActive: a.isActive,
          isFolder: !!a.isFolder,
          // v5.10.51 — explicit display_order persisted per account
          displayOrder: a.displayOrder == null ? null : Number(a.displayOrder),
          balance: Number(a.balance) || 0,
          storedBalance: Number(a.storedBalance) || 0,
          movementCount: Number(a.movementCount) || 0
        };
      });
      // v5.10.51 — explicit displayOrder wins, code is the tiebreaker.
      // NULL falls to the bottom (matches the SQL COALESCE 99999 trick).
      _erpAccounts.sort(function(a, b){
        var ao = a.displayOrder == null ? 99999 : Number(a.displayOrder);
        var bo = b.displayOrder == null ? 99999 : Number(b.displayOrder);
        if (ao !== bo) return ao - bo;
        return String(a.code || '').localeCompare(String(b.code || ''));
      });
      // v5.10.45 — restore persisted open-set (or seed with the 5 roots
      // on first run) before the first build so the tree opens at the
      // user's last expanded state, not at an arbitrary default.
      _coaRestoreOpenSet();
      _coaSeedOpenSetIfEmpty();
      _coaBuildTree();
      if (_coaSelectedId) coaSelectNode(_coaSelectedId);
    }).getGLAccounts();
  }).syncInventoryGL();
}

// ─── Build children map ───
function _coaChildrenOf(parentId) {
  // v5.10.51 — same priority as _erpAccounts.sort: explicit displayOrder
  // first (NULL → bottom), code as tiebreaker. This is what makes the
  // user's import-order edits actually show up in the tree.
  return _erpAccounts
    .filter(function(a){ return (a.parentId || null) === (parentId || null); })
    .sort(function(a, b){
      var ao = a.displayOrder == null ? 99999 : Number(a.displayOrder);
      var bo = b.displayOrder == null ? 99999 : Number(b.displayOrder);
      if (ao !== bo) return ao - bo;
      return String(a.code || '').localeCompare(String(b.code || ''));
    });
}
// v5.10.43 — defense in depth against migration failure: codes 1..5
// (the IFRS roots) are ALWAYS folders regardless of what the database
// says. This ensures حقوق الملكية and الإيرادات never render as leaves
// even if the is_folder migration silently failed in production.
function _coaIsGroup(id) {
  var acc = _erpAccounts.find(function(a){ return a.id === id; });
  if (!acc) return false;
  if (['1','2','3','4','5'].indexOf(String(acc.code)) >= 0) return true;
  if (acc.isFolder) return true;
  return _erpAccounts.some(function(a){ return a.parentId === id; });
}

// v5.10.38 — does this account (or any descendant) have any posted journal
// entries? Used to hide structural-only accounts from the tree by default.
function _coaHasMovements(accId) {
  var acc = _erpAccounts.find(function(a){ return a.id === accId; });
  if (!acc) return false;
  if ((acc.movementCount || 0) > 0) return true;
  var children = _coaChildrenOf(accId);
  return children.some(function(c) { return _coaHasMovements(c.id); });
}

// Rollup balance: sum self + all descendants (for parent/folder accounts)
function _coaRollupBalance(accId) {
  var acc = _erpAccounts.find(function(a) { return a.id === accId; });
  if (!acc) return 0;
  var total = Number(acc.balance) || 0;
  var children = _coaChildrenOf(accId);
  children.forEach(function(c) { total += _coaRollupBalance(c.id); });
  return total;
}

// ─── Build Tree Sidebar ───
function _coaBuildTree() {
  var container = document.getElementById('coaTreeBody');
  if (!container) return;

  // v5.10.35 — refresh top filter chips first
  _coaRenderTypeChips();

  var typeFilter = window._coaTypeFilter || '';

  // Find ONLY the 5 main roots by code (1,2,3,4,5)
  var mainCodes = ['1','2','3','4','5'];
  var roots = _erpAccounts.filter(function(a) {
    return mainCodes.indexOf(a.code) >= 0;
  }).sort(function(a,b) { return a.code.localeCompare(b.code); });

  // If no accounts with exact codes 1-5, fallback to level=1
  if (!roots.length) {
    roots = _erpAccounts.filter(function(a) { return a.level === 1; }).sort(function(a,b) { return a.code.localeCompare(b.code); });
  }

  // Final fallback: accounts with no parent
  if (!roots.length) roots = _coaChildrenOf(null);

  // v5.10.35 — when a type filter is active, hide root branches that don't
  // match (e.g. selecting 'asset' shows only the "1 الأصول" tree)
  if (typeFilter) {
    roots = roots.filter(function(r){ return r.type === typeFilter; });
  }

  // v5.10.38 — by default hide branches with no journal movements anywhere
  // in the subtree. The 5 main roots (codes 1-5) always show so the user
  // can build the chart from scratch. Toggle exposes structural accounts.
  var hideEmpty = !window._coaShowEmpty;
  if (hideEmpty) {
    var alwaysShow = ['1','2','3','4','5'];
    roots = roots.filter(function(r){
      return alwaysShow.indexOf(r.code) >= 0 || _coaHasMovements(r.id);
    });
  }

  // v5.10.41 — only the 5 roots are open by default; all descendants start
  // collapsed so the user sees a clean overview and can drill down on demand.
  container.innerHTML = roots.length
    ? roots.map(function(a) { return _coaRenderNode(a, true, /*depth*/0); }).join('')
    : '<div class="coa-empty"><i class="fas fa-folder-open"></i><p>لا حسابات في هذا التصنيف</p></div>';

  // v5.10.41 — restore persisted tree-panel width (set by user via the
  // resize handle). Saved on every mouseup of the panel.
  var panel = document.querySelector('.coa-tree-panel');
  if (panel) {
    var saved = parseInt(localStorage.getItem('coaTreeWidth') || '0', 10);
    if (saved >= 320 && saved <= 800) panel.style.width = saved + 'px';
    if (!panel._coaWidthBound) {
      panel._coaWidthBound = true;
      panel.addEventListener('mouseup', function(){
        try { localStorage.setItem('coaTreeWidth', String(panel.getBoundingClientRect().width | 0)); } catch(_) {}
      });
    }
  }
}

// v5.10.35 — Render the top type-filter chip strip with live counts + balances
function _coaRenderTypeChips() {
  var box = document.getElementById('coaTypeChips');
  if (!box) return;
  var current = window._coaTypeFilter || '';
  var fmt = function(n){ return Number(n||0).toLocaleString('en',{maximumFractionDigits:0}); };
  var chipDef = [
    { id:'',         label:'الكل',          icon:'fa-layer-group',     cls:'all' },
    { id:'asset',    label:'الأصول',        icon:'fa-vault',           cls:'asset' },
    { id:'liability',label:'الالتزامات',    icon:'fa-file-invoice',    cls:'liability' },
    { id:'equity',   label:'حقوق الملكية',  icon:'fa-handshake',       cls:'equity' },
    { id:'revenue',  label:'الإيرادات',     icon:'fa-arrow-trend-up',  cls:'revenue' },
    { id:'expense',  label:'المصروفات',     icon:'fa-arrow-trend-down',cls:'expense' }
  ];
  // Compute counts + total balance per type (across leaves only — sum at root level)
  var stats = { '':{count: _erpAccounts.length, balance: 0}, asset:{count:0,balance:0}, liability:{count:0,balance:0}, equity:{count:0,balance:0}, revenue:{count:0,balance:0}, expense:{count:0,balance:0} };
  _erpAccounts.forEach(function(a){
    if (stats[a.type]) {
      stats[a.type].count++;
      // Only sum non-group accounts (leaves) to avoid double counting
      if (!_coaIsGroup(a.id)) stats[a.type].balance += Number(a.balance) || 0;
    }
  });
  // Compute total balance for "All" as sum across types
  stats[''].balance = stats.asset.balance + stats.liability.balance + stats.equity.balance + stats.revenue.balance + stats.expense.balance;

  box.innerHTML = chipDef.map(function(c){
    var s = stats[c.id] || { count: 0, balance: 0 };
    var active = (c.id === current) ? ' is-active' : '';
    return '<button class="coa-type-chip coa-type-chip--' + c.cls + active + '" data-type="' + c.id + '" onclick="coaSetTypeFilter(\'' + c.id + '\')">' +
      '<i class="fas ' + c.icon + '"></i>' +
      '<span class="coa-type-chip__label">' + c.label + '</span>' +
      '<span class="coa-type-chip__count">' + s.count + '</span>' +
      (s.balance ? '<span class="coa-type-chip__bal">' + fmt(s.balance) + ' ر.س</span>' : '') +
    '</button>';
  }).join('');
}

window.coaSetTypeFilter = function(type) {
  window._coaTypeFilter = type || '';
  _coaBuildTree();
};

// v5.10.38 — toggle structural / empty accounts in the COA tree.
// Default (false): only accounts with posted journal entries (anywhere
// in their subtree) are shown. The 5 main roots always show.
window.coaToggleShowEmpty = function(checked) {
  window._coaShowEmpty = !!checked;
  _coaBuildTree();
};

// v5.10.45 — expand/collapse all rewritten on top of _coaOpenSet so the
// state survives every subsequent rebuild and persists across reloads.
// "Collapse all" now means "all" — even the 5 roots collapse, matching
// the user's explicit expectation. They can re-expand any root with one
// click; we no longer special-case them.
window.coaExpandAll = function() {
  if (!window._coaOpenSet) window._coaOpenSet = new Set();
  _erpAccounts.forEach(function(a){
    var hasKids = _erpAccounts.some(function(b){ return b.parentId === a.id; });
    if (hasKids) window._coaOpenSet.add(a.id);
  });
  _coaPersistOpenSet();
  _coaBuildTree();
};
window.coaCollapseAll = function() {
  window._coaOpenSet = new Set();
  _coaPersistOpenSet();
  _coaBuildTree();
};

// v5.10.39 — quick row actions. Both currently delegate to coaSelectNode
// which loads the ledger view in the main panel; the separation lets us
// later route "view ledger" vs "edit" to dedicated screens without
// changing the tree markup.
window.coaViewLedger  = function(id) { if (typeof coaSelectNode === 'function') coaSelectNode(id); };
window.coaEditAccount = function(id) { if (typeof coaSelectNode === 'function') coaSelectNode(id); };

function _coaRenderNode(acc, open, depth) {
  if (typeof depth !== 'number') depth = 0;
  var children = _coaChildrenOf(acc.id);
  // v5.10.38 — when hideEmpty mode is on, drop children with no movements
  // anywhere below them (and no movement of their own). Roots 1-5 are
  // never hidden — that's enforced in _coaBuildTree, not here.
  var hideEmpty = !window._coaShowEmpty;
  if (hideEmpty) {
    children = children.filter(function(c){ return _coaHasMovements(c.id); });
  }
  var isGroup = children.length > 0;
  var lvl = acc.level || 1;
  // v5.10.45 — open state lives in window._coaOpenSet (persisted to
  // localStorage). Replaces the depth-based heuristic that lost the
  // user's expansion state on every rebuild and made coaExpandAll a
  // best-effort visual hack instead of a real source of truth.
  if (!window._coaOpenSet) window._coaOpenSet = new Set();
  var openSelf = isGroup && window._coaOpenSet.has(acc.id);
  var chevronDir = openSelf ? 'fa-chevron-down' : 'fa-chevron-left';
  var toggle = isGroup ? '<span class="coa-node-toggle"><i class="fas ' + chevronDir + '"></i></span>' : '<span style="width:16px;display:inline-block;"></span>';
  var iconSize = lvl <= 1 ? 18 : lvl === 2 ? 16 : lvl === 3 ? 14 : 12;
  var icon = isGroup
    ? '<i class="fas fa-folder" style="color:#f59e0b;font-size:' + iconSize + 'px;"></i>'
    : '<i class="fas fa-file-alt" style="color:#3b82f6;font-size:' + iconSize + 'px;"></i>';
  var fontW = lvl <= 1 ? 900 : lvl === 2 ? 800 : lvl === 3 ? 600 : 400;
  var fontSize = lvl <= 1 ? 15 : lvl === 2 ? 14 : lvl === 3 ? 13 : 12;
  var activeClass = _coaSelectedId === acc.id ? ' active' : '';

  // v5.10.41 — type-badge is now an inline-start border on the row itself
  // (set via [data-type] CSS), and the L1 level badge is removed from the
  // default view to give the name full breathing room. Both can be brought
  // back via inspector if needed; the row no longer wastes pixels on chrome.
  var typeBadge = '';
  var levelBadge = '';
  // v5.10.42 — warning icon shows ONLY for critical issues that need
  // attention. Minor structural issues (levelMismatch, typeMismatch) are
  // fixed automatically by deep-repair and don't deserve a noisy warning.
  var warnHtml = '';
  var snap = window._coaDiagSnap;
  if (snap && snap.issues) {
    var hit = function(arr){ return arr && arr.find(function(x){ return x.id === acc.id; }); };
    var critical = null;
    if      (hit(snap.issues.rootCodeMismatch))         critical = 'الجذر الفعلي لا يطابق الكود';
    else if (hit(snap.issues.balanceWithoutEntries))    critical = 'رصيد بدون قيود فعلية';
    else if (hit(snap.issues.nameVsPlacementMismatch))  critical = 'الاسم لا يطابق المكان في الشجرة';
    else if (hit(snap.issues.cycles))                   critical = 'حلقة في الشجرة';
    else if (hit(snap.issues.codeTypeMismatch))         critical = 'النوع لا يطابق جذر الكود';
    else if (hit(snap.issues.orphans))                  critical = 'حساب يتيم (parent محذوف)';
    if (critical) warnHtml = '<i class="fas fa-triangle-exclamation coa-warn-icon" title="' + critical + '" onclick="event.stopPropagation();coaOpenDiagnose();"></i>';
  }

  // v5.10.39 — folder balance ALWAYS shown (not only when non-zero) so parents
  // surface their rollup at a glance. Leaves still hide zero to avoid clutter.
  var displayBal = isGroup ? _coaRollupBalance(acc.id) : (Number(acc.balance) || 0);
  var balClass = displayBal > 0 ? 'coa-folder-balance--pos'
              : displayBal < 0 ? 'coa-folder-balance--neg'
              : 'coa-folder-balance--zero';
  var balHtml = '';
  if (isGroup) {
    balHtml = '<span class="coa-folder-balance coa-folder-balance--group ' + balClass + '">' +
      Number(displayBal).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}) +
    '</span>';
  } else if (displayBal !== 0) {
    balHtml = '<span class="coa-folder-balance ' + balClass + '" style="font-size:11px;">' +
      Number(displayBal).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}) +
    '</span>';
  }

  // v5.10.41 — actions only on hover; mini-stat removed from default view.
  // v5.10.45 — added "Move" action; hidden for the 5 IFRS roots since
  // those should never be reparented through the UI.
  var isRoot = ['1','2','3','4','5'].indexOf(String(acc.code)) >= 0;
  var moveBtn = isRoot ? '' :
    '<button title="نقل لقسم آخر" onclick="coaOpenMoveModal(\'' + acc.id + '\')"><i class="fas fa-arrows-up-down-left-right"></i></button>';
  var actionsHtml = '<span class="coa-node-actions" onclick="event.stopPropagation();">' +
    '<button title="عرض الأستاذ" onclick="coaViewLedger(\'' + acc.id + '\')"><i class="fas fa-eye"></i></button>' +
    moveBtn +
  '</span>';

  // Right-side cluster: warn (only if real issue) + balance + actions.
  var rightHtml = '<span class="coa-node-right">' + warnHtml + balHtml + actionsHtml + '</span>';

  // v5.10.45 — IFRS reference chip on the 5 root rows. Tells the user
  // at a glance which IFRS standard governs each branch and signals
  // that the structure follows international convention.
  var ifrsChipHtml = '';
  if (depth === 0) {
    var IFRS_REF = {
      '1': { std: 'IAS 1',   tip: 'IAS 1 — Presentation of Financial Statements (الأصول)' },
      '2': { std: 'IAS 1',   tip: 'IAS 1 — Presentation of Financial Statements (الالتزامات)' },
      '3': { std: 'IAS 1',   tip: 'IAS 1 — Presentation of Financial Statements (حقوق الملكية)' },
      '4': { std: 'IFRS 15', tip: 'IFRS 15 — Revenue from Contracts with Customers' },
      '5': { std: 'IAS 1',   tip: 'IAS 1 — Presentation of Financial Statements (المصروفات)' }
    };
    var ref = IFRS_REF[String(acc.code)];
    if (ref) {
      ifrsChipHtml = '<span class="coa-ifrs-chip" title="' + ref.tip + '">' + ref.std + '</span>';
    }
  }

  var html = '<div class="coa-node" data-id="' + acc.id + '" data-level="' + lvl + '" data-type="' + (acc.type||'') + '">';
  html += '<div class="coa-node-row' + activeClass + '" style="font-weight:' + fontW + ';font-size:' + fontSize + 'px;" onclick="coaSelectNode(\'' + acc.id + '\')" title="' + (acc.nameAr||'').replace(/"/g,'&quot;') + ' — ' + (acc.code||'') + '">';
  html += toggle + icon;
  html += '<span class="coa-node-name">' + (acc.nameAr||'') + '</span>';
  html += ifrsChipHtml;
  html += rightHtml;
  html += '</div>';
  if (isGroup) {
    html += '<div class="coa-node-children' + (openSelf ? ' open' : '') + '" style="margin-inline-start:22px;padding-inline-start:8px;border-inline-start:2px dotted #cbd5e1;">';
    html += children.map(function(c) { return _coaRenderNode(c, false, depth + 1); }).join('');
    html += '</div>';
  }
  html += '</div>';
  return html;
}

// ─── Tree: Toggle expand/collapse ───
// v5.10.45 — also mutate window._coaOpenSet so a tree rebuild later
// (e.g. after deep-repair, account edit, sync) doesn't drop the user's
// expansion state.
document.addEventListener('click', function(e) {
  var toggle = e.target.closest('.coa-node-toggle');
  if (toggle && toggle.querySelector('i')) {
    e.stopPropagation();
    var node = toggle.closest('.coa-node');
    if (!node) return;
    var id = node.getAttribute('data-id');
    var children = node.querySelector('.coa-node-children');
    if (!children) return;
    if (id) {
      if (!window._coaOpenSet) window._coaOpenSet = new Set();
      if (window._coaOpenSet.has(id)) window._coaOpenSet.delete(id);
      else                            window._coaOpenSet.add(id);
      _coaPersistOpenSet();
    }
    children.classList.toggle('open');
    var icon = toggle.querySelector('i');
    icon.className = children.classList.contains('open') ? 'fas fa-chevron-down' : 'fas fa-chevron-left';
  }
});

// ─── Tree: Select node ───
window.coaSelectNode = function(id) {
  _coaSelectedId = id;
  // V5.9.6 — `coaMainContent` only lives on the GL Accounts page. When this
  // function fires from a side-effect path (e.g. Sync-Inventory-GL fired
  // from the inventory-method page), `main` is null and the legacy code
  // crashed with "Cannot set properties of null (setting 'innerHTML')",
  // surfacing a red toast and freezing the inventory-method page on its
  // loading spinner. Guard up front and bail silently — the next visit to
  // the GL Accounts page will pick up `_coaSelectedId` and render then.
  var main = document.getElementById('coaMainContent');
  if (!main) return;

  document.querySelectorAll('.coa-node-row').forEach(r => r.classList.remove('active'));
  var row = document.querySelector('.coa-node[data-id="' + id + '"] > .coa-node-row');
  if (row) row.classList.add('active');
  var acc = _erpAccounts.find(a => a.id === id);
  if (acc) {
    // v5.10.45 — push the ancestor chain into the Set so the path stays
    // open across rebuilds (and survives reload via localStorage).
    if (!window._coaOpenSet) window._coaOpenSet = new Set();
    var parent = acc;
    while (parent && parent.parentId) {
      window._coaOpenSet.add(parent.parentId);
      var parentNode = document.querySelector('.coa-node[data-id="' + parent.parentId + '"] > .coa-node-children');
      if (parentNode) parentNode.classList.add('open');
      parent = _erpAccounts.find(a => a.id === parent.parentId);
    }
    _coaPersistOpenSet();
  }
  var isGroup = _coaIsGroup(id);
  if (isGroup) _coaShowGroup(id, main);
  else         _coaShowAccount(id, main);
};

// ─── Show Group (children as cards) — v5.10.40 redesign ───
// • Rollup balance prominently shown on the END of header (visually left in RTL)
// • Every card always shows its balance (zero is muted, not hidden)
// • Folders have a green nimbus, leaves a blue nimbus — clearer visual rhythm
// • Per-card "promote to folder" / "demote to leaf" toggle for manual control
function _coaShowGroup(id, container) {
  if (!container) return;
  var acc = _erpAccounts.find(a => a.id === id);
  if (!acc) return;
  var children = _coaChildrenOf(id);
  var typeNature   = { asset:'debit', expense:'debit', liability:'credit', equity:'credit', revenue:'credit' };
  var natureLabels = { debit:'مدين', credit:'دائن' };
  var typeLabels   = { asset:'أصول', liability:'التزامات', equity:'حقوق ملكية', revenue:'إيرادات', expense:'مصروفات' };
  var fmt = function(v) { return Number(v||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}); };
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };

  // Rollup of this folder + all descendants (computed_balance from gl_entries)
  var rollup    = _coaRollupBalance(id);
  var rollupCls = rollup > 0 ? 'is-pos' : (rollup < 0 ? 'is-neg' : 'is-zero');
  var withMov   = children.filter(function(c){ return _coaHasMovements ? _coaHasMovements(c.id) : ((c.movementCount||0)>0); }).length;

  var html = '';
  // ── Header: name + code on right, rollup + actions on left ──
  html += '<div class="coa-group-header coa-group-header--v2">';
  html +=   '<div class="coa-group-headline">';
  html +=     '<div class="coa-group-title"><i class="fas fa-folder-open"></i> ' + esc(acc.nameAr || '') + ' <span class="coa-group-code">#' + esc(acc.code) + '</span></div>';
  html +=     '<div class="coa-group-meta">';
  html +=       '<span class="coa-group-meta-pill coa-type-' + (acc.type || 'asset') + '">' + (typeLabels[acc.type] || acc.type || '—') + '</span>';
  html +=       '<span class="coa-group-meta-pill">' + children.length + ' حساب فرعي</span>';
  html +=       '<span class="coa-group-meta-pill">' + withMov + ' بحركات</span>';
  html +=     '</div>';
  html +=   '</div>';
  html +=   '<div class="coa-group-balance ' + rollupCls + '">';
  html +=     '<span class="coa-group-balance__label">الرصيد المجمَّع</span>';
  html +=     '<span class="coa-group-balance__value">' + fmt(rollup) + '</span>';
  html +=   '</div>';
  html +=   '<div class="coa-group-actions">';
  html +=     '<button class="btn btn-sm btn-primary coa-group-add" onclick="erpAddChildAccount(\'' + acc.id + '\',\'' + acc.code + '\')"><i class="fas fa-plus"></i> إضافة حساب</button>';
  html +=     '<button class="btn btn-sm btn-light" onclick="erpEditAccount(\'' + acc.id + '\')" title="تعديل"><i class="fas fa-edit"></i></button>';
  html +=   '</div>';
  html += '</div>';

  // ── Children grid ──
  if (!children.length) {
    html += '<div class="coa-empty coa-empty--v2"><i class="fas fa-inbox"></i><p>هذا الحساب فارغ — أضف أوّل حساب فرعي</p></div>';
    html += '<button class="coa-add-btn" onclick="erpAddChildAccount(\'' + acc.id + '\',\'' + acc.code + '\')"><i class="fas fa-plus-circle"></i> أضف حساب</button>';
  } else {
    html += '<div class="coa-cards coa-cards--v2">';
    children.forEach(function(c) {
      var isFolder = _coaIsGroup(c.id);
      var nature   = typeNature[c.type] || 'debit';
      var bal      = Number(c.balance) || 0;
      var balCls   = bal > 0 ? 'is-pos' : (bal < 0 ? 'is-neg' : 'is-zero');
      var mvCount  = Number(c.movementCount || 0);

      html += '<div class="coa-card coa-card--v2 ' + (isFolder ? 'is-folder' : 'is-leaf') + '" onclick="coaSelectNode(\'' + c.id + '\')">';
      html +=   '<div class="coa-card__nimbus"><i class="fas ' + (isFolder ? 'fa-folder' : 'fa-file-invoice') + '"></i></div>';
      html +=   '<div class="coa-card__body">';
      html +=     '<div class="coa-card__name" title="' + esc(c.nameAr || '') + '">' + esc(c.nameAr || '') + '</div>';
      html +=     '<div class="coa-card__sub">';
      html +=       '<span class="coa-card__code">#' + esc(c.code) + '</span>';
      html +=       '<span class="coa-card-nature ' + nature + '">' + (natureLabels[nature] || '') + '</span>';
      // v5.10.43 — folders show rollup metric (children with movements /
      // total children); leaves show their own movement count. The old
      // logic showed "بدون حركات" on a folder whose children had movements
      // — a confusing contradiction with the visible balance pill.
      if (isFolder) {
        var grand   = _coaChildrenOf(c.id);
        var withMov = grand.filter(function(g){ return _coaHasMovements(g.id); }).length;
        if (withMov > 0) {
          html +=   '<span class="coa-card__mv">' + withMov + '/' + grand.length + ' بحركات</span>';
        } else {
          html +=   '<span class="coa-card__mv coa-card__mv--zero">' + grand.length + ' فرعي بدون حركات</span>';
        }
      } else if (mvCount > 0) {
        html +=     '<span class="coa-card__mv">' + mvCount.toLocaleString('ar-SA') + ' حركة</span>';
      } else {
        html +=     '<span class="coa-card__mv coa-card__mv--zero">بدون حركات</span>';
      }
      html +=     '</div>';
      html +=   '</div>';
      // Always-on balance (zero shown muted)
      html +=   '<div class="coa-card__bal ' + balCls + '">' + fmt(isFolder ? _coaRollupBalance(c.id) : bal) + '</div>';
      html +=   '<button class="coa-card__menu" onclick="event.stopPropagation();coaCardMenu(\'' + c.id + '\',this)" title="خيارات">&#8943;</button>';
      html += '</div>';
    });
    html += '</div>';
    html += '<button class="coa-add-btn" onclick="erpAddChildAccount(\'' + acc.id + '\',\'' + acc.code + '\')"><i class="fas fa-plus-circle"></i> أضف حساب فرعي جديد</button>';
  }
  container.innerHTML = html;
}

// ─── Show Account Detail (transactions) ───
function _coaShowAccount(id, container) {
  if (!container) return; // V5.9.6
  var acc = _erpAccounts.find(a => a.id === id);
  if (!acc) return;
  var fmt = function(v) { return Number(v||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}); };
  var balColor = acc.balance >= 0 ? '#16a34a' : '#ef4444';

  var html = '<div class="coa-acc-header">';
  html += '<div><div class="coa-acc-name"><i class="fas fa-file-alt" style="color:#3b82f6;margin-left:8px;"></i>' + (acc.nameAr||'') + '</div>';
  html += '<span class="coa-acc-code-badge">#' + acc.code + '</span></div>';
  html += '<div class="coa-acc-bal-box"><div class="coa-acc-bal-label">الرصيد</div><div class="coa-acc-bal-val" style="color:' + balColor + ';">' + fmt(acc.balance) + '</div></div>';
  html += '</div>';

  // Action buttons
  html += '<div style="display:flex;gap:6px;margin-bottom:16px;">';
  html += '<button class="btn btn-sm btn-light" onclick="erpEditAccount(\'' + acc.id + '\')" style="border-radius:10px;"><i class="fas fa-edit"></i> تعديل</button>';
  html += '<button class="btn btn-sm btn-light" style="border-radius:10px;color:#ef4444;" onclick="erpDeleteAccount(\'' + acc.id + '\',\'' + acc.code + '\',\'' + (acc.nameAr||'').replace(/'/g,'') + '\')"><i class="fas fa-trash"></i> حذف</button>';
  html += '<button class="coa-add-btn" onclick="erpAddChildAccount(\'' + acc.id + '\',\'' + acc.code + '\')"><i class="fas fa-plus-circle"></i> إضافة فرعي</button>';
  html += '</div>';

  // Transactions table
  html += '<h4 style="font-size:15px;font-weight:800;color:#1e293b;margin-bottom:10px;"><i class="fas fa-list-alt" style="color:#3b82f6;margin-left:6px;"></i> حركات الحساب</h4>';
  html += '<div id="coaTransLoading" style="text-align:center;padding:20px;color:#94a3b8;"><i class="fas fa-spinner fa-spin"></i> جاري التحميل...</div>';
  html += '<div id="coaTransTable"></div>';
  container.innerHTML = html;

  // Load transactions for this account
  _coaLoadTransactions(id);
}

function _coaLoadTransactions(accountId) {
  // Use dedicated account ledger endpoint — queries gl_entries directly by account_id/code
  window._apiBridge.withSuccessHandler(function(res) {
    var loadingEl = document.getElementById('coaTransLoading');
    if (loadingEl) loadingEl.style.display = 'none';
    var tableEl = document.getElementById('coaTransTable');
    if (!tableEl) return;
    var fmt = function(v) { return Number(v||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}); };

    var rows = (res && res.ledger) || [];
    if (!rows.length) {
      tableEl.innerHTML = '<div class="coa-empty"><i class="fas fa-inbox"></i><p>لا توجد حركات لهذا الحساب</p></div>';
      return;
    }

    var refLabels = { manual: 'يدوي', opening: 'افتتاحي', sale: 'مبيعات', purchase: 'مشتريات', custody: 'عهدة', inventory: 'مخزون' };
    var refColors = { manual: '#3b82f6', opening: '#7c3aed', sale: '#10b981', purchase: '#f59e0b', custody: '#ec4899', inventory: '#06b6d4' };

    var html = '<div style="overflow-x:auto;border-radius:12px;border:1px solid #e2e8f0;"><table style="width:100%;border-collapse:collapse;font-size:13px;">';
    html += '<thead><tr style="background:#0f172a;color:#fff;"><th style="padding:10px 12px;">التاريخ</th><th>القيد</th><th>النوع</th><th>البيان</th><th>مدين</th><th>دائن</th><th>الرصيد</th></tr></thead><tbody>';
    rows.forEach(function(r) {
      var dt = '';
      try { dt = new Date(r.journalDate).toLocaleDateString('en-GB'); } catch(e) {}
      var balColor = r.balance >= 0 ? '#16a34a' : '#ef4444';
      var refType = r.referenceType || 'manual';
      var typeBadge = '<span style="display:inline-block;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;background:' + (refColors[refType]||'#94a3b8') + '15;color:' + (refColors[refType]||'#94a3b8') + ';">' + (refLabels[refType]||refType) + '</span>';
      html += '<tr style="cursor:pointer;border-bottom:1px solid #f1f5f9;" onclick="erpViewJournal(\'' + r.journalId + '\')" onmouseover="this.style.background=\'#f8fafc\'" onmouseout="this.style.background=\'\'">';
      html += '<td style="padding:8px 12px;">' + dt + '</td>';
      html += '<td><code style="color:#3b82f6;font-weight:700;">' + (r.journalNumber||'') + '</code></td>';
      html += '<td>' + typeBadge + '</td>';
      html += '<td style="max-width:200px;overflow:hidden;text-overflow:ellipsis;">' + (r.journalDesc || r.entryDesc || '') + '</td>';
      html += '<td style="font-weight:700;color:#16a34a;">' + (r.debit ? fmt(r.debit) : '') + '</td>';
      html += '<td style="font-weight:700;color:#ef4444;">' + (r.credit ? fmt(r.credit) : '') + '</td>';
      html += '<td style="font-weight:800;color:' + balColor + ';">' + fmt(r.balance) + '</td>';
      html += '</tr>';
    });
    html += '</tbody></table></div>';
    tableEl.innerHTML = html;
  }).getAccountLedger(accountId);
}

// ─── Card context menu ───
// v5.10.40 — proper popover replacing the old confirm() blocking dialog.
// Adds "Promote to folder" / "Demote to leaf" so users control the
// folder structure manually (instead of every account auto-becoming a
// folder the moment it has children).
window.coaCardMenu = function(id, el) {
  var acc = _erpAccounts.find(a => a.id === id);
  if (!acc) return;
  // Close any existing popover
  var prior = document.getElementById('coaCardPopover');
  if (prior) prior.remove();

  var isFolder = !!acc.isFolder || _coaIsGroup(id);
  var hasChildren = _coaIsGroup(id);

  var pop = document.createElement('div');
  pop.id = 'coaCardPopover';
  pop.className = 'coa-card-popover';
  pop.innerHTML =
    '<button class="coa-card-popover__item" onclick="event.stopPropagation();erpEditAccount(\'' + id + '\');coaClosePopover();">' +
      '<i class="fas fa-pen"></i><span>تعديل البيانات</span>' +
    '</button>' +
    (isFolder
      ? (hasChildren
          ? '<button class="coa-card-popover__item" disabled title="لا يمكن إلغاء الفولدر — احذف الأبناء أولاً"><i class="fas fa-folder-minus"></i><span>تحويل لورقة (يحتاج لا أبناء)</span></button>'
          : '<button class="coa-card-popover__item" onclick="event.stopPropagation();coaToggleFolder(\'' + id + '\',false);coaClosePopover();"><i class="fas fa-folder-minus"></i><span>تحويل إلى ورقة</span></button>')
      : '<button class="coa-card-popover__item" onclick="event.stopPropagation();coaToggleFolder(\'' + id + '\',true);coaClosePopover();">' +
          '<i class="fas fa-folder-plus"></i><span>تحويل إلى مجلد</span>' +
        '</button>'
    ) +
    '<button class="coa-card-popover__item" onclick="event.stopPropagation();erpAddChildAccount(\'' + id + '\',\'' + acc.code + '\');coaClosePopover();">' +
      '<i class="fas fa-plus"></i><span>إضافة حساب فرعي</span>' +
    '</button>' +
    '<div class="coa-card-popover__divider"></div>' +
    '<button class="coa-card-popover__item coa-card-popover__item--danger" onclick="event.stopPropagation();coaConfirmDelete(\'' + id + '\',\'' + acc.code + '\',\'' + (acc.nameAr||'').replace(/[\\\']/g,'') + '\');coaClosePopover();">' +
      '<i class="fas fa-trash"></i><span>حذف الحساب</span>' +
    '</button>';

  // Position relative to the trigger element
  document.body.appendChild(pop);
  if (el) {
    var rect = el.getBoundingClientRect();
    pop.style.position = 'fixed';
    pop.style.top  = (rect.bottom + 4) + 'px';
    // RTL: anchor to the trigger's right edge so the popover opens leftward
    pop.style.right = (window.innerWidth - rect.right) + 'px';
  }
  // Close on outside click
  setTimeout(function(){
    document.addEventListener('click', function _off(e){
      if (!pop.contains(e.target)) { pop.remove(); document.removeEventListener('click', _off); }
    });
  }, 0);
};

window.coaClosePopover = function() {
  var p = document.getElementById('coaCardPopover');
  if (p) p.remove();
};

// v5.10.40 — toggle is_folder flag on an account. Refreshes the tree
// and currently-shown group view.
window.coaToggleFolder = function(id, makeFolder) {
  var token = localStorage.getItem('pos_token') || '';
  fetch('/api/erp/gl/accounts/' + encodeURIComponent(id) + '/folder', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ isFolder: !!makeFolder })
  }).then(function(r){ return r.json(); }).then(function(j){
    if (!j || !j.success) {
      if (typeof showToast === 'function') showToast(j && j.error || 'فشل التحديث', true);
      return;
    }
    if (typeof showToast === 'function') showToast(makeFolder ? 'تم تحويله إلى مجلد' : 'تم تحويله إلى ورقة');
    if (typeof erpLoadAccountsList_ === 'function') erpLoadAccountsList_();
  }).catch(function(e){
    if (typeof showToast === 'function') showToast('خطأ: ' + (e && e.message || ''), true);
  });
};

// Keep the old delete confirmation flow but stripped of the popup chain
window.coaConfirmDelete = function(id, code, name) {
  if (confirm('حذف "' + code + ' — ' + name + '"؟')) erpDeleteAccount(id, code, name);
};

// ─── Tree search filter ───
window.coaFilterTree = function(query) {
  var q = (query||'').toLowerCase();
  document.querySelectorAll('.coa-node').forEach(function(node) {
    var name = (node.querySelector('.coa-node-name')||{}).textContent || '';
    if (!q || name.toLowerCase().indexOf(q) >= 0) {
      node.style.display = '';
      // Also expand parents
      var parent = node.parentElement;
      while (parent && parent.classList) {
        if (parent.classList.contains('coa-node-children')) parent.classList.add('open');
        parent = parent.parentElement;
      }
    } else {
      // Only hide if no matching children
      var hasMatch = node.querySelector('.coa-node-name') && Array.from(node.querySelectorAll('.coa-node-name')).some(function(n) { return n.textContent.toLowerCase().indexOf(q) >= 0; });
      node.style.display = hasMatch ? '' : 'none';
    }
  });
};

// ═══════════════════════════════════════════════════════════════════════
// v5.10.35 — COA diagnose, repair, suggestions
// ═══════════════════════════════════════════════════════════════════════
window.coaOpenDiagnose = function() {
  var modal = document.getElementById('coaDiagModal');
  var body  = document.getElementById('coaDiagBody');
  if (!modal || !body) return;
  body.innerHTML = '<div class="coa-empty" style="padding:40px;"><i class="fas fa-spinner fa-spin"></i><p>جاري التشخيص...</p></div>';
  modal.classList.add('show'); modal.style.display = '';
  var token = localStorage.getItem('pos_token') || '';
  fetch('/api/erp/gl/diagnose', { headers: { 'Authorization': 'Bearer ' + token } })
    .then(function(r){ return r.json(); })
    .then(function(j){
      window._coaDiagSnap = j;
      _coaRenderDiagnose(j);
      _coaUpdateDiagBadge(j);
    })
    .catch(function(e){
      body.innerHTML = '<div class="coa-empty" style="color:#ef4444;padding:30px;">' + (e && e.message || 'تعذّر التحميل') + '</div>';
    });
};
window.coaCloseDiagnose = function() {
  var m = document.getElementById('coaDiagModal'); if (m) { m.classList.remove('show'); m.style.display = 'none'; }
};

function _coaUpdateDiagBadge(j) {
  var badge = document.getElementById('coaDiagBadge');
  if (!badge) return;
  var n = (j && j.summary && j.summary.issuesCount) || 0;
  badge.textContent = n;
  badge.style.display = n > 0 ? 'inline-flex' : 'none';
  badge.classList.toggle('coa-action-badge--healthy', n === 0);
}

function _coaRenderDiagnose(j) {
  var body = document.getElementById('coaDiagBody');
  if (!body) return;
  if (!j || !j.summary) { body.innerHTML = '<div class="coa-empty">لا بيانات</div>'; return; }
  var s = j.summary, issues = j.issues || {};
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };
  var fmt = function(n){ return Number(n||0).toLocaleString('ar-SA'); };

  // Top summary card
  var healthClass = s.healthy ? 'coa-diag-summary--healthy' : 'coa-diag-summary--issues';
  var healthIcon  = s.healthy ? 'fa-check-circle' : 'fa-triangle-exclamation';
  var headHtml =
    '<div class="coa-diag-summary ' + healthClass + '">' +
      '<i class="fas ' + healthIcon + '" style="font-size:28px;"></i>' +
      '<div>' +
        '<div style="font-size:18px;font-weight:900;">' + (s.healthy ? 'الشجرة سليمة' : (fmt(s.issuesCount) + ' مشكلة بحاجة لمراجعة')) + '</div>' +
        '<div style="font-size:12px;color:#475569;">' + fmt(s.accounts) + ' حساب · ' + fmt(s.validEntries) + ' قيد · ' + fmt(s.nullEntries) + ' قيد بدون حساب</div>' +
      '</div>' +
      '<div style="margin-inline-start:auto;">' +
        '<button class="wo-btn wo-btn-secondary" onclick="coaRunAutoRepair()"><i class="fas fa-wand-magic-sparkles"></i><span>إصلاح شامل</span></button>' +
      '</div>' +
    '</div>';

  // v5.10.39 — Three groups (tabs): critical / structural / balance
  var GROUP_DEFS = {
    critical: {
      label: 'حرجة',
      icon: 'fa-fire',
      keys: ['balanceWithoutEntries', 'nameVsPlacementMismatch', 'codeTypeMismatch',
             'cycles', 'unbalancedJournals', 'orphanEntries']
    },
    structural: {
      label: 'هيكلية',
      icon: 'fa-sitemap',
      keys: ['orphans', 'typeMismatch', 'duplicateCodes', 'levelMismatch', 'missingCoreAccounts']
    }
  };
  var groupCounts = { all: 0, critical: 0, structural: 0 };
  Object.keys(GROUP_DEFS).forEach(function(g){
    GROUP_DEFS[g].keys.forEach(function(k){
      var n = (issues[k] || []).length;
      groupCounts[g] += n; groupCounts.all += n;
    });
  });

  var activeTab = window._coaDiagActiveTab || 'critical';
  if (groupCounts[activeTab] === 0 && groupCounts.all > 0) {
    activeTab = groupCounts.critical > 0 ? 'critical' : 'structural';
  }

  var tabsHtml = '<div class="coa-diag-tabs">' +
    '<button class="coa-diag-tab' + (activeTab==='all' ? ' is-active' : '') + '" onclick="coaSetDiagTab(\'all\')">' +
      '<i class="fas fa-list"></i> الكل <span class="coa-diag-tab__count">' + groupCounts.all + '</span>' +
    '</button>' +
    '<button class="coa-diag-tab coa-diag-tab--critical' + (activeTab==='critical' ? ' is-active' : '') + '" onclick="coaSetDiagTab(\'critical\')">' +
      '<i class="fas fa-fire"></i> حرجة <span class="coa-diag-tab__count">' + groupCounts.critical + '</span>' +
    '</button>' +
    '<button class="coa-diag-tab' + (activeTab==='structural' ? ' is-active' : '') + '" onclick="coaSetDiagTab(\'structural\')">' +
      '<i class="fas fa-sitemap"></i> هيكلية <span class="coa-diag-tab__count">' + groupCounts.structural + '</span>' +
    '</button>' +
  '</div>';

  // Issue categories — all metadata in one place; the active tab decides which to show.
  var CATS = {
    rootCodeMismatch:        { icon:'fa-diagram-project',  color:'#dc2626', label:'الجذر الفعلي لا يطابق الكود', group:'critical' },
    balanceWithoutEntries:   { icon:'fa-ghost',            color:'#dc2626', label:'رصيد بدون قيود فعلية', group:'critical' },
    nameVsPlacementMismatch: { icon:'fa-folder-tree',      color:'#dc2626', label:'الاسم لا يطابق المكان في الشجرة', group:'critical' },
    codeTypeMismatch:        { icon:'fa-tags',             color:'#ea580c', label:'النوع لا يطابق الكود', group:'critical' },
    cycles:                  { icon:'fa-rotate',           color:'#dc2626', label:'حلقات في الشجرة (cycle)', group:'critical' },
    unbalancedJournals:      { icon:'fa-scale-unbalanced', color:'#dc2626', label:'قيود غير متوازنة', group:'critical' },
    orphanEntries:           { icon:'fa-link-slash',       color:'#dc2626', label:'قيود تشير لحساب محذوف', group:'critical' },
    orphans:                 { icon:'fa-unlink',           color:'#b45309', label:'حسابات يتيمة (parent محذوف)', group:'structural' },
    typeMismatch:            { icon:'fa-arrows-rotate',    color:'#b45309', label:'نوع لا يطابق نوع الأب', group:'structural' },
    duplicateCodes:          { icon:'fa-copy',             color:'#b45309', label:'أكواد مكرَّرة', group:'structural' },
    levelMismatch:           { icon:'fa-layer-group',      color:'#0e7490', label:'مستوى مختلف عن العمق الفعلي', group:'structural' },
    missingCoreAccounts:     { icon:'fa-circle-question',  color:'#7c3aed', label:'حسابات أساسية ناقصة', group:'structural' }
  };

  // For each category in the active tab, render a card with up to 12 rows.
  var sectionsHtml = '';
  Object.keys(CATS).forEach(function(key){
    var cat = CATS[key];
    if (activeTab !== 'all' && cat.group !== activeTab) return;
    var arr = issues[key] || [];
    if (!arr.length) return;

    // v5.10.42 — sort each category's items by code for predictable display.
    arr = arr.slice().sort(function(a, b){
      var ca = String(a && a.code || ''), cb = String(b && b.code || '');
      return ca.localeCompare(cb);
    });

    sectionsHtml += '<div class="coa-diag-cat">' +
      '<div class="coa-diag-cat__head" style="border-color:' + cat.color + '33;">' +
        '<i class="fas ' + cat.icon + '" style="color:' + cat.color + ';"></i>' +
        '<span class="coa-diag-cat__label">' + cat.label + '</span>' +
        '<span class="coa-diag-cat__count" style="background:' + cat.color + '22;color:' + cat.color + ';">' + arr.length + '</span>' +
        // v5.10.47 — per-category fix now refreshes the diagnose modal
        // in place instead of triggering the full repair-report modal.
        // Resolved categories disappear immediately; the user stays on
        // this screen to keep working through remaining issues.
        '<button class="coa-diag-cat__fix-btn" onclick="event.stopPropagation();_coaFixAllAndRefreshDiagnose(this);" title="يُشغِّل الإصلاح الشامل ويُحدِّث القائمة فوريًا">' +
          '<i class="fas fa-wand-magic-sparkles"></i> إصلاح' +
        '</button>' +
      '</div>' +
      '<div class="coa-diag-cat__body">';

    arr.slice(0, 12).forEach(function(item){
      var code = '', info = '', actionHtml = '', accId = item.id || '';
      if (key === 'orphans') {
        code = item.code || '';
        info = '<b>' + esc(item.name_ar || '') + '</b> <span class="coa-diag-arrow">→</span> parent مفقود';
      } else if (key === 'typeMismatch') {
        code = item.code || '';
        info = '<b>' + esc(item.name_ar || '') + '</b> · النوع: <span class="coa-diag-from">' + esc(item.child_type || '?') + '</span>' +
               '<span class="coa-diag-arrow">في</span><b>' + (item.parent_code || '') + '</b> (' + esc(item.parent_type || '?') + ')';
      } else if (key === 'duplicateCodes') {
        code = item.code || '';
        info = 'مستخدم في <b>' + item.n + '</b> حساب';
      } else if (key === 'unbalancedJournals') {
        code = item.journal_number || item.id || '';
        info = 'مدين ' + (Number(item.total_debit)||0).toFixed(2) + ' <span class="coa-diag-arrow">≠</span> دائن ' + (Number(item.total_credit)||0).toFixed(2);
      } else if (key === 'orphanEntries') {
        code = item.account_code || '—';
        info = '<b>' + esc(item.account_name || '') + '</b> · حساب محذوف';
      } else if (key === 'missingCoreAccounts') {
        code = String(item);
        info = 'حساب أساسي مفقود';
      } else if (key === 'levelMismatch') {
        code = item.code || '';
        info = '<b>' + esc(item.name_ar || '') + '</b> · مستوى محفوظ <span class="coa-diag-from">' + item.storedLevel + '</span> <span class="coa-diag-arrow">→</span> المحسوب <span class="coa-diag-to">' + item.computedLevel + '</span>';
      } else if (key === 'cycles') {
        code = item.code || '';
        info = '<b>' + esc(item.name_ar || '') + '</b> · حلقة في الشجرة';
      } else if (key === 'codeTypeMismatch') {
        code = item.code || '';
        info = '<b>' + esc(item.name_ar || '') + '</b> · النوع <span class="coa-diag-from">' + esc(item.type || '—') + '</span> لا يطابق جذر الكود';
      } else if (key === 'balanceWithoutEntries') {
        code = item.code || '';
        info = '<b>' + esc(item.name_ar || '') + '</b> · رصيد ' + Number(item.balance||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}) + ' بدون قيد فعلي';
      } else if (key === 'nameVsPlacementMismatch') {
        code = item.code || '';
        info = '<b>' + esc(item.name_ar || '') + '</b> · في <span class="coa-diag-from">' + esc(item.actualRootCode || '?') + '</span> <span class="coa-diag-arrow">→</span> المتوقع <span class="coa-diag-to">' + esc(item.expectedLabel || item.expectedParentCode || '?') + '</span>';
      } else if (key === 'rootCodeMismatch') {
        code = item.code || '';
        info = '<b>' + esc(item.name_ar || '') + '</b> · يبدأ بـ <span class="coa-diag-to">' + esc(item.expectedRootCode || '?') + '</span> لكنه تحت جذر <span class="coa-diag-from">' + esc(item.actualRootCode || '?') + '</span>';
      }

      // Click takes the user to the account in the tree (when we have an id)
      var rowAttrs = '';
      if (accId) {
        rowAttrs = ' class="coa-diag-row coa-diag-row--clickable" onclick="coaJumpToAccount(\'' + esc(accId) + '\')"';
      } else {
        rowAttrs = ' class="coa-diag-row"';
      }

      sectionsHtml += '<div' + rowAttrs + '>' +
        '<span class="coa-diag-row__code">' + esc(code) + '</span>' +
        '<span class="coa-diag-row__info">' + info + '</span>' +
        actionHtml +
      '</div>';
    });
    if (arr.length > 12) {
      sectionsHtml += '<div class="coa-diag-row coa-diag-row--more">… و' + (arr.length - 12) + ' بند آخر</div>';
    }
    sectionsHtml += '</div></div>';
  });

  // v5.10.45 — full-clear empty state when ALL groups are healthy.
  // Per-tab empty state still applies if only the active tab is clean.
  if (groupCounts.all === 0) {
    sectionsHtml =
      '<div class="coa-diag-empty-state">' +
        '<i class="fas fa-circle-check" style="color:#16a34a;font-size:54px;"></i>' +
        '<h3>الشجرة سليمة بنسبة 100%</h3>' +
        '<p>لا توجد مشاكل هيكلية أو حرجة أو في الأرصدة. آخر فحص قبل ثوانٍ.</p>' +
        '<div class="coa-diag-empty-state__meta">' +
          fmt(s.accounts) + ' حساب · ' + fmt(s.validEntries) + ' قيد · 0 مشكلة' +
        '</div>' +
      '</div>';
  } else if (!sectionsHtml) {
    sectionsHtml = '<div class="coa-empty" style="padding:30px;color:#16a34a;"><i class="fas fa-shield-heart" style="font-size:32px;"></i><p style="margin-top:10px;">لا توجد مشاكل في هذا التصنيف. تابوبات أخرى قد تحتوي على مشاكل.</p></div>';
  }

  body.innerHTML = headHtml + tabsHtml + sectionsHtml;
}

// v5.10.39 — switch active diagnose tab without re-fetching
window.coaSetDiagTab = function(tab) {
  window._coaDiagActiveTab = tab;
  if (window._coaDiagSnap) _coaRenderDiagnose(window._coaDiagSnap);
};

// v5.10.39 — jump to an account in the tree from any diagnose row
window.coaJumpToAccount = function(accId) {
  if (!accId) return;
  // Close diagnose modal so the user can see the tree
  var m = document.getElementById('coaDiagModal');
  if (m) { m.classList.remove('show'); m.style.display = 'none'; }
  // Select and scroll to it
  if (typeof coaSelectNode === 'function') coaSelectNode(accId);
  setTimeout(function(){
    var el = document.querySelector('.coa-node[data-id="' + accId.replace(/"/g,'\\"') + '"]');
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      el.classList.add('coa-node--flash');
      setTimeout(function(){ el.classList.remove('coa-node--flash'); }, 1500);
    }
  }, 50);
};

// v5.10.42 — Full-screen overlay during repair so the user can SEE work
// happening, plus modal-based error reporting (a toast disappears in 3
// seconds — for a multi-second DB operation that's invisible).
window.coaRunAutoRepair = function() {
  if (!confirm('سيتم تشغيل إصلاح شامل لشجرة الحسابات:\n\n' +
    '• إعادة تصنيف الحسابات بالاسم (بنوك، مخزون، …)\n' +
    '• نقل الحسابات بكود خاطئ إلى جذرها الصحيح\n' +
    '• توحيد النوع مع جذر الكود\n' +
    '• إصلاح اليتامى وإعادة احتساب المستويات\n' +
    '• إعادة احتساب كل الأرصدة من قيود اليومية الفعلية\n\n' +
    'يتم كل ذلك في معاملة واحدة. هل تريد المتابعة؟')) return;

  _coaShowRepairOverlay('جاري تنفيذ الإصلاح الشامل...');
  var token = localStorage.getItem('pos_token') || '';
  fetch('/api/erp/gl/deep-repair', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' }
  })
    .then(function(r){ return r.json(); })
    .then(function(j){
      _coaHideRepairOverlay();
      if (!j || !j.success) {
        _coaShowRepairError((j && j.error) || 'استجابة غير متوقعة من الخادم');
        return;
      }
      // v5.10.44 — if the verification query returned remaining
      // misplacements, surface them prominently. Otherwise show the
      // normal success report. Either way, force a fresh reload below.
      if (j.stillMisplaced && j.stillMisplaced.length) {
        _coaShowMisplacementWarning(j);
      } else {
        _coaShowRepairReport(j);
      }
      // v5.10.44 — bypass any HTTP-level cache so the tree definitely
      // reflects the post-repair DB state, not a stale snapshot.
      _erpReloadAccountsCacheBust();
      // Refresh the diagnose snapshot so warning icons in the tree clear out.
      _coaRefreshDiagSnap();
      var diagModal = document.getElementById('coaDiagModal');
      if (diagModal && (diagModal.classList.contains('show') || diagModal.style.display === 'flex')) {
        setTimeout(function(){ coaOpenDiagnose(); }, 400);
      }
    })
    .catch(function(e){
      _coaHideRepairOverlay();
      _coaShowRepairError((e && e.message) || 'تعذّر الاتصال بالخادم');
    });
};

function _coaShowRepairOverlay(msg) {
  _coaHideRepairOverlay();
  var ov = document.createElement('div');
  ov.id = 'coaRepairOverlay';
  ov.className = 'coa-repair-overlay';
  ov.innerHTML =
    '<div class="coa-repair-overlay__panel">' +
      '<div class="coa-repair-overlay__spinner"></div>' +
      '<div class="coa-repair-overlay__msg">' + (msg || 'جاري المعالجة...') + '</div>' +
      '<div class="coa-repair-overlay__hint">يتم تنفيذ كل خطوات الإصلاح في معاملة واحدة. الرجاء عدم إغلاق الصفحة.</div>' +
    '</div>';
  document.body.appendChild(ov);
}
function _coaHideRepairOverlay() {
  var ov = document.getElementById('coaRepairOverlay');
  if (ov) ov.remove();
}
function _coaShowRepairError(message) {
  var prior = document.getElementById('coaRepairErrorModal');
  if (prior) prior.remove();
  var html =
    '<div class="modal show" id="coaRepairErrorModal" style="display:flex;align-items:flex-start;justify-content:center;z-index:10001;" onclick="if(event.target===this)this.remove();">' +
      '<div class="modal-content" style="max-width:560px;width:96%;margin-top:60px;" onclick="event.stopPropagation();">' +
        '<div class="modal-title">' +
          '<i class="fas fa-circle-exclamation" style="color:#dc2626;"></i>' +
          '<span>فشل الإصلاح الشامل</span>' +
          '<button class="modal-close" onclick="document.getElementById(\'coaRepairErrorModal\').remove()">&times;</button>' +
        '</div>' +
        '<div style="padding:18px 20px;">' +
          '<div style="padding:14px;background:#fef2f2;border:1px solid #fecaca;border-radius:10px;font-size:13px;color:#7f1d1d;">' +
            '<i class="fas fa-triangle-exclamation"></i> ' +
            String(message || 'خطأ غير معروف').replace(/[<>]/g,'') +
          '</div>' +
          '<p style="font-size:12.5px;color:#475569;margin-top:12px;line-height:1.7;">' +
            'لم يتم تطبيق أي تغيير — كل عمليات الإصلاح تتم داخل معاملة قاعدة بيانات واحدة، فإذا فشلت أي خطوة يتم التراجع عن الجميع. ' +
            'يمكنك إعادة المحاولة، أو فتح "تشخيص" لرؤية الفئات بمزيد من التفصيل.' +
          '</p>' +
          '<div style="margin-top:16px;display:flex;gap:8px;justify-content:flex-end;">' +
            '<button class="wo-btn wo-btn-ghost" onclick="document.getElementById(\'coaRepairErrorModal\').remove();coaOpenDiagnose();">عرض التشخيص</button>' +
            '<button class="wo-btn wo-btn-primary" onclick="document.getElementById(\'coaRepairErrorModal\').remove();coaRunAutoRepair();">إعادة المحاولة</button>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
}

// v5.10.44 — bypass any HTTP-level cache by hitting the accounts endpoint
// with a timestamp query param. Replaces erpLoadAccountsList_() in the
// post-repair flow because the bridge has no cache-bust knob.
function _erpReloadAccountsCacheBust() {
  var token = localStorage.getItem('pos_token') || '';
  fetch('/api/erp/gl/accounts?_=' + Date.now(), {
    headers: { 'Authorization': 'Bearer ' + token }
  })
    .then(function(r){ return r.json(); })
    .then(function(list){
      _erpAccounts = (list || []).map(function(a){
        return {
          id: a.id, code: a.code, nameAr: a.nameAr, nameEn: a.nameEn,
          type: a.type, parentId: a.parentId, level: Number(a.level) || 1,
          isActive: a.isActive,
          isFolder: !!a.isFolder,
          displayOrder: a.displayOrder == null ? null : Number(a.displayOrder),
          balance: Number(a.balance) || 0,
          storedBalance: Number(a.storedBalance) || 0,
          movementCount: Number(a.movementCount) || 0
        };
      });
      _erpAccounts.sort(function(a,b){
        var ao = a.displayOrder == null ? 99999 : Number(a.displayOrder);
        var bo = b.displayOrder == null ? 99999 : Number(b.displayOrder);
        if (ao !== bo) return ao - bo;
        return String(a.code||'').localeCompare(String(b.code||''));
      });
      if (typeof _coaBuildTree === 'function') _coaBuildTree();
      if (_coaSelectedId && typeof coaSelectNode === 'function') coaSelectNode(_coaSelectedId);
    })
    .catch(function(e){ console.error('[v5.10.44] cache-bust reload failed:', e); });
}

// v5.10.44 — explicit warning modal that lists the accounts the
// deep-repair pipeline COULD NOT relocate. The user previously got a
// fake success toast even when accounts like 41 stayed under root 5;
// this surfaces the truth so they can act or escalate.
function _coaShowMisplacementWarning(j) {
  var prior = document.getElementById('coaMisplacementModal');
  if (prior) prior.remove();
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };
  var list = j.stillMisplaced || [];
  var rows = list.map(function(m){
    return '<tr>' +
      '<td><strong>' + esc(m.code) + '</strong></td>' +
      '<td>' + esc(m.name) + '</td>' +
      '<td><code>' + esc(m.expected) + '</code></td>' +
      '<td><code>' + esc(m.actual || 'orphan') + '</code></td>' +
    '</tr>';
  }).join('');
  var moved = (j.bruteForcedTopology || []).length + (j.rootFixed || []).length;
  var html =
    '<div class="modal show" id="coaMisplacementModal" style="display:flex;align-items:flex-start;justify-content:center;z-index:10001;" onclick="if(event.target===this)this.remove();">' +
      '<div class="modal-content" style="max-width:760px;width:96%;margin-top:48px;" onclick="event.stopPropagation();">' +
        '<div class="modal-title">' +
          '<i class="fas fa-triangle-exclamation" style="color:#d97706;"></i>' +
          '<span>تحذير — بعض الحسابات لم تُنقَل</span>' +
          '<button class="modal-close" onclick="document.getElementById(\'coaMisplacementModal\').remove()">&times;</button>' +
        '</div>' +
        '<div style="padding:18px 22px 22px;">' +
          '<div style="padding:14px;background:#fffbeb;border:1px solid #fde68a;border-radius:10px;font-size:13px;color:#78350f;line-height:1.7;">' +
            '<strong>' + list.length + '</strong> حساب لا يزال في موقع خاطئ في الشجرة بعد تنفيذ كل خطوات الإصلاح. ' +
            'تم نقل <strong>' + moved + '</strong> حساب آخر بنجاح. ' +
            (j.missingRoots && j.missingRoots.length ? '<br/><strong>سبب جذري:</strong> الجذور التالية مفقودة من قاعدة البيانات: <code>' + esc(j.missingRoots.join(', ')) + '</code> — لذلك تعذَّر إعادة الإسناد.' : '') +
          '</div>' +
          '<table style="width:100%;border-collapse:collapse;margin-top:16px;font-size:12.5px;">' +
            '<thead><tr style="background:#f1f5f9;">' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">الكود</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">الاسم</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">الجذر المتوقَّع</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">الجذر الفعلي</th>' +
            '</tr></thead>' +
            '<tbody>' + rows + '</tbody>' +
          '</table>' +
          '<p style="font-size:12px;color:#64748b;margin-top:14px;line-height:1.7;">' +
            'انسخ هذه القائمة وأرسلها للدعم الفني، أو افتح "تشخيص" لرؤية تفاصيل الفئات الأخرى. ' +
            'تم تسجيل كل المحاولات والإخفاقات في سجل الخادم (Railway logs).' +
          '</p>' +
          '<div style="margin-top:14px;display:flex;gap:8px;justify-content:flex-end;">' +
            '<button class="wo-btn wo-btn-ghost" onclick="document.getElementById(\'coaMisplacementModal\').remove();coaOpenDiagnose();">عرض التشخيص الكامل</button>' +
            '<button class="wo-btn wo-btn-primary" onclick="document.getElementById(\'coaMisplacementModal\').remove();">إغلاق</button>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
}

// v5.10.47 — searchable combobox: replaces a native <select> with a real
// type-ahead dropdown that filters by code OR name. Used by both the
// account create/edit modal and the move modal. The hidden <input type="hidden">
// keeps the value so existing form readers (document.getElementById(id).value)
// keep working without any caller changes.
//
// opts = {
//   id:           hidden input id (the one form code reads)
//   placeholder:  search box placeholder
//   value:        currently-selected option value (optional)
//   options:      array of { value, label, sublabel?, disabled? }
//   onChange:     fired with (newValue) after user picks an option
// }
function _coaMountSearchableSelect(targetEl, opts) {
  if (!targetEl) return;
  opts = opts || {};
  var options = (opts.options || []).slice();
  var hiddenId = opts.id || ('coaSel_' + Math.random().toString(36).slice(2, 8));
  var initialValue = opts.value || '';
  var selectedOpt = options.find(function(o){ return String(o.value) === String(initialValue); });
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };

  var displayText = selectedOpt ? selectedOpt.label : (opts.placeholder || '— اختر —');

  targetEl.innerHTML =
    '<div class="coa-sel" data-open="0">' +
      '<input type="hidden" id="' + hiddenId + '" value="' + esc(initialValue) + '">' +
      '<button type="button" class="coa-sel__trigger" tabindex="0">' +
        '<span class="coa-sel__current' + (selectedOpt ? '' : ' is-placeholder') + '">' + esc(displayText) + '</span>' +
        '<i class="fas fa-chevron-down coa-sel__chev"></i>' +
      '</button>' +
      '<div class="coa-sel__panel">' +
        '<div class="coa-sel__searchbox">' +
          '<i class="fas fa-search"></i>' +
          '<input type="text" class="coa-sel__search" placeholder="ابحث بالكود أو الاسم..." autocomplete="off">' +
        '</div>' +
        '<div class="coa-sel__list" role="listbox"></div>' +
        '<div class="coa-sel__footer"><span class="coa-sel__count">' + options.length + ' نتيجة</span></div>' +
      '</div>' +
    '</div>';

  var root      = targetEl.querySelector('.coa-sel');
  var hidden    = targetEl.querySelector('#' + hiddenId);
  var trigger   = targetEl.querySelector('.coa-sel__trigger');
  var current   = targetEl.querySelector('.coa-sel__current');
  var panel     = targetEl.querySelector('.coa-sel__panel');
  var searchInp = targetEl.querySelector('.coa-sel__search');
  var list      = targetEl.querySelector('.coa-sel__list');
  var countEl   = targetEl.querySelector('.coa-sel__count');
  var activeIdx = -1;

  function renderList(filterText) {
    var ft = String(filterText || '').trim().toLowerCase();
    var visible = options.map(function(o, i){ return { o: o, i: i }; }).filter(function(p){
      if (!ft) return true;
      var hay = (String(p.o.label) + ' ' + String(p.o.sublabel || '')).toLowerCase();
      return hay.indexOf(ft) >= 0;
    });
    if (!visible.length) {
      list.innerHTML = '<div class="coa-sel__empty">لا توجد نتائج لـ "' + esc(ft) + '"</div>';
      countEl.textContent = '0 نتيجة';
      return;
    }
    countEl.textContent = visible.length + ' نتيجة';
    list.innerHTML = visible.map(function(p, vi){
      var isSel = String(hidden.value) === String(p.o.value);
      var disabled = p.o.disabled ? ' is-disabled' : '';
      var sub = p.o.sublabel ? '<span class="coa-sel__sub">' + esc(p.o.sublabel) + '</span>' : '';
      return '<div class="coa-sel__opt' + (isSel ? ' is-selected' : '') + disabled +
        '" role="option" data-value="' + esc(p.o.value) + '" data-vi="' + vi + '">' +
        '<span class="coa-sel__lbl">' + esc(p.o.label) + '</span>' + sub +
        (isSel ? '<i class="fas fa-check coa-sel__tick"></i>' : '') +
      '</div>';
    }).join('');
    activeIdx = -1;
  }

  function setValue(val, label) {
    hidden.value = val == null ? '' : String(val);
    var picked = options.find(function(o){ return String(o.value) === String(hidden.value); });
    var txt = label || (picked ? picked.label : (opts.placeholder || '— اختر —'));
    current.textContent = txt;
    current.classList.toggle('is-placeholder', !picked);
    if (typeof opts.onChange === 'function') opts.onChange(hidden.value, picked || null);
  }

  function open() {
    root.setAttribute('data-open', '1');
    renderList('');
    setTimeout(function(){ searchInp.focus(); searchInp.select(); }, 30);
  }
  function close() { root.setAttribute('data-open', '0'); }
  function toggle() { root.getAttribute('data-open') === '1' ? close() : open(); }

  trigger.addEventListener('click', function(e){ e.stopPropagation(); toggle(); });
  searchInp.addEventListener('input', function(){ renderList(searchInp.value); });
  searchInp.addEventListener('keydown', function(e){
    var opts2 = list.querySelectorAll('.coa-sel__opt:not(.is-disabled)');
    if (e.key === 'ArrowDown') { e.preventDefault(); activeIdx = Math.min(opts2.length - 1, activeIdx + 1); _coaSelHighlight(opts2, activeIdx); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); activeIdx = Math.max(0, activeIdx - 1); _coaSelHighlight(opts2, activeIdx); }
    else if (e.key === 'Enter') { e.preventDefault(); if (activeIdx >= 0 && opts2[activeIdx]) opts2[activeIdx].click(); }
    else if (e.key === 'Escape') { close(); trigger.focus(); }
  });
  list.addEventListener('click', function(e){
    var opt = e.target.closest('.coa-sel__opt');
    if (!opt || opt.classList.contains('is-disabled')) return;
    setValue(opt.getAttribute('data-value'), opt.querySelector('.coa-sel__lbl').textContent);
    close();
  });
  // close when clicking outside
  document.addEventListener('click', function outsideHandler(e){
    if (!root.contains(e.target)) close();
  });

  // Public API on the targetEl for callers to reset/refresh
  targetEl._coaSel = {
    setValue: setValue,
    setOptions: function(newOpts) { options = (newOpts || []).slice(); renderList(''); },
    getValue: function(){ return hidden.value; }
  };
}

function _coaSelHighlight(opts, idx) {
  Array.prototype.forEach.call(opts, function(o, i){ o.classList.toggle('is-active', i === idx); });
  if (opts[idx]) opts[idx].scrollIntoView({ block: 'nearest' });
}

// v5.10.46 — export the chart of accounts to an .xlsx file with a fixed
// 9-column shape (order/code/nameAr/nameEn/type/parentCode/level/kind/balance).
// Re-importing the same file is a no-op; modify cells and re-import to
// upsert. Reuses the global ensureXlsx loader from app.js.
window.coaExportExcel = async function() {
  if (typeof window.ensureXlsx === 'function') await window.ensureXlsx();
  if (typeof XLSX === 'undefined') { showToast('فشل تحميل مكتبة Excel', true); return; }
  if (!_erpAccounts || !_erpAccounts.length) { showToast('لا توجد حسابات للتصدير', true); return; }
  var sorted = _erpAccounts.slice().sort(function(a,b){
    return String(a.code||'').localeCompare(String(b.code||''));
  });
  // v5.10.48 — first column is the internal id. v5.10.50 — added
  // "اسم الأب" so the user can rewire parents in Excel by editing
  // names instead of codes. Backend resolves parents by name first.
  var rows = sorted.map(function(a, idx){
    var parent = a.parentId ? _erpAccounts.find(function(p){ return p.id === a.parentId; }) : null;
    return {
      'المعرف (لا تحذف)': a.id || '',
      // v5.10.51 — real persisted display_order. Edit this cell, re-import,
      // and the row actually moves in the tree.
      'الترتيب':       a.displayOrder == null ? (idx + 1) : Number(a.displayOrder),
      'الكود':         a.code || '',
      'الاسم العربي':  a.nameAr || '',
      'الاسم الإنج':   a.nameEn || '',
      'النوع':         a.type || '',
      'اسم الأب':      parent ? (parent.nameAr || '') : '',
      'كود الأب':      parent ? parent.code : '',
      'المستوى':       a.level || 1,
      'النوع الهيكلي': a.isFolder ? 'رئيسي' : 'فرعي',
      'الرصيد':        Number(a.balance || 0).toFixed(2)
    };
  });
  var ws = XLSX.utils.json_to_sheet(rows);
  ws['!cols'] = [{wch:22},{wch:8},{wch:12},{wch:32},{wch:32},{wch:12},{wch:32},{wch:10},{wch:8},{wch:12},{wch:14}];
  var wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'دليل الحسابات');
  var stamp = new Date().toISOString().slice(0, 10);
  XLSX.writeFile(wb, 'chart_of_accounts_' + stamp + '.xlsx');
  showToast('تم تصدير ' + rows.length + ' حساب');
};

// v5.10.46 — read an .xlsx file the user picked, parse it, then show a
// preview modal before posting. Resetting event.target.value lets the
// user re-pick the same file after fixing it without a hard refresh.
window.coaImportExcel = async function(event) {
  var file = event && event.target && event.target.files && event.target.files[0];
  if (!file) return;
  if (typeof window.ensureXlsx === 'function') await window.ensureXlsx();
  if (typeof XLSX === 'undefined') { showToast('فشل تحميل مكتبة Excel', true); return; }
  var reader = new FileReader();
  reader.onload = function(e) {
    try {
      var wb = XLSX.read(e.target.result, { type: 'array' });
      var ws = wb.Sheets[wb.SheetNames[0]];
      var rows = XLSX.utils.sheet_to_json(ws, { defval: '' });
      // v5.10.55 — first ask the user which import semantics they want.
      _coaShowImportModeModal(rows);
    } catch (err) {
      showToast('فشل قراءة الملف: ' + (err && err.message || err), true);
    }
    event.target.value = '';
  };
  reader.readAsArrayBuffer(file);
};

// v5.10.55 — mode picker. Two options:
//   'update'   — upsert only; existing accounts not in the file stay.
//   'replace'  — file is the truth; accounts not in the file are
//                deleted (when they have no journal entries; otherwise
//                skipped and reported).
function _coaShowImportModeModal(rows) {
  var prior = document.getElementById('coaImportModeModal');
  if (prior) prior.remove();
  var html =
    '<div class="modal show" id="coaImportModeModal" style="display:flex;align-items:flex-start;justify-content:center;z-index:10001;" onclick="if(event.target===this)this.remove();">' +
      '<div class="modal-content" style="max-width:640px;width:96%;margin-top:60px;" onclick="event.stopPropagation();">' +
        '<div class="modal-title">' +
          '<i class="fas fa-question-circle" style="color:#7c3aed;"></i>' +
          '<span>كيف تريد اعتماد الملف؟</span>' +
          '<button class="modal-close" onclick="document.getElementById(\'coaImportModeModal\').remove()">&times;</button>' +
        '</div>' +
        '<div style="padding:18px 22px;">' +
          '<p style="font-size:13.5px;color:#475569;line-height:1.8;margin-bottom:14px;">' +
            'الملف يَحوي <strong>' + rows.length + '</strong> صف. اختر طريقة التَّطبيق:' +
          '</p>' +
          '<div style="display:grid;gap:10px;">' +
            '<button class="coa-mode-btn" onclick="_coaPickImportMode(\'update\')" style="text-align:start;padding:14px 16px;background:#f8fafc;border:1.5px solid #e2e8f0;border-radius:12px;cursor:pointer;transition:all 120ms;">' +
              '<div style="display:flex;align-items:center;gap:10px;">' +
                '<i class="fas fa-pen-to-square" style="color:#0369a1;font-size:18px;"></i>' +
                '<div>' +
                  '<div style="font-weight:800;font-size:14px;color:#0f172a;">اعتماد كتَعديل</div>' +
                  '<div style="font-size:12px;color:#64748b;margin-top:3px;">يُحدِّث ما في الملف فقط. الحسابات الأخرى في القاعدة تَبقى كما هي.</div>' +
                '</div>' +
              '</div>' +
            '</button>' +
            '<button class="coa-mode-btn" onclick="_coaPickImportMode(\'replace\')" style="text-align:start;padding:14px 16px;background:#fef2f2;border:1.5px solid #fecaca;border-radius:12px;cursor:pointer;transition:all 120ms;">' +
              '<div style="display:flex;align-items:center;gap:10px;">' +
                '<i class="fas fa-tree" style="color:#b91c1c;font-size:18px;"></i>' +
                '<div>' +
                  '<div style="font-weight:800;font-size:14px;color:#7f1d1d;">اعتماد كالشجرة النهائية</div>' +
                  '<div style="font-size:12px;color:#991b1b;margin-top:3px;">' +
                    'الملف هو الشجرة كاملةً. الحسابات الموجودة في القاعدة وغير الموجودة في الملف <strong>تُحذف</strong>. ' +
                    'الجذور 1-5 والحسابات بقيود يومية لن تُحذف.' +
                  '</div>' +
                '</div>' +
              '</div>' +
            '</button>' +
          '</div>' +
          '<div style="margin-top:14px;text-align:end;">' +
            '<button class="wo-btn wo-btn-ghost" onclick="document.getElementById(\'coaImportModeModal\').remove()">إلغاء</button>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
  // Stash the rows so the picked mode can carry them forward.
  window._coaImportPendingRows = rows;
}

window._coaPickImportMode = function(mode) {
  var rows = window._coaImportPendingRows || [];
  window._coaImportPendingRows = null;
  var m = document.getElementById('coaImportModeModal');
  if (m) m.remove();
  if (!rows.length) return;
  _coaConfirmImport(rows, mode);
};

function _coaConfirmImport(rows, mode) {
  if (!rows || !rows.length) { showToast('الملف فارغ', true); return; }
  var prior = document.getElementById('coaImportModal');
  if (prior) prior.remove();
  window._coaImportRows = rows;
  window._coaImportMode = String(mode || 'update');
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };
  var sample = rows.slice(0, 5);
  var withId = rows.filter(function(r){ return String(r['المعرف (لا تحذف)'] || r.id || '').trim(); }).length;
  var sampleRows = sample.map(function(r){
    var idVal = String(r['المعرف (لا تحذف)'] || r.id || '').trim();
    var matchBadge = idVal
      ? '<span style="background:#dcfce7;color:#166534;padding:2px 8px;border-radius:999px;font-size:10.5px;font-weight:800;">سيُطابق بالـ ID</span>'
      : '<span style="background:#fef3c7;color:#92400e;padding:2px 8px;border-radius:999px;font-size:10.5px;font-weight:800;">سيُطابق بالكود</span>';
    return '<tr>' +
      '<td>' + esc(r['الكود'] || r.code || '') + '</td>' +
      '<td>' + esc(r['الاسم العربي'] || r.nameAr || '') + '</td>' +
      '<td>' + esc(r['كود الأب'] || r.parentCode || '—') + '</td>' +
      '<td>' + esc(r['المستوى'] || r.level || '') + '</td>' +
      '<td>' + esc(r['النوع الهيكلي'] || r.kind || '') + '</td>' +
      '<td>' + matchBadge + '</td>' +
    '</tr>';
  }).join('');
  var html =
    '<div class="modal show" id="coaImportModal" style="display:flex;align-items:flex-start;justify-content:center;z-index:10001;" onclick="if(event.target===this)this.remove();">' +
      '<div class="modal-content" style="max-width:760px;width:96%;margin-top:48px;" onclick="event.stopPropagation();">' +
        '<div class="modal-title">' +
          '<i class="fas fa-file-import" style="color:#16a34a;"></i>' +
          '<span>معاينة الاستيراد — ' + rows.length + ' حساب</span>' +
          '<button class="modal-close" onclick="document.getElementById(\'coaImportModal\').remove()">&times;</button>' +
        '</div>' +
        '<div style="padding:16px 22px;">' +
          (window._coaImportMode === 'replace'
            ? '<div style="padding:12px 14px;background:#fef2f2;border:1px solid #fecaca;border-radius:10px;font-size:13px;color:#7f1d1d;line-height:1.7;">' +
                '<i class="fas fa-tree"></i> <strong>الوضع: شجرة نهائية.</strong> ' +
                'الملف يُمثِّل الشجرة كاملةً — أي حساب في القاعدة وليس في الملف سيُحذف (مع تجاهل الجذور 1-5 والحسابات التي لها قيود يومية). ' +
                'الأولوية: الاسم + المستوى ثم الـ ID ثم الكود.' +
              '</div>'
            : '<div style="padding:12px 14px;background:#f0f9ff;border:1px solid #bae6fd;border-radius:10px;font-size:13px;color:#0369a1;line-height:1.7;">' +
                '<i class="fas fa-pen-to-square"></i> <strong>الوضع: تَعديل فقط.</strong> ' +
                'الحسابات الموجودة في الملف تُحدَّث، الجديدة تُضاف. الحسابات الأخرى في القاعدة لا تُمسّ. ' +
                'الأولوية: الاسم + المستوى ثم الـ ID ثم الكود.' +
              '</div>'
          ) +
          '<table style="width:100%;border-collapse:collapse;margin-top:14px;font-size:12.5px;">' +
            '<thead><tr style="background:#f1f5f9;">' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">الكود</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">الاسم</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">كود الأب</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">المستوى</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">رئيسي/فرعي</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">المُطابقة</th>' +
            '</tr></thead>' +
            '<tbody>' + sampleRows + '</tbody>' +
          '</table>' +
          (rows.length > 5 ? '<div style="padding:8px 10px;color:#64748b;font-size:12px;">… و ' + (rows.length - 5) + ' صف آخر</div>' : '') +
          '<div style="margin-top:16px;display:flex;gap:8px;justify-content:flex-end;">' +
            '<button class="wo-btn wo-btn-ghost" onclick="document.getElementById(\'coaImportModal\').remove()">إلغاء</button>' +
            '<button class="wo-btn wo-btn-primary" onclick="coaRunImport()"><i class="fas fa-check"></i> تأكيد الاستيراد</button>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
}

window.coaRunImport = function() {
  var rows = window._coaImportRows || [];
  if (!rows.length) return;
  var mode = window._coaImportMode || 'update';
  var token = localStorage.getItem('pos_token') || '';
  var btn = document.querySelector('#coaImportModal .wo-btn-primary');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> جاري الاستيراد...'; }
  fetch('/api/erp/gl/accounts/import', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ rows: rows, mode: mode })
  })
    .then(function(r){ return r.json(); })
    .then(function(j){
      if (!j || !j.success) {
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-check"></i> تأكيد الاستيراد'; }
        showToast((j && j.error) || 'فشل الاستيراد', true);
        return;
      }
      var m = document.getElementById('coaImportModal'); if (m) m.remove();
      window._coaImportRows = null;
      window._coaImportMode = null;
      var renameNote = (j.codeChanges || j.parentChanges) ?
        ' · ' + (j.codeChanges || 0) + ' كود مُعاد · ' + (j.parentChanges || 0) + ' أب مُعاد' : '';
      // v5.10.55 — surface delete metrics in replace mode
      var deleteNote = '';
      if (j.deleted || (j.skippedDeletes && j.skippedDeletes.length)) {
        deleteNote = ' · ' + (j.deleted || 0) + ' محذوف';
        if (j.skippedDeletes && j.skippedDeletes.length) deleteNote += ' · ' + j.skippedDeletes.length + ' تُجوهل (لها قيود)';
      }
      showToast('تم الاستيراد: ' + j.inserted + ' جديد · ' + j.updated + ' محدَّث · ' + j.skipped + ' متخطٍّ' + renameNote + deleteNote);
      // v5.10.50 — if any rows had unresolved parents or other issues,
      // surface them in a follow-up modal so the user can fix the file.
      if (j.errors && j.errors.length) _coaShowImportErrorsModal(j);
      // v5.10.51 — after a successful import, prove what changed by
      // showing the per-row diff. Closes the "I imported but I can't
      // see what was applied" feedback gap.
      if (j.appliedChanges && j.appliedChanges.length) _coaShowAppliedChangesModal(j);
      if (typeof _erpReloadAccountsCacheBust === 'function') _erpReloadAccountsCacheBust();
      else if (typeof erpLoadAccountsList_ === 'function') erpLoadAccountsList_();
    })
    .catch(function(e){
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-check"></i> تأكيد الاستيراد'; }
      showToast(String((e && e.message) || e), true);
    });
};

// v5.10.50 — when the import response carries an errors array (typically
// rows whose parentName/parentCode didn't resolve to any existing
// account), show them so the user can fix the file and re-import.
function _coaShowImportErrorsModal(j) {
  var prior = document.getElementById('coaImportErrorsModal');
  if (prior) prior.remove();
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };
  var rows = (j.errors || []).slice(0, 50).map(function(e){
    return '<tr>' +
      '<td><code>' + esc(e.code || '—') + '</code></td>' +
      '<td><code style="color:#94a3b8;font-size:10.5px;">' + esc(e.id || '—') + '</code></td>' +
      '<td style="color:#b91c1c;">' + esc(e.reason || '') + '</td>' +
    '</tr>';
  }).join('');
  var more = (j.errors.length > 50) ? '<div style="padding:8px 10px;color:#64748b;font-size:12px;">… و ' + (j.errors.length - 50) + ' خطأ آخر</div>' : '';
  var html =
    '<div class="modal show" id="coaImportErrorsModal" style="display:flex;align-items:flex-start;justify-content:center;z-index:10002;" onclick="if(event.target===this)this.remove();">' +
      '<div class="modal-content" style="max-width:680px;width:96%;margin-top:48px;" onclick="event.stopPropagation();">' +
        '<div class="modal-title">' +
          '<i class="fas fa-triangle-exclamation" style="color:#d97706;"></i>' +
          '<span>تحذيرات الاستيراد (' + j.errors.length + ')</span>' +
          '<button class="modal-close" onclick="document.getElementById(\'coaImportErrorsModal\').remove()">&times;</button>' +
        '</div>' +
        '<div style="padding:16px 22px;">' +
          '<div style="padding:10px 14px;background:#fffbeb;border:1px solid #fde68a;border-radius:8px;font-size:12.5px;color:#78350f;line-height:1.7;">' +
            'الصفوف التالية لم تَنحلّ بالكامل (غالبًا لأن "اسم الأب" أو "كود الأب" لا يُطابق أي حساب موجود). صحِّح الملف وأعِد الاستيراد.' +
          '</div>' +
          '<table style="width:100%;border-collapse:collapse;margin-top:12px;font-size:12.5px;">' +
            '<thead><tr style="background:#f1f5f9;">' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">الكود</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">المعرف</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">السبب</th>' +
            '</tr></thead>' +
            '<tbody>' + rows + '</tbody>' +
          '</table>' +
          more +
          '<div style="margin-top:14px;text-align:end;">' +
            '<button class="wo-btn wo-btn-primary" onclick="document.getElementById(\'coaImportErrorsModal\').remove()">إغلاق</button>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
}

// v5.10.51 — applied-changes modal: per-row diff of what the import
// actually changed. Renders BEFORE → AFTER for code, name, level,
// parent, and order so the user has visible proof their edits landed.
function _coaShowAppliedChangesModal(j) {
  var prior = document.getElementById('coaAppliedChangesModal');
  if (prior) prior.remove();
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };
  var changes = (j.appliedChanges || []).slice(0, 200);
  var rowsHtml = changes.map(function(c){
    var d = c.diff || {};
    var parts = [];
    if (d.id)     parts.push('المعرف: <span style="color:#dc2626;font-family:monospace;font-size:11px;">' + esc(d.id.from) + '</span> → <span style="color:#16a34a;font-weight:800;font-family:monospace;font-size:11px;">' + esc(d.id.to) + '</span>');
    if (d.code)   parts.push('الكود: <span style="color:#dc2626;">' + esc(d.code.from) + '</span> → <span style="color:#16a34a;font-weight:800;">' + esc(d.code.to) + '</span>');
    if (d.name)   parts.push('الاسم: <span style="color:#dc2626;">' + esc(d.name.from) + '</span> → <span style="color:#16a34a;font-weight:800;">' + esc(d.name.to) + '</span>');
    if (d.level)  parts.push('المستوى: <span style="color:#dc2626;">L' + esc(d.level.from) + '</span> → <span style="color:#16a34a;font-weight:800;">L' + esc(d.level.to) + '</span>');
    if (d.order)  parts.push('الترتيب: <span style="color:#dc2626;">' + (d.order.from == null ? '—' : esc(d.order.from)) + '</span> → <span style="color:#16a34a;font-weight:800;">' + esc(d.order.to) + '</span>');
    if (d.parent) parts.push('الأب: <span style="color:#dc2626;">' + (d.parent.from == null ? '—' : esc(d.parent.from)) + '</span> → <span style="color:#16a34a;font-weight:800;">' + (d.parent.to == null ? '—' : esc(d.parent.to)) + '</span>');
    return '<tr>' +
      '<td><strong>' + esc(c.code) + '</strong></td>' +
      '<td>' + esc(c.name || '') + '</td>' +
      '<td style="line-height:1.9;">' + parts.join('<br>') + '</td>' +
    '</tr>';
  }).join('');
  var more = ((j.appliedChanges || []).length > 200) ? '<div style="padding:8px 10px;color:#64748b;font-size:12px;">… و ' + ((j.appliedChanges.length - 200)) + ' تَغيير آخر</div>' : '';
  var sums = '<strong>' + (j.codeChanges  || 0) + '</strong> كود · ' +
             '<strong>' + (j.parentChanges|| 0) + '</strong> أب · ' +
             '<strong>' + (j.levelChanges || 0) + '</strong> مستوى · ' +
             '<strong>' + (j.orderChanges || 0) + '</strong> ترتيب';
  var html =
    '<div class="modal show" id="coaAppliedChangesModal" style="display:flex;align-items:flex-start;justify-content:center;z-index:10002;" onclick="if(event.target===this)this.remove();">' +
      '<div class="modal-content" style="max-width:820px;width:96%;margin-top:32px;max-height:88vh;display:flex;flex-direction:column;" onclick="event.stopPropagation();">' +
        '<div class="modal-title">' +
          '<i class="fas fa-circle-check" style="color:#16a34a;"></i>' +
          '<span>تَفاصيل التَّطبيق — ' + (j.appliedChanges || []).length + ' تَغيير</span>' +
          '<button class="modal-close" onclick="document.getElementById(\'coaAppliedChangesModal\').remove()">&times;</button>' +
        '</div>' +
        '<div style="padding:16px 22px;overflow-y:auto;flex:1;">' +
          '<div style="padding:12px 14px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px;font-size:13px;color:#166534;line-height:1.8;margin-bottom:12px;">' +
            '<i class="fas fa-shield-check"></i> ' +
            'تم تَطبيق وتَأكيد التَّغييرات على القاعدة. الـ verification يَعمل على الخادم بعد كل commit. ' +
            'مجموع: ' + sums +
          '</div>' +
          '<table style="width:100%;border-collapse:collapse;font-size:12.5px;">' +
            '<thead><tr style="background:#f1f5f9;">' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">الكود</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">الاسم</th>' +
              '<th style="padding:8px 10px;text-align:right;border-bottom:1px solid #e2e8f0;">التَّغيير</th>' +
            '</tr></thead>' +
            '<tbody>' + rowsHtml + '</tbody>' +
          '</table>' +
          more +
        '</div>' +
        '<div style="padding:14px 22px;border-top:1px solid #e2e8f0;text-align:end;background:#f8fafc;">' +
          '<button class="wo-btn wo-btn-primary" onclick="document.getElementById(\'coaAppliedChangesModal\').remove()">إغلاق</button>' +
        '</div>' +
      '</div>' +
    '</div>';
  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
}

// v5.10.50 — detect duplicate accounts by normalized name (trimmed +
// case-folded) and let the user pick which to keep. Backend deletes the
// rest atomically (refusing any whose deletion would orphan journal
// entries). Reachable from the tree toolbar.
// v5.11.1 — fetches the official 150-account template and feeds it
// through the existing import preview flow with replace-mode preselected.
// One confirmation, then the chart is overwritten (accounts with journal
// entries are preserved by the import logic).
window.coaApplyTemplate = function() {
  var token = localStorage.getItem('pos_token') || '';
  fetch('/api/erp/gl/coa-template', { headers: { 'Authorization': 'Bearer ' + token } })
    .then(function(r){ return r.json(); })
    .then(function(j){
      if (!j || !j.success || !Array.isArray(j.accounts)) {
        return showToast('تعذَّر تحميل القالب', true);
      }
      var rows = j.accounts.map(function(a){
        return {
          'الكود':         a.code,
          'الاسم العربي':  a.nameAr,
          'الاسم الإنج':   a.nameEn,
          'النوع':         a.type,
          'كود الأب':      a.parentCode || '',
          'اسم الأب':      '',
          'المستوى':       a.level,
          'النوع الهيكلي': a.kind === 'folder' ? 'رئيسي' : 'فرعي',
          'الترتيب':       a.order
        };
      });
      // Single confirmation before the destructive replace.
      erpConfirm(
        'تَطبيق القالب الرسمي',
        'سيُطبَّق القالب الرسمي (' + rows.length + ' حساب) كـ"شجرة نهائية" — أي حساب في القاعدة وليس في القالب سيُحذف، باستثناء الجذور 1-5 والحسابات بقيود يومية. متابعة؟',
        function(){
          window._coaImportRows = rows;
          window._coaImportMode = 'replace';
          // Reuse the import preview modal; user just clicks "تأكيد".
          _coaConfirmImport(rows, 'replace');
        },
        { icon: 'fa-wand-magic-sparkles', color: '#7c3aed', okText: 'تَطبيق' }
      );
    })
    .catch(function(e){ showToast(String((e && e.message) || e), true); });
};

window.coaOpenDedupeModal = function() {
  var prior = document.getElementById('coaDedupeModal');
  if (prior) prior.remove();
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };
  var normName = function(s){ return String(s||'').trim().toLowerCase().replace(/\s+/g, ' '); };

  // Group accounts by normalized nameAr; keep only groups of size > 1.
  var groups = {};
  (_erpAccounts || []).forEach(function(a){
    var nn = normName(a.nameAr);
    if (!nn) return;
    if (!groups[nn]) groups[nn] = [];
    groups[nn].push(a);
  });
  var dupGroups = Object.keys(groups).filter(function(k){ return groups[k].length > 1; }).map(function(k){ return groups[k]; });
  // Sort groups by name; inside each, oldest-with-most-movements first
  dupGroups.sort(function(a,b){ return String(a[0].nameAr||'').localeCompare(String(b[0].nameAr||'')); });
  dupGroups.forEach(function(g){
    g.sort(function(a,b){
      var am = (a.movementCount || 0), bm = (b.movementCount || 0);
      if (am !== bm) return bm - am;             // most movements first → suggested keeper
      return String(a.code||'').localeCompare(String(b.code||''));
    });
  });

  if (!dupGroups.length) {
    showToast('لا توجد حسابات مكرَّرة بالاسم');
    return;
  }

  var sectionsHtml = dupGroups.map(function(group, gi){
    var rowsHtml = group.map(function(a, ri){
      var ckId = 'coaDup_' + gi + '_' + ri;
      var nameId = 'coaDupKeep_' + gi;  // radio name = group, so picking one auto-deselects others
      var hasMovements = (a.movementCount || 0) > 0;
      return '<tr data-acc-id="' + esc(a.id) + '" data-group="' + gi + '">' +
        '<td><input type="radio" name="' + nameId + '" id="' + ckId + '"' + (ri === 0 ? ' checked' : '') + ' style="width:16px;height:16px;cursor:pointer;"></td>' +
        '<td><strong>' + esc(a.code || '') + '</strong></td>' +
        '<td>' + esc(a.nameAr || '') + '</td>' +
        '<td><code style="font-size:10.5px;color:#64748b;">' + esc(a.id) + '</code></td>' +
        '<td style="text-align:center;">L' + (a.level || 1) + '</td>' +
        '<td style="text-align:center;color:' + (hasMovements ? '#dc2626' : '#94a3b8') + ';font-weight:800;">' + (a.movementCount || 0) + '</td>' +
        '<td style="text-align:end;font-variant-numeric:tabular-nums;">' + Number(a.balance||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}) + '</td>' +
      '</tr>';
    }).join('');
    return '<div class="coa-dedupe-group" style="margin-bottom:18px;">' +
      '<div style="font-weight:800;color:#0f172a;font-size:13px;padding:6px 4px;display:flex;align-items:center;gap:8px;">' +
        '<i class="fas fa-clone" style="color:#7c3aed;"></i>' +
        '<span>' + esc(group[0].nameAr) + '</span>' +
        '<span style="background:#fef3c7;color:#92400e;padding:2px 8px;border-radius:999px;font-size:11px;font-weight:700;">' + group.length + ' نسخ</span>' +
      '</div>' +
      '<table style="width:100%;border-collapse:collapse;font-size:12.5px;border:1px solid #e2e8f0;border-radius:8px;overflow:hidden;">' +
        '<thead><tr style="background:#f8fafc;">' +
          '<th style="padding:8px 10px;text-align:center;width:60px;">إبقاء</th>' +
          '<th style="padding:8px 10px;text-align:right;">الكود</th>' +
          '<th style="padding:8px 10px;text-align:right;">الاسم</th>' +
          '<th style="padding:8px 10px;text-align:right;">المعرف</th>' +
          '<th style="padding:8px 10px;text-align:center;">المستوى</th>' +
          '<th style="padding:8px 10px;text-align:center;">الحركات</th>' +
          '<th style="padding:8px 10px;text-align:end;">الرصيد</th>' +
        '</tr></thead>' +
        '<tbody>' + rowsHtml + '</tbody>' +
      '</table>' +
    '</div>';
  }).join('');

  var totalDups = dupGroups.reduce(function(s,g){ return s + g.length; }, 0);
  var willDelete = totalDups - dupGroups.length;

  var html =
    '<div class="modal show" id="coaDedupeModal" style="display:flex;align-items:flex-start;justify-content:center;z-index:10001;" onclick="if(event.target===this)this.remove();">' +
      '<div class="modal-content" style="max-width:920px;width:96%;margin-top:32px;max-height:88vh;display:flex;flex-direction:column;" onclick="event.stopPropagation();">' +
        '<div class="modal-title">' +
          '<i class="fas fa-clone" style="color:#7c3aed;"></i>' +
          '<span>حذف الحسابات المُكرَّرة</span>' +
          '<button class="modal-close" onclick="document.getElementById(\'coaDedupeModal\').remove()">&times;</button>' +
        '</div>' +
        '<div style="padding:18px 22px;overflow-y:auto;flex:1;">' +
          '<div style="padding:12px 14px;background:#f0f9ff;border:1px solid #bae6fd;border-radius:10px;font-size:13px;color:#0369a1;line-height:1.7;margin-bottom:14px;">' +
            '<i class="fas fa-circle-info"></i> ' +
            'تم العثور على <strong>' + dupGroups.length + '</strong> مجموعة بأسماء مكرَّرة (<strong>' + totalDups + '</strong> حساب إجمالي). ' +
            'الـ radio يُؤشِّر إلى الحساب الذي سيُبقى — الأبناء سيُربطون به. ' +
            'الباقي (<strong>' + willDelete + '</strong> حساب) سيُحذف. ' +
            '<strong>الحسابات بحركات يومية لن تُحذف</strong> — سيُتجاهَل وضعها وتُترَك.' +
          '</div>' +
          sectionsHtml +
        '</div>' +
        '<div style="padding:14px 22px;border-top:1px solid #e2e8f0;display:flex;gap:8px;justify-content:flex-end;background:#f8fafc;">' +
          '<button class="wo-btn wo-btn-ghost" onclick="document.getElementById(\'coaDedupeModal\').remove()">إلغاء</button>' +
          '<button class="wo-btn wo-btn-primary" style="background:#dc2626;" onclick="coaConfirmDedupe()"><i class="fas fa-trash"></i> حذف ' + willDelete + ' مكرَّر</button>' +
        '</div>' +
      '</div>' +
    '</div>';
  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
};

window.coaConfirmDedupe = function() {
  var modal = document.getElementById('coaDedupeModal');
  if (!modal) return;
  // Build payload: for each group, the keep id and the delete ids.
  var groups = {};
  modal.querySelectorAll('tr[data-acc-id]').forEach(function(tr){
    var gi = tr.getAttribute('data-group');
    var id = tr.getAttribute('data-acc-id');
    var radio = tr.querySelector('input[type="radio"]');
    if (!groups[gi]) groups[gi] = { keep: null, deleteIds: [] };
    if (radio && radio.checked) groups[gi].keep = id;
    else groups[gi].deleteIds.push(id);
  });
  var payload = [];
  Object.keys(groups).forEach(function(gi){
    var g = groups[gi];
    if (!g.keep || !g.deleteIds.length) return;
    payload.push({ keepId: g.keep, deleteIds: g.deleteIds });
  });
  if (!payload.length) { showToast('لا شيء للحذف', true); return; }

  var btn = modal.querySelector('.wo-btn-primary');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> جاري الحذف...'; }
  var token = localStorage.getItem('pos_token') || '';
  fetch('/api/erp/gl/accounts/dedupe', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ groups: payload })
  })
    .then(function(r){ return r.json(); })
    .then(function(j){
      if (!j || !j.success) {
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-trash"></i> حذف مكرَّر'; }
        showToast((j && j.error) || 'فشل الحذف', true);
        return;
      }
      modal.remove();
      var noteSkipped = (j.skipped && j.skipped.length) ? ' · ' + j.skipped.length + ' لم يُحذف (له حركات)' : '';
      showToast('تم حذف ' + (j.deleted || 0) + ' حساب مكرَّر · ' + (j.reparented || 0) + ' طفل مُعاد ربطه' + noteSkipped);
      if (typeof _erpReloadAccountsCacheBust === 'function') _erpReloadAccountsCacheBust();
    })
    .catch(function(e){
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-trash"></i> حذف مكرَّر'; }
      showToast(String((e && e.message) || e), true);
    });
};

// v5.10.45 — collect all descendant ids of an account so the move modal
// can exclude them from the parent dropdown (preventing cycles client-side).
function _coaCollectDescendants(rootId) {
  var out = [];
  function walk(pid) {
    _erpAccounts.forEach(function(a){
      if (a.parentId === pid) { out.push(a.id); walk(a.id); }
    });
  }
  walk(rootId);
  return out;
}

// v5.10.45 — compute the next code under a given parent, mirroring
// erpAddChildAccount's algorithm. Used by the move modal preview AND by
// the backend (kept identical to avoid drift). Returns null if no parent.
function _coaPreviewMoveCode(parent) {
  if (!parent) return null;
  var children = _erpAccounts.filter(function(a){ return a.parentId === parent.id; });
  var childCodes = children.map(function(a){ return a.code; }).sort();
  if (!childCodes.length) {
    return (parent.level >= 3) ? parent.code + '01' : parent.code + '1';
  }
  var lastCode = childCodes[childCodes.length - 1];
  var suffix = lastCode.substring(parent.code.length);
  var nextNum = parseInt(suffix, 10) + 1;
  return parent.code + String(nextNum).padStart(suffix.length, '0');
}

// v5.10.45 — move modal: lets the user reparent an account (and optionally
// auto-renumber the code + cascade-rename descendants). Posts to
// /api/erp/gl/accounts/:id/move which performs the work atomically.
window.coaOpenMoveModal = function(id) {
  var acc = _erpAccounts.find(function(a){ return a.id === id; });
  if (!acc) return;
  var prior = document.getElementById('coaMoveModal');
  if (prior) prior.remove();
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };
  var descendantIds = _coaCollectDescendants(id);
  var descendantCount = descendantIds.length;
  // v5.10.47 — structured options for the searchable combobox.
  var moveParentOptions = [{ value: '', label: '— جذر (بلا أب) —' }].concat(
    _erpAccounts
      .filter(function(a){
        if (a.id === id) return false;
        if (descendantIds.indexOf(a.id) >= 0) return false;
        if ((a.level || 1) >= 4) return false;
        return true;
      })
      .sort(function(a,b){ return String(a.code||'').localeCompare(String(b.code||'')); })
      .map(function(a){
        var indentM = '  '.repeat(((a.level||1) - 1));
        return {
          value: a.id,
          label: indentM + a.code + ' — ' + (a.nameAr || ''),
          sublabel: a.type || ''
        };
      })
  );
  var parentOpts = '<option value="">— جذر (بلا أب) —</option>' +
    _erpAccounts
      .filter(function(a){
        if (a.id === id) return false;
        if (descendantIds.indexOf(a.id) >= 0) return false;
        if ((a.level || 1) >= 4) return false;
        return true;
      })
      .sort(function(a,b){ return String(a.code||'').localeCompare(String(b.code||'')); })
      .map(function(a){
        var indent = '    '.repeat(((a.level||1) - 1));
        return '<option value="' + a.id + '">' + indent + esc(a.code) + ' — ' + esc(a.nameAr || '') + '</option>';
      }).join('');

  var html =
    '<div class="modal show" id="coaMoveModal" style="display:flex;align-items:flex-start;justify-content:center;z-index:10001;" onclick="if(event.target===this)this.remove();">' +
      '<div class="modal-content" style="max-width:560px;width:96%;margin-top:60px;" onclick="event.stopPropagation();">' +
        '<div class="modal-title">' +
          '<i class="fas fa-arrows-up-down-left-right" style="color:#7c3aed;"></i>' +
          '<span>نقل الحساب: ' + esc(acc.code) + ' — ' + esc(acc.nameAr || '') + '</span>' +
          '<button class="modal-close" onclick="document.getElementById(\'coaMoveModal\').remove()">&times;</button>' +
        '</div>' +
        '<div style="padding:18px 22px;">' +
          '<div class="form-row">' +
            '<label style="font-weight:700;">الأب الجديد</label>' +
            '<div id="coaMoveParentMount"></div>' +
          '</div>' +
          '<div class="form-row" style="display:flex;align-items:center;gap:8px;margin-top:12px;">' +
            '<input type="checkbox" id="coaMoveAutoRenum" checked onchange="_coaUpdateMovePreview(\'' + id + '\')" style="width:18px;height:18px;">' +
            '<label for="coaMoveAutoRenum" style="margin:0;font-weight:700;cursor:pointer;">إعادة ترقيم الكود تلقائيًا بناءً على الأب الجديد</label>' +
          '</div>' +
          '<div id="coaMovePreview" style="margin-top:14px;padding:12px 14px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;font-size:13px;color:#475569;line-height:1.8;">' +
            'اختر أبًا جديدًا لمعاينة الكود الناتج.' +
          '</div>' +
          (descendantCount > 0 ? '<div style="margin-top:10px;padding:10px 14px;background:#fffbeb;border:1px solid #fde68a;border-radius:8px;font-size:12.5px;color:#78350f;"><i class="fas fa-triangle-exclamation"></i> هذا الحساب لديه <strong>' + descendantCount + '</strong> حساب فرعي — سيُعاد ترقيمها تلقائيًا للحفاظ على التسلسل.</div>' : '') +
          '<div style="margin-top:18px;display:flex;gap:8px;justify-content:flex-end;">' +
            '<button class="wo-btn wo-btn-ghost" onclick="document.getElementById(\'coaMoveModal\').remove()">إلغاء</button>' +
            '<button class="wo-btn wo-btn-primary" onclick="coaConfirmMove(\'' + id + '\')"><i class="fas fa-check"></i> تأكيد النقل</button>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);

  // v5.10.47 — mount the searchable combobox in the parent slot. The
  // hidden input it writes (#coaMoveNewParent) keeps the same id so
  // existing readers in coaConfirmMove / _coaUpdateMovePreview still work.
  setTimeout(function(){
    var mount = document.getElementById('coaMoveParentMount');
    if (!mount) return;
    _coaMountSearchableSelect(mount, {
      id: 'coaMoveNewParent',
      placeholder: '— جذر (بلا أب) —',
      value: '',
      options: moveParentOptions,
      onChange: function(){ if (typeof _coaUpdateMovePreview === 'function') _coaUpdateMovePreview(id); }
    });
  }, 30);
};

window._coaUpdateMovePreview = function(id) {
  var acc = _erpAccounts.find(function(a){ return a.id === id; });
  var box = document.getElementById('coaMovePreview');
  var sel = document.getElementById('coaMoveNewParent');
  var auto = document.getElementById('coaMoveAutoRenum');
  if (!acc || !box || !sel) return;
  var newParentId = sel.value || null;
  var newParent = newParentId ? _erpAccounts.find(function(a){ return a.id === newParentId; }) : null;
  var willRenumber = !!(auto && auto.checked && newParent);
  var newCode = willRenumber ? _coaPreviewMoveCode(newParent) : acc.code;
  var newLevel = newParent ? ((newParent.level || 1) + 1) : 1;
  box.innerHTML =
    '<div><strong>الكود الجديد:</strong> <code style="background:#fff;padding:2px 8px;border-radius:6px;border:1px solid #cbd5e1;font-weight:800;color:#7c3aed;">' + (newCode || '—') + '</code>' +
      (willRenumber ? '' : ' <span style="color:#94a3b8;">(لن يتغيَّر — اختيار يدوي)</span>') +
    '</div>' +
    '<div style="margin-top:6px;"><strong>المستوى الجديد:</strong> L' + newLevel + '</div>' +
    '<div style="margin-top:6px;color:#64748b;font-size:12px;">' +
      'الأب: ' + (newParent ? (newParent.code + ' — ' + (newParent.nameAr || '')) : '— جذر —') +
    '</div>';
};

window.coaConfirmMove = function(id) {
  var sel = document.getElementById('coaMoveNewParent');
  var auto = document.getElementById('coaMoveAutoRenum');
  if (!sel) return;
  var newParentId = sel.value || null;
  var autoRenumber = !!(auto && auto.checked);
  var token = localStorage.getItem('pos_token') || '';
  var btn = document.querySelector('#coaMoveModal .wo-btn-primary');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> جاري النقل...'; }
  fetch('/api/erp/gl/accounts/' + encodeURIComponent(id) + '/move', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ parentId: newParentId, autoRenumber: autoRenumber })
  })
    .then(function(r){ return r.json(); })
    .then(function(j){
      if (!j || !j.success) {
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-check"></i> تأكيد النقل'; }
        showToast((j && j.error) || 'فشل النقل', true);
        return;
      }
      var modal = document.getElementById('coaMoveModal');
      if (modal) modal.remove();
      var n = (j.renumbered || []).length;
      showToast('تم نقل الحساب بنجاح — أُعيد ترقيم ' + n + ' حساب');
      if (typeof _erpReloadAccountsCacheBust === 'function') _erpReloadAccountsCacheBust();
      else if (typeof erpLoadAccountsList_ === 'function') erpLoadAccountsList_();
    })
    .catch(function(e){
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-check"></i> تأكيد النقل'; }
      showToast(String((e && e.message) || e), true);
    });
};

// Pull a fresh diagnose snapshot in the background so tree warning icons
// reflect the current state without forcing the user to open the modal.
function _coaRefreshDiagSnap() {
  var token = localStorage.getItem('pos_token') || '';
  fetch('/api/erp/gl/diagnose', { headers: { 'Authorization': 'Bearer ' + token } })
    .then(function(r){ return r.json(); })
    .then(function(j){
      window._coaDiagSnap = j;
      _coaUpdateDiagBadge(j);
      if (typeof _coaBuildTree === 'function') _coaBuildTree();
    })
    .catch(function(){});
}

// v5.10.47 — per-category "إصلاح" button: runs deep-repair, then
// re-fetches diagnose and re-renders the modal body in place. The user
// stays in the diagnose modal; resolved categories vanish from the list
// without needing to close+reopen anything. The full-blown repair-report
// modal is intentionally skipped here — that flow is reserved for the
// header-level "إصلاح شامل" button.
window._coaFixAllAndRefreshDiagnose = function(btnEl) {
  var btn = btnEl || null;
  var prevHtml = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> جاري الإصلاح...'; }
  var token = localStorage.getItem('pos_token') || '';
  fetch('/api/erp/gl/deep-repair', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' }
  })
    .then(function(r){ return r.json(); })
    .then(function(j){
      if (!j || !j.success) {
        if (btn) { btn.disabled = false; btn.innerHTML = prevHtml; }
        showToast((j && j.error) || 'فشل الإصلاح', true);
        return;
      }
      // Re-fetch diagnose and re-render the modal body in place.
      return fetch('/api/erp/gl/diagnose', { headers: { 'Authorization': 'Bearer ' + token } })
        .then(function(r2){ return r2.json(); })
        .then(function(diag){
          window._coaDiagSnap = diag;
          _coaUpdateDiagBadge(diag);
          _coaRenderDiagnose(diag);
          // Refresh accounts so the tree mirrors the post-repair state.
          if (typeof _erpReloadAccountsCacheBust === 'function') _erpReloadAccountsCacheBust();
          var fixedCount = 0;
          if (j.before && j.after) {
            ['orphans','typeMismatch','duplicateCodes','levelMismatch','cycles',
             'codeTypeMismatch','balanceWithoutEntries','nameVsPlacementMismatch',
             'rootCodeMismatch','unbalancedJournals','orphanEntries','missingCoreAccounts'
            ].forEach(function(k){ fixedCount += Math.max(0, (j.before[k]||0) - (j.after[k]||0)); });
          }
          showToast('تم إصلاح ' + fixedCount + ' مشكلة');
        });
    })
    .catch(function(e){
      if (btn) { btn.disabled = false; btn.innerHTML = prevHtml; }
      showToast(String((e && e.message) || e), true);
    });
};

// Display a modal summarizing what /gl/deep-repair changed.
function _coaShowRepairReport(j) {
  var labels = {
    orphans: 'يتيمة',
    typeMismatch: 'نوع لا يطابق الأب',
    codeTypeMismatch: 'النوع لا يطابق الكود',
    rootCodeMismatch: 'الجذر الفعلي لا يطابق الكود',
    duplicateCodes: 'أكواد مكرَّرة',
    balanceWithoutEntries: 'رصيد بدون قيود فعلية',
    levelMismatch: 'مستويات خاطئة',
    cycles: 'حلقات (cycles)'
  };
  var before = j.before || {}, after = j.after || {};
  var esc = function(t){ return String(t==null?'':t).replace(/[&<>"']/g, function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };
  var totalBefore = 0, totalAfter = 0;
  Object.keys(labels).forEach(function(k){ totalBefore += (before[k]||0); totalAfter += (after[k]||0); });

  var rowsHtml = Object.keys(labels).map(function(k){
    var b = before[k] || 0, a = after[k] || 0;
    var diff = b - a, color = diff > 0 ? '#16a34a' : (diff < 0 ? '#dc2626' : '#64748b');
    return '<tr>' +
      '<td style="padding:6px 10px;">' + labels[k] + '</td>' +
      '<td style="padding:6px 10px;text-align:center;color:#64748b;">' + b + '</td>' +
      '<td style="padding:6px 10px;text-align:center;font-weight:800;color:' + color + ';">' + a + '</td>' +
      '<td style="padding:6px 10px;text-align:center;color:' + color + ';">' + (diff > 0 ? '−' + diff : (diff < 0 ? '+' + Math.abs(diff) : '0')) + '</td>' +
    '</tr>';
  }).join('');

  var reclass = j.reclassified || [];
  var skipped = j.skipped || [];
  var typeFixed = j.typeFixed || [];

  var detailsHtml = '';
  if (reclass.length) {
    detailsHtml += '<details style="margin-top:14px;"><summary style="cursor:pointer;font-weight:700;">إعادة تصنيف ' + reclass.length + ' حساب</summary><div style="max-height:240px;overflow:auto;margin-top:8px;font-size:12px;">';
    reclass.slice(0, 200).forEach(function(x){
      detailsHtml += '<div style="padding:4px 8px;border-bottom:1px solid #f1f5f9;">' +
        esc(x.nameAr || '') + ' <span style="color:#64748b;">(' + esc(x.code || '') + ')</span> · ' +
        '<span style="color:#dc2626;">' + esc(x.oldParentCode || '?') + '</span> → ' +
        '<span style="color:#16a34a;">' + esc(x.newParentCode || '?') + '</span>' +
      '</div>';
    });
    if (reclass.length > 200) detailsHtml += '<div style="padding:4px 8px;color:#64748b;">… و' + (reclass.length - 200) + ' بند آخر</div>';
    detailsHtml += '</div></details>';
  }
  if (typeFixed.length) {
    detailsHtml += '<details style="margin-top:8px;"><summary style="cursor:pointer;font-weight:700;">تصحيح النوع لـ ' + typeFixed.length + ' حساب</summary><div style="max-height:240px;overflow:auto;margin-top:8px;font-size:12px;">';
    typeFixed.slice(0, 200).forEach(function(x){
      detailsHtml += '<div style="padding:4px 8px;border-bottom:1px solid #f1f5f9;">' +
        esc(x.code || '') + ' · ' +
        '<span style="color:#dc2626;">' + esc(x.oldType || '—') + '</span> → ' +
        '<span style="color:#16a34a;">' + esc(x.newType || '—') + '</span>' +
      '</div>';
    });
    detailsHtml += '</div></details>';
  }
  if (skipped.length) {
    detailsHtml += '<details style="margin-top:8px;"><summary style="cursor:pointer;font-weight:700;color:#b45309;">تخطٍّ ' + skipped.length + ' حساب (مراجعة يدوية)</summary><div style="max-height:200px;overflow:auto;margin-top:8px;font-size:12px;">';
    skipped.slice(0, 100).forEach(function(x){
      detailsHtml += '<div style="padding:4px 8px;border-bottom:1px solid #f1f5f9;">' +
        esc(x.nameAr || '') + ' <span style="color:#64748b;">(' + esc(x.code || '') + ')</span> · ' + esc(x.reason || '') +
      '</div>';
    });
    detailsHtml += '</div></details>';
  }

  var summaryColor = totalAfter === 0 ? '#16a34a' : (totalAfter < totalBefore ? '#0e7490' : '#dc2626');
  var summaryIcon = totalAfter === 0 ? 'fa-circle-check' : 'fa-circle-info';
  var summaryText = totalAfter === 0
    ? 'الشجرة سليمة الآن — تم حلّ كل المشاكل ✓'
    : (totalBefore - totalAfter) + ' مشكلة تم إصلاحها · ' + totalAfter + ' متبقّية للمراجعة';

  var html =
    '<div class="modal show" id="coaRepairReportModal" style="display:flex;align-items:flex-start;justify-content:center;z-index:10000;" onclick="if(event.target===this)this.remove();">' +
      '<div class="modal-content modal-large" style="max-width:760px;width:96%;margin-top:24px;" onclick="event.stopPropagation();">' +
        '<div class="modal-title">' +
          '<i class="fas fa-wand-magic-sparkles" style="color:#7c3aed;"></i>' +
          '<span>تقرير الإصلاح الشامل</span>' +
          '<button class="modal-close" onclick="document.getElementById(\'coaRepairReportModal\').remove()">&times;</button>' +
        '</div>' +
        '<div style="padding:18px 20px;">' +
          '<div style="display:flex;align-items:center;gap:12px;padding:14px;background:' + summaryColor + '11;border:1px solid ' + summaryColor + '33;border-radius:10px;margin-bottom:14px;">' +
            '<i class="fas ' + summaryIcon + '" style="color:' + summaryColor + ';font-size:24px;"></i>' +
            '<div style="font-weight:800;color:' + summaryColor + ';">' + summaryText + '</div>' +
          '</div>' +
          '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
            '<thead><tr style="background:#f8fafc;border-bottom:2px solid #e2e8f0;">' +
              '<th style="padding:8px 10px;text-align:right;">الفئة</th>' +
              '<th style="padding:8px 10px;text-align:center;">قبل</th>' +
              '<th style="padding:8px 10px;text-align:center;">بعد</th>' +
              '<th style="padding:8px 10px;text-align:center;">التغير</th>' +
            '</tr></thead>' +
            '<tbody>' + rowsHtml + '</tbody>' +
          '</table>' +
          '<div style="margin-top:14px;padding:10px 14px;background:#f0f9ff;border:1px solid #bae6fd;border-radius:8px;font-size:13px;color:#0369a1;">' +
            '<i class="fas fa-circle-check"></i> ' +
            'أُعيد احتساب أرصدة <b>' + (j.balancesRecomputed||0) + '</b> حساب من قيود اليومية الفعلية' +
            ((j.rootFixed||[]).length ? ' · نُقل <b>' + j.rootFixed.length + '</b> حساب لجذره الصحيح' : '') +
            ((j.bruteForcedTopology||[]).length ? ' · فُرض على <b>' + j.bruteForcedTopology.length + '</b> حساب الانتقال مباشرةً تحت جذره (v5.10.44)' : '') +
            '. الآن الأرقام في الشجرة = مجموع <code>gl_entries</code> فقط — لا أرصدة وهمية.' +
          '</div>' +
          detailsHtml +
          '<div style="margin-top:16px;text-align:left;">' +
            '<button class="wo-btn wo-btn-primary" onclick="document.getElementById(\'coaRepairReportModal\').remove()">إغلاق</button>' +
          '</div>' +
        '</div>' +
      '</div>' +
    '</div>';

  // remove any prior instance
  var prior = document.getElementById('coaRepairReportModal');
  if (prior) prior.remove();
  var wrap = document.createElement('div');
  wrap.innerHTML = html;
  document.body.appendChild(wrap.firstChild);
}

// ─── Suggestions panel (international standard reference) ───
window.coaOpenSuggestions = function() {
  var modal = document.getElementById('coaSuggModal');
  var body  = document.getElementById('coaSuggBody');
  if (!modal || !body) return;
  body.innerHTML = _coaBuildSuggestionsHtml();
  modal.classList.add('show'); modal.style.display = '';
};
window.coaCloseSuggestions = function() {
  var m = document.getElementById('coaSuggModal'); if (m) { m.classList.remove('show'); m.style.display = 'none'; }
};

