function erpPrintStatement(type) {
  const containerId = type === 'customer' ? 'erpCustomerStatement' : 'erpSupplierStatement';
  const el = document.getElementById(containerId);
  const printWin = window.open('', '_blank');
  printWin.document.write(`<html dir="rtl"><head><title>كشف حساب</title>
    <style>body{font-family:Arial,sans-serif;padding:20px;direction:rtl}table{width:100%;border-collapse:collapse;margin:10px 0}th,td{border:1px solid #ddd;padding:6px 8px;text-align:right;font-size:12px}th{background:#f0f4f8}
    .section-title{font-size:18px;margin-bottom:10px}.fin-grid{display:flex;gap:15px;margin:10px 0}.fin-card{padding:8px;background:#f8fafc;border-radius:4px}.fin-label{font-size:11px;color:#666}.fin-val{font-weight:bold}
    @media print{button{display:none}}</style></head><body>${el.innerHTML}<scr`+`ipt>window.print();<\/scr`+`ipt></body></html>`);
  printWin.document.close();
}

// ═══════════════════════════════════════
// EXPORT CSV (تصدير التقارير) §19.9
// ═══════════════════════════════════════

function erpExportReport(reportType) {
  loader(true);
  const filters = {};
  if (reportType === 'warehouse_stock') {
    const whId = document.getElementById('erpStockWhFilter');
    if (whId) filters.warehouseId = whId.value || null;
  }
  window._apiBridge.withSuccessHandler(function(res) {
    loader(false);
    if (!res.success) { showToast(res.error || 'خطأ في التصدير', 'error'); return; }
    // تنزيل CSV
    const blob = new Blob([res.csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = res.filename || 'report.csv';
    link.click();
    showToast('تم تصدير التقرير');
  }).exportReportCSV(reportType, filters);
}

// ═══════════════════════════════════════
// MODAL UTILS
// ═══════════════════════════════════════
function erpCloseModal() {
  var modalEl = document.getElementById('erpModal');
  modalEl.classList.add('hidden');
  // V3.1 — clean up the wide txn-view-mode layout so the next modal opens normally
  modalEl.classList.remove('txn-view-mode');
  var injectedTb = modalEl.querySelector('#wfTxnToolbar');
  if (injectedTb) injectedTb.remove();
  // V4 — clear cached server permissions so next view fetches fresh
  window._lastViewedTxnPerms = null;
  // Reset modal width (PO form widens it via inline style)
  const box = document.querySelector('#erpModal .modal-box');
  if (box) box.style.maxWidth = '';
}
function erpModalSave() {
  // Placeholder — each modal sets its own save handler
}

// ═══════════════════════════════════════
// WORKFLOW ENGINE — نظام المعاملات الداخلية
// ═══════════════════════════════════════

// ─── المناصب (Positions) ───
var _wfPositions = [];
function wfLoadPositions() {
  var grid = document.getElementById('wfPositionsGrid');
  grid.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8;grid-column:1/-1;"><i class="fas fa-spinner fa-spin"></i> جاري التحميل...</div>';
  window._apiBridge.withSuccessHandler(function(list) {
    _wfPositions = list || [];
    if (!list.length) { grid.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8;grid-column:1/-1;font-style:italic;">لا توجد مناصب — اضغط "منصب جديد"</div>'; return; }
    var maxLevel = Math.max.apply(null, list.map(function(p) { return p.level || 0; })) || 1;
    var btnS = 'width:32px;height:32px;border-radius:8px;border:1px solid #e2e8f0;background:#f8fafc;color:#64748b;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;font-size:13px;';
    grid.innerHTML = list.map(function(p) {
      var pct = Math.round(((p.level || 0) / maxLevel) * 100);
      return '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:16px;padding:18px;">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">' +
          '<div style="font-size:15px;font-weight:800;color:#1e293b;"><i class="fas fa-id-badge" style="color:#3b82f6;margin-left:6px;"></i> ' + p.name + '</div>' +
          (p.isActive !== false ? '<span class="badge badge-green">فعال</span>' : '<span class="badge badge-red">معطل</span>') +
        '</div>' +
        '<div style="display:flex;align-items:center;gap:8px;margin-top:4px;">' +
          '<span style="font-size:12px;font-weight:700;color:#64748b;white-space:nowrap;">المستوى ' + (p.level || 0) + '</span>' +
          '<div style="height:6px;border-radius:3px;background:#e2e8f0;flex:1;max-width:120px;overflow:hidden;"><div style="height:100%;border-radius:3px;background:linear-gradient(90deg,#3b82f6,#8b5cf6);width:' + pct + '%;"></div></div>' +
        '</div>' +
        '<div style="display:flex;align-items:center;justify-content:space-between;margin-top:12px;padding-top:10px;border-top:1px solid #f1f5f9;">' +
          '<span style="font-size:12px;color:#94a3b8;">الصلاحية: ' + (p.level||0) + '</span>' +
          '<div style="display:flex;gap:6px;">' +
            '<button style="' + btnS + '" onclick="wfEditPosition(\'' + p.id + '\')"><i class="fas fa-edit"></i></button>' +
            '<button style="' + btnS + 'color:#ef4444;" onclick="wfDeletePosition(\'' + p.id + '\')"><i class="fas fa-trash"></i></button>' +
          '</div>' +
        '</div>' +
      '</div>';
    }).join('');
  }).getWfPositions();
}

function wfOpenPositionModal(data) {
  var d = data || {};
  document.getElementById('erpModalTitle').textContent = d.id ? 'تعديل منصب' : 'منصب جديد';
  document.getElementById('erpModalBody').innerHTML =
    '<input type="hidden" id="wfPosId" value="' + (d.id || '') + '">' +
    '<div class="form-row"><label>اسم المنصب *</label><input class="form-control" id="wfPosName" value="' + (d.name || '') + '"></div>' +
    '<div class="form-row"><label>المستوى (الأعلى = أكثر صلاحية)</label><input type="number" class="form-control" id="wfPosLevel" value="' + (d.level || 0) + '" min="0" max="100"></div>';
  document.getElementById('erpModalSaveBtn').onclick = function() {
    var name = document.getElementById('wfPosName').value;
    if (!name) return showToast('اسم المنصب مطلوب', true);
    loader(true);
    window._apiBridge.withSuccessHandler(function(r) {
      loader(false);
      if (r.success) { showToast('تم الحفظ'); erpCloseModal(); wfLoadPositions(); }
      else showToast(r.error, true);
    }).saveWfPosition({ id: document.getElementById('wfPosId').value || undefined, name: name, level: Number(document.getElementById('wfPosLevel').value) || 0 });
  };
  document.getElementById('erpModal').classList.remove('hidden');
}

function wfEditPosition(id) {
  var p = _wfPositions.find(function(x) { return x.id === id; });
  if (p) wfOpenPositionModal(p);
}

function wfDeletePosition(id) {
  if (!confirm('حذف هذا المنصب؟')) return;
  loader(true);
  window._apiBridge.withSuccessHandler(function(r) {
    loader(false);
    if (r.success) { showToast('تم الحذف'); wfLoadPositions(); }
    else showToast(r.error, true);
  }).deleteWfPosition(id);
}

// ─── أنواع المعاملات (Transaction Types) ───
var _wfTypes = [];
function wfLoadTypes() {
  var grid = document.getElementById('wfTypesGrid');
  grid.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8;grid-column:1/-1;"><i class="fas fa-spinner fa-spin"></i> جاري التحميل...</div>';
  window._apiBridge.withSuccessHandler(function(list) {
    _wfTypes = list || [];
    if (!list.length) { grid.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8;grid-column:1/-1;font-style:italic;">لا توجد أنواع — اضغط "نوع جديد"</div>'; return; }
    var icons = { EXPENSE: 'fa-money-bill-wave', PURCHASE: 'fa-shopping-cart', ASSET: 'fa-building', PAYMENT: 'fa-credit-card' };
    var colors = { EXPENSE: '#dc2626', PURCHASE: '#2563eb', ASSET: '#7c3aed', PAYMENT: '#059669' };
    grid.innerHTML = list.map(function(t) {
      var icon = icons[t.code] || 'fa-file-alt';
      var color = colors[t.code] || '#2563eb';
      return '<div style="display:flex;align-items:center;gap:14px;padding:18px;border:1.5px solid #e2e8f0;border-radius:16px;background:#fff;">' +
        '<div style="width:46px;height:46px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0;background:' + color + '15;color:' + color + ';"><i class="fas ' + icon + '"></i></div>' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="font-size:15px;font-weight:800;color:#1e293b;">' + t.name + '</div>' +
          '<div style="font-size:12px;color:#94a3b8;font-family:monospace;margin-top:2px;">' + (t.code || '') + '</div>' +
        '</div>' +
        (t.isActive !== false ? '<span class="badge badge-green">فعال</span>' : '<span class="badge badge-red">معطل</span>') +
        ' <button class="btn-icon" style="margin-right:8px;" onclick="wfEditType(\'' + t.id + '\')"><i class="fas fa-edit"></i></button>' +
      '</div>';
    }).join('');
  }).getWfTypes();
}

function wfOpenTypeModal(data) {
  var d = data || {};
  document.getElementById('erpModalTitle').textContent = d.id ? 'تعديل نوع معاملة' : 'نوع معاملة جديد';
  document.getElementById('erpModalBody').innerHTML =
    '<input type="hidden" id="wfTypeId" value="' + (d.id || '') + '">' +
    '<div class="form-row"><label>اسم النوع *</label><input class="form-control" id="wfTypeName" value="' + (d.name || '') + '"></div>' +
    '<div class="form-row"><label>الرمز *</label><input class="form-control" id="wfTypeCode" value="' + (d.code || '') + '" placeholder="مثال: EXPENSE, PURCHASE"></div>';
  document.getElementById('erpModalSaveBtn').onclick = function() {
    var name = document.getElementById('wfTypeName').value;
    var code = document.getElementById('wfTypeCode').value;
    if (!name || !code) return showToast('الاسم والرمز مطلوبان', true);
    loader(true);
    window._apiBridge.withSuccessHandler(function(r) {
      loader(false);
      if (r.success) { showToast('تم الحفظ'); erpCloseModal(); wfLoadTypes(); }
      else showToast(r.error, true);
    }).saveWfType({ id: document.getElementById('wfTypeId').value || undefined, name: name, code: code });
  };
  document.getElementById('erpModal').classList.remove('hidden');
}

function wfEditType(id) {
  var t = _wfTypes.find(function(x) { return x.id === id; });
  if (t) wfOpenTypeModal(t);
}

// ─── خطوات سير العمل (Workflow Definitions) ───
var _wfDefs = [];
var _wfDefsMode = 'role'; // 'role' | 'type'

function wfDefsSetMode(mode) {
  _wfDefsMode = mode;
  var roleBtn = document.getElementById('wfDefsModeRole');
  var typeBtn = document.getElementById('wfDefsModeType');
  var roleWrap = document.getElementById('wfDefsRoleFilterWrap');
  var typeWrap = document.getElementById('wfDefsTypeFilterWrap');
  if (mode === 'role') {
    roleBtn.style.background='#fff'; roleBtn.style.color='#0ea5e9'; roleBtn.style.boxShadow='0 1px 3px rgba(0,0,0,.05)';
    typeBtn.style.background='transparent'; typeBtn.style.color='#64748b'; typeBtn.style.boxShadow='none';
    roleWrap.style.display='flex'; typeWrap.style.display='none';
  } else {
    typeBtn.style.background='#fff'; typeBtn.style.color='#0ea5e9'; typeBtn.style.boxShadow='0 1px 3px rgba(0,0,0,.05)';
    roleBtn.style.background='transparent'; roleBtn.style.color='#64748b'; roleBtn.style.boxShadow='none';
    typeWrap.style.display='flex'; roleWrap.style.display='none';
  }
  wfLoadDefs();
}

function wfInitDefs() {
  // Populate both dropdowns — roles (default) and types
  var roleSel = document.getElementById('wfDefsRoleFilter');
  var typeSel = document.getElementById('wfDefsTypeFilter');

  Promise.all([
    new Promise(function(r){ window._apiBridge.withSuccessHandler(r).getWfTypes(); }),
    new Promise(function(r){ window._apiBridge.withSuccessHandler(r).getWfPositions(); })
  ]).then(function(results) {
    _wfTypes = results[0] || [];
    var positions = results[1] || [];

    // Fill type dropdown
    var curType = typeSel.value;
    typeSel.innerHTML = '<option value="">— اختر نوع المعاملة —</option>';
    _wfTypes.forEach(function(t) {
      var opt = document.createElement('option');
      opt.value = t.id; opt.textContent = t.name + ' (' + (t.code||'') + ')';
      typeSel.appendChild(opt);
    });
    if (curType) typeSel.value = curType;

    // Fill role dropdown — sorted by level asc (workforce order)
    var curRole = roleSel.value;
    roleSel.innerHTML = '<option value="">— اختر المنصب —</option>';
    positions.slice().sort(function(a,b){return (a.level||0)-(b.level||0);}).forEach(function(p) {
      var opt = document.createElement('option');
      opt.value = p.id;
      opt.textContent = p.name + ' (Level ' + (p.level||'?') + ')';
      roleSel.appendChild(opt);
    });
    if (curRole) roleSel.value = curRole;

    // Default mode: role-based view
    wfDefsSetMode(_wfDefsMode || 'role');
    if ((_wfDefsMode === 'role' && curRole) || (_wfDefsMode === 'type' && curType)) wfLoadDefs();
  });
}

function wfLoadDefs() {
  if (_wfDefsMode === 'role') return _wfLoadDefsByRole();
  return _wfLoadDefsByType();
}

function _wfLoadDefsByRole() {
  var posId = document.getElementById('wfDefsRoleFilter').value;
  var container = document.getElementById('wfDefsContainer');
  if (!posId) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8;font-style:italic;background:#f8fafc;border-radius:14px;border:1px dashed #e2e8f0;">اختر المنصب الإداري أولاً</div>';
    return;
  }
  container.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8;"><i class="fas fa-spinner fa-spin"></i> جاري التحميل...</div>';
  window._apiBridge.withSuccessHandler(function(list) {
    _wfDefs = list || [];
    if (!list.length) {
      container.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8;font-style:italic;background:#f8fafc;border-radius:14px;border:1px dashed #e2e8f0;">لا توجد خطوات مرتبطة بهذا المنصب</div>';
      return;
    }
    // Group by transaction type
    var byType = {};
    list.forEach(function(w) {
      var k = w.transactionTypeId || 'unknown';
      if (!byType[k]) byType[k] = { typeName: w.typeName || '', typeCode: w.typeCode || '', steps: [] };
      byType[k].steps.push(w);
    });

    var permOn = 'width:22px;height:22px;border-radius:5px;display:inline-flex;align-items:center;justify-content:center;font-size:10px;background:#dcfce7;color:#16a34a;';
    var permOff = 'width:22px;height:22px;border-radius:5px;display:inline-flex;align-items:center;justify-content:center;font-size:10px;background:#f1f5f9;color:#cbd5e1;';
    var sBtn = 'width:26px;height:26px;border-radius:5px;border:1px solid #e2e8f0;background:#f8fafc;color:#64748b;font-size:11px;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;';

    var html = '<div style="display:flex;flex-direction:column;gap:14px;">';
    Object.keys(byType).forEach(function(k) {
      var g = byType[k];
      html += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:14px;">' +
        '<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;padding-bottom:10px;border-bottom:1px dashed #e5e7eb;">' +
          '<div style="width:36px;height:36px;border-radius:10px;background:#eff6ff;color:#1e40af;display:flex;align-items:center;justify-content:center;"><i class="fas fa-list-alt"></i></div>' +
          '<div><div style="font-size:14px;font-weight:800;color:#0f172a;">' + g.typeName + '</div>' +
          '<div style="font-size:11px;color:#64748b;font-family:monospace;">' + g.typeCode + '</div></div>' +
          '<div style="margin-right:auto;font-size:11px;color:#64748b;">' + g.steps.length + ' خطوة</div>' +
        '</div>' +
        '<div style="display:flex;gap:8px;flex-wrap:wrap;">';
      g.steps.forEach(function(w) {
        var cBg = w.isFinal ? 'linear-gradient(135deg,#f0fdf4,#dcfce7)' : 'linear-gradient(135deg,#eff6ff,#dbeafe)';
        var cColor = w.isFinal ? '#166534' : '#1e40af';
        html += '<div style="min-width:180px;background:' + cBg + ';border-radius:10px;padding:10px 12px;">' +
          '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">' +
            '<div style="width:22px;height:22px;border-radius:50%;background:' + cColor + ';color:#fff;font-size:11px;font-weight:900;display:flex;align-items:center;justify-content:center;">' + w.stepOrder + '</div>' +
            '<div style="font-size:12px;font-weight:800;color:#0f172a;">' + w.stepName + '</div>' +
          '</div>' +
          '<div style="display:flex;gap:3px;justify-content:flex-start;margin-top:4px;flex-wrap:wrap;">' +
            (w.requireSameBranch!==false ? '<span style="padding:1px 5px;background:#dbeafe;color:#1e40af;border-radius:4px;font-size:9px;font-weight:700;">نفس الفرع</span>' : '') +
            (w.requireSameDepartment ? '<span style="padding:1px 5px;background:#ede9fe;color:#6d28d9;border-radius:4px;font-size:9px;font-weight:700;">نفس القسم</span>' : '') +
            '<span style="padding:1px 5px;background:#dcfce7;color:#166534;border-radius:4px;font-size:9px;font-weight:700;">' + (w.assignmentStrategy === 'first' ? 'الأول' : 'الأقل انشغالاً') + '</span>' +
          '</div>' +
          '<div style="display:flex;gap:3px;justify-content:flex-start;margin-top:6px;">' +
            '<div style="' + ((w.canApprove !== false) ? permOn : permOff) + '" title="موافقة"><i class="fas fa-check"></i></div>' +
            '<div style="' + ((w.canReject !== false) ? permOn : permOff) + '" title="رفض"><i class="fas fa-times"></i></div>' +
            '<div style="' + (w.canReturn ? permOn : permOff) + '" title="إرجاع"><i class="fas fa-undo"></i></div>' +
            '<div style="' + (w.canEditAmount ? permOn : permOff) + '" title="تعديل المبلغ"><i class="fas fa-dollar-sign"></i></div>' +
            (w.isFinal ? '<div style="' + permOn + '" title="نهائية"><i class="fas fa-flag-checkered"></i></div>' : '') +
          '</div>' +
          '<div style="display:flex;gap:4px;margin-top:6px;">' +
            '<button style="' + sBtn + '" onclick="wfEditDef(\'' + w.id + '\')"><i class="fas fa-edit"></i></button>' +
            '<button style="' + sBtn + 'color:#ef4444;" onclick="wfDeleteDef(\'' + w.id + '\')"><i class="fas fa-trash"></i></button>' +
          '</div>' +
        '</div>';
      });
      html += '</div></div>';
    });
    html += '</div>';
    container.innerHTML = html;
  }).getWfDefsByRole(posId);
}

function _wfLoadDefsByType() {
  var typeId = document.getElementById('wfDefsTypeFilter').value;
  var container = document.getElementById('wfDefsContainer');
  if (!typeId) { container.innerHTML = '<div class="wf-pipeline-empty">اختر نوع المعاملة أولاً</div>'; return; }
  container.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8;"><i class="fas fa-spinner fa-spin"></i> جاري التحميل...</div>';
  window._apiBridge.withSuccessHandler(function(list) {
    _wfDefs = list || [];
    if (!list.length) { container.innerHTML = '<div style="text-align:center;padding:40px;color:#94a3b8;font-style:italic;background:#f8fafc;border-radius:14px;border:1px dashed #e2e8f0;">لا توجد خطوات — اضغط "خطوة جديدة"</div>'; return; }
    var circleS = 'width:56px;height:56px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:900;position:relative;z-index:1;';
    var bodyS = 'text-align:center;margin-top:10px;padding:12px 14px;background:#fff;border:1px solid #e2e8f0;border-radius:12px;min-width:140px;box-shadow:0 2px 8px rgba(0,0,0,0.02);';
    var permOn = 'width:24px;height:24px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;font-size:11px;background:#dcfce7;color:#16a34a;';
    var permOff = 'width:24px;height:24px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;font-size:11px;background:#f1f5f9;color:#cbd5e1;';
    var sBtn = 'width:28px;height:28px;border-radius:6px;border:1px solid #e2e8f0;background:#f8fafc;color:#64748b;font-size:12px;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;';
    var html = '<div style="display:flex;align-items:flex-start;gap:0;overflow-x:auto;padding:20px 10px;">';
    list.forEach(function(w, i) {
      if (i > 0) html += '<div style="display:flex;align-items:center;padding-top:14px;color:#94a3b8;font-size:18px;min-width:32px;justify-content:center;"><i class="fas fa-chevron-left"></i></div>';
      var cBg = w.isFinal ? 'linear-gradient(135deg,#f0fdf4,#dcfce7)' : 'linear-gradient(135deg,#eff6ff,#dbeafe)';
      var cBorder = w.isFinal ? '2.5px solid #86efac' : '2.5px solid #93c5fd';
      var cColor = w.isFinal ? '#166534' : '#1e40af';
      var roleChip = w.positionName
        ? '<div style="display:inline-flex;align-items:center;gap:4px;padding:3px 10px;background:#ede9fe;color:#6d28d9;border-radius:8px;font-size:11px;font-weight:700;margin-top:4px;"><i class="fas fa-id-badge"></i>' + w.positionName + '</div>'
        : '<div style="color:#94a3b8;font-size:11px;margin-top:4px;">أي منصب</div>';
      var scopeChips = '<div style="display:flex;gap:3px;justify-content:center;margin-top:5px;flex-wrap:wrap;">';
      if (w.requireSameBranch !== false) scopeChips += '<span style="padding:1px 6px;background:#dbeafe;color:#1e40af;border-radius:6px;font-size:9px;font-weight:700;">نفس الفرع</span>';
      if (w.requireSameDepartment) scopeChips += '<span style="padding:1px 6px;background:#ede9fe;color:#6d28d9;border-radius:6px;font-size:9px;font-weight:700;">نفس القسم</span>';
      if (w.assignmentStrategy === 'first') scopeChips += '<span style="padding:1px 6px;background:#fef3c7;color:#92400e;border-radius:6px;font-size:9px;font-weight:700;">الأول</span>';
      else scopeChips += '<span style="padding:1px 6px;background:#dcfce7;color:#166534;border-radius:6px;font-size:9px;font-weight:700;">الأقل انشغالاً</span>';
      scopeChips += '</div>';
      html += '<div style="display:flex;flex-direction:column;align-items:center;min-width:170px;max-width:220px;flex-shrink:0;">' +
        '<div style="' + circleS + 'background:' + cBg + ';border:' + cBorder + ';color:' + cColor + ';">' + w.stepOrder + '</div>' +
        '<div style="' + bodyS + '">' +
          '<div style="font-size:13px;font-weight:800;color:#1e293b;margin-bottom:4px;">' + w.stepName + '</div>' +
          roleChip +
          scopeChips +
          '<div style="display:flex;gap:4px;justify-content:center;margin-top:6px;">' +
            '<div style="' + ((w.canApprove !== false) ? permOn : permOff) + '" title="الموافقة"><i class="fas fa-check"></i></div>' +
            '<div style="' + ((w.canReject  !== false) ? permOn : permOff) + '" title="الرفض"><i class="fas fa-times"></i></div>' +
            '<div style="' + (w.canReturn ? permOn : permOff) + '" title="إرجاع"><i class="fas fa-undo"></i></div>' +
            '<div style="' + (w.canEditAmount ? permOn : permOff) + '" title="تعديل المبلغ"><i class="fas fa-dollar-sign"></i></div>' +
            (w.isFinal ? '<div style="' + permOn + '" title="نهائية"><i class="fas fa-flag-checkered"></i></div>' : '') +
          '</div>' +
          '<div style="display:flex;gap:4px;justify-content:center;margin-top:8px;">' +
            '<button style="' + sBtn + '" onclick="wfEditDef(\'' + w.id + '\')"><i class="fas fa-edit"></i></button>' +
            '<button style="' + sBtn + 'color:#ef4444;" onclick="wfDeleteDef(\'' + w.id + '\')"><i class="fas fa-trash"></i></button>' +
          '</div>' +
        '</div>' +
      '</div>';
    });
    html += '</div>';
    container.innerHTML = html;
  }).getWfDefs(typeId);
}

function wfOpenDefModal(data) {
  var d = data || {};
  var typeId = document.getElementById('wfDefsTypeFilter').value;
  // In role mode: the selected type isn't set — we ask via dropdown inside the modal.
  // If editing, the type comes from the record.
  if (!typeId) typeId = d.transactionTypeId || '';
  if (!typeId && !d.id && _wfDefsMode === 'type') return showToast('اختر نوع المعاملة أولاً', true);
  // Pre-fill role if in role mode and creating new
  if (!d.positionId && _wfDefsMode === 'role' && !d.id) {
    d.positionId = document.getElementById('wfDefsRoleFilter').value || '';
  }
  // Load positions for dropdown
  window._apiBridge.withSuccessHandler(function(positions) {
    var posOpts = (positions || []).map(function(p) {
      return '<option value="' + p.id + '"' + (d.positionId === p.id ? ' selected' : '') + '>' + p.name + ' (مستوى ' + p.level + ')</option>';
    }).join('');
    var reqBranch = (d.requireSameBranch === undefined) ? true : !!d.requireSameBranch;
    var reqDept   = !!d.requireSameDepartment;
    var strategy  = d.assignmentStrategy || 'least_busy';
    var cApprove  = (d.canApprove === undefined) ? true : !!d.canApprove;
    var cReject   = (d.canReject  === undefined) ? true : !!d.canReject;
    var cEdit     = !!d.canEdit;

    // Type picker — shown only when creating from role mode (no pre-selected type)
    var typeSelectorHtml = '';
    var needTypeSelector = !typeId && !d.id;
    if (needTypeSelector) {
      var tOpts = (_wfTypes||[]).map(function(t) {
        return '<option value="' + t.id + '">' + t.name + ' (' + (t.code||'') + ')</option>';
      }).join('');
      typeSelectorHtml =
        '<div class="form-row"><label><i class="fas fa-list-alt" style="color:#3b82f6;"></i> نوع المعاملة *</label>' +
          '<select class="form-control" id="wfDefTypePicker"><option value="">— اختر النوع —</option>' + tOpts + '</select>' +
        '</div>';
    }

    document.getElementById('erpModalTitle').textContent = d.id ? 'تعديل خطوة' : 'خطوة جديدة';
    document.getElementById('erpModalBody').innerHTML =
      '<input type="hidden" id="wfDefId" value="' + (d.id || '') + '">' +
      '<input type="hidden" id="wfDefTypeId" value="' + (typeId || '') + '">' +
      typeSelectorHtml +
      '<div style="display:grid;grid-template-columns:1fr 2fr;gap:12px;">' +
        '<div class="form-row"><label>ترتيب الخطوة *</label><input type="number" class="form-control" id="wfDefOrder" value="' + (d.stepOrder || (_wfDefs.length + 1)) + '" min="1"></div>' +
        '<div class="form-row"><label>اسم الخطوة <span style="color:#94a3b8;font-weight:normal;">(اختياري)</span></label>' +
          '<input class="form-control" id="wfDefName" value="' + (d.stepName || '').replace(/"/g,'&quot;') + '" placeholder="مثال: مراجعة المحاسب">' +
          '<div style="font-size:11px;color:#64748b;margin-top:4px;line-height:1.5;"><i class="fas fa-info-circle" style="color:#0ea5e9;"></i> هذا هو العنوان الإداري الظاهر في شريط المسار وعمود «الخطوة الحالية» وسجل الحركة. إن تركته فارغاً سيُولَّد تلقائياً من اسم المنصب.</div>' +
        '</div>' +
      '</div>' +

      '<div class="form-row"><label><i class="fas fa-id-badge" style="color:#8b5cf6;"></i> المسمى الوظيفي المسؤول (Role) *</label>' +
        '<select class="form-control" id="wfDefPosition"><option value="">— أي منصب —</option>' + posOpts + '</select>' +
        '<div style="font-size:11px;color:#64748b;margin-top:4px;"><i class="fas fa-info-circle"></i> سيتم اختيار الموظف تلقائياً حسب هذا المسمى.</div>' +
      '</div>' +

      '<div style="border:1px dashed #c7d2fe;background:#eff6ff;border-radius:12px;padding:10px 12px;margin-top:6px;">' +
        '<div style="font-size:12px;font-weight:800;color:#1e40af;margin-bottom:8px;"><i class="fas fa-filter"></i> قواعد اختيار الموظف</div>' +
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">' +
          '<label style="display:flex;align-items:center;gap:6px;background:#fff;padding:6px 10px;border-radius:8px;cursor:pointer;font-size:12px;"><input type="checkbox" id="wfDefReqBranch" ' + (reqBranch?'checked':'') + '> نفس الفرع</label>' +
          '<label style="display:flex;align-items:center;gap:6px;background:#fff;padding:6px 10px;border-radius:8px;cursor:pointer;font-size:12px;"><input type="checkbox" id="wfDefReqDept" ' + (reqDept?'checked':'') + '> نفس القسم</label>' +
        '</div>' +
        '<div class="form-row" style="margin-bottom:0;"><label style="font-size:11.5px;">طريقة التوزيع</label>' +
          '<select class="form-control" id="wfDefStrategy">' +
            '<option value="least_busy"' + (strategy==='least_busy'?' selected':'') + '>الأقل انشغالاً (least busy)</option>' +
            '<option value="first"' + (strategy==='first'?' selected':'') + '>الأول في القائمة (first)</option>' +
          '</select>' +
        '</div>' +
      '</div>' +

      '<div style="border:1px dashed #bbf7d0;background:#f0fdf4;border-radius:12px;padding:10px 12px;margin-top:10px;">' +
        '<div style="font-size:12px;font-weight:800;color:#166534;margin-bottom:8px;"><i class="fas fa-check-circle"></i> صلاحيات هذه الخطوة</div>' +
        '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;">' +
          '<label style="display:flex;align-items:center;gap:6px;background:#fff;padding:6px 10px;border-radius:8px;cursor:pointer;font-size:12px;"><input type="checkbox" id="wfDefCApprove" ' + (cApprove?'checked':'') + '> الموافقة</label>' +
          '<label style="display:flex;align-items:center;gap:6px;background:#fff;padding:6px 10px;border-radius:8px;cursor:pointer;font-size:12px;"><input type="checkbox" id="wfDefCReject" ' + (cReject?'checked':'') + '> الرفض</label>' +
          '<label style="display:flex;align-items:center;gap:6px;background:#fff;padding:6px 10px;border-radius:8px;cursor:pointer;font-size:12px;"><input type="checkbox" id="wfDefReturn" ' + (d.canReturn !== false ? 'checked' : '') + '> الإرجاع</label>' +
          '<label style="display:flex;align-items:center;gap:6px;background:#fff;padding:6px 10px;border-radius:8px;cursor:pointer;font-size:12px;"><input type="checkbox" id="wfDefCEdit" ' + (cEdit?'checked':'') + '> التعديل</label>' +
          '<label style="display:flex;align-items:center;gap:6px;background:#fff;padding:6px 10px;border-radius:8px;cursor:pointer;font-size:12px;"><input type="checkbox" id="wfDefEditAmt" ' + (d.canEditAmount ? 'checked' : '') + '> تعديل المبلغ</label>' +
          '<label style="display:flex;align-items:center;gap:6px;background:#fff;padding:6px 10px;border-radius:8px;cursor:pointer;font-size:12px;"><input type="checkbox" id="wfDefFinal" ' + (d.isFinal ? 'checked' : '') + '> خطوة نهائية</label>' +
        '</div>' +
      '</div>';
    document.getElementById('erpModalSaveBtn').onclick = function() {
      var stepName = document.getElementById('wfDefName').value;  // optional — backend auto-generates if empty
      // Resolve type: pre-selected, editing-record, or picker
      var finalTypeId = document.getElementById('wfDefTypeId').value;
      var picker = document.getElementById('wfDefTypePicker');
      if (!finalTypeId && picker) finalTypeId = picker.value;
      if (!finalTypeId && d.transactionTypeId) finalTypeId = d.transactionTypeId;
      if (!finalTypeId) return showToast('اختر نوع المعاملة', true);
      loader(true);
      window._apiBridge.withSuccessHandler(function(r) {
        loader(false);
        if (r.success) { showToast('تم الحفظ'); erpCloseModal(); wfLoadDefs(); }
        else showToast(r.error, true);
      }).saveWfDef({
        id: document.getElementById('wfDefId').value || undefined,
        transactionTypeId: finalTypeId,
        stepOrder: Number(document.getElementById('wfDefOrder').value) || 1,
        stepName: stepName,
        positionId: document.getElementById('wfDefPosition').value || null,
        canEditAmount: document.getElementById('wfDefEditAmt').checked,
        canReturn: document.getElementById('wfDefReturn').checked,
        canApprove: document.getElementById('wfDefCApprove').checked,
        canReject: document.getElementById('wfDefCReject').checked,
        canEdit: document.getElementById('wfDefCEdit').checked,
        isFinal: document.getElementById('wfDefFinal').checked,
        requireSameBranch: document.getElementById('wfDefReqBranch').checked,
        requireSameDepartment: document.getElementById('wfDefReqDept').checked,
        assignmentStrategy: document.getElementById('wfDefStrategy').value || 'least_busy'
      });
    };
    document.getElementById('erpModal').classList.remove('hidden');
  }).getWfPositions();
}

function wfEditDef(id) {
  var d = _wfDefs.find(function(x) { return x.id === id; });
  if (d) wfOpenDefModal(d);
}

function wfDeleteDef(id) {
  if (!confirm('حذف هذه الخطوة؟')) return;
  loader(true);
  window._apiBridge.withSuccessHandler(function(r) {
    loader(false);
    if (r.success) { showToast('تم الحذف'); wfLoadDefs(); }
    else showToast(r.error, true);
  }).deleteWfDef(id);
}

// ─── صندوق المعاملات (Transaction Inbox) ───
// ─── shared helpers for workflow UI ────────────────────────────
window._wfImpColors = { critical:'#dc2626', high:'#ea580c', medium:'#ca8a04', low:'#16a34a' };
window._wfImpBgs    = { critical:'#fee2e2', high:'#ffedd5', medium:'#fef9c3', low:'#dcfce7' };
window._wfImpLabels = { critical:'عاجل', high:'عالي', medium:'متوسط', low:'منخفض' };
window._wfStatLbl   = { pending:'قيد الانتظار', in_progress:'قيد التنفيذ', approved:'معتمدة', rejected:'مرفوضة', closed:'مغلقة', draft:'مسودة' };
window._wfStatClrs  = { pending:'#f59e0b', in_progress:'#3b82f6', approved:'#10b981', rejected:'#ef4444', closed:'#6b7280', draft:'#94a3b8' };

function _wfImpBadge(imp) {
  var c = window._wfImpColors[imp] || '#6b7280';
  var bg = window._wfImpBgs[imp] || '#f3f4f6';
  return '<span style="padding:3px 10px;border-radius:8px;background:'+bg+';color:'+c+';font-size:11px;font-weight:800;"><i class="fas fa-circle" style="font-size:7px;margin-left:4px;"></i>'+(window._wfImpLabels[imp]||imp)+'</span>';
}

function _wfStatBadge(s) {
  var c = window._wfStatClrs[s] || '#94a3b8';
  return '<span style="padding:3px 10px;border-radius:8px;background:'+c+'20;color:'+c+';font-size:11px;font-weight:800;">'+(window._wfStatLbl[s]||s)+'</span>';
}

// V5-PERF: pagination — render in chunks of 100 rows.
// Previous behavior: 10,000 rows → 10s+ to render synchronously, browser frozen.
window._wfInboxPageSize = 100;
window._wfInboxPagedList = null;   // last full list — used for "load more"
window._wfInboxPagedShown = 0;
window._wfInboxRenderRow = null;   // hoisted row renderer (set below)

function wfLoadInbox() {
  // V5.7.2: show "wipe all" button only for developers
  var wipeBtn = document.getElementById('wfWipeAllBtn');
  if (wipeBtn) {
    var isDev = (window.state && window.state.isDeveloper) || (typeof window._isDeveloperUser === 'function' && window._isDeveloperUser());
    wipeBtn.style.display = isDev ? '' : 'none';
  }
  var tb = document.getElementById('wfInboxBody');
  tb.innerHTML = '<tr><td colspan="12" class="empty-msg"><i class="fas fa-spinner fa-spin"></i> جاري التحميل...</td></tr>';
  // V5-UX: 12s timeout — show retry button if backend hangs
  var TXN_TIMEOUT = (window.TxnConst && window.TxnConst.TXN_FETCH_TIMEOUT_MS) || 12000;
  var fetchTimeout = setTimeout(function(){
    tb.innerHTML = '<tr><td colspan="12" class="empty-msg" style="color:#b91c1c;">' +
      '<i class="fas fa-triangle-exclamation"></i> فشل تحميل القائمة (انتهت المهلة).' +
      '<button class="btn btn-sm btn-primary" style="margin-inline-start:10px;" onclick="wfLoadInbox()">إعادة المحاولة</button>' +
      '</td></tr>';
  }, TXN_TIMEOUT);
  var status = (document.getElementById('wfInboxStatusFilter') || {}).value || '';
  var params = {};
  if (status) params.status = status;
  window._apiBridge.withSuccessHandler(function(list) {
    clearTimeout(fetchTimeout);
    if (!list || !list.length) {
      tb.innerHTML = '<tr><td colspan="12" class="empty-msg">لا توجد معاملات</td></tr>';
      document.getElementById('wfInboxStats').innerHTML = '';
      return;
    }
    // V5: client-side search filter (in addition to server filter)
    var q = ((document.getElementById('wfInboxSearch')||{}).value || '').trim().toLowerCase();
    if (q) {
      list = list.filter(function(t){
        return (t.title||'').toLowerCase().indexOf(q) >= 0
            || (t.txnNumber||'').toLowerCase().indexOf(q) >= 0
            || (t.createdBy||'').toLowerCase().indexOf(q) >= 0
            || (t.currentAssignee||'').toLowerCase().indexOf(q) >= 0;
      });
    }
    var counts = { pending:0, in_progress:0, approved:0, rejected:0, closed:0 };
    list.forEach(function(t) { if (counts.hasOwnProperty(t.status)) counts[t.status]++; });
    var statsHtml = '';
    Object.keys(counts).forEach(function(k) {
      statsHtml += '<div style="display:flex;align-items:center;gap:8px;padding:8px 16px;background:#fff;border:1px solid #e2e8f0;border-radius:10px;font-size:13px;font-weight:700;">' +
        '<span style="width:10px;height:10px;border-radius:50%;background:' + (window._wfStatClrs[k]||'#94a3b8') + ';flex-shrink:0;"></span>' +
        '<span>' + window._wfStatLbl[k] + '</span><span style="font-weight:900;color:#0f172a;">' + counts[k] + '</span></div>';
    });
    statsHtml += '<div style="margin-inline-start:auto;font-size:12px;color:#64748b;">الإجمالي: <strong>' + list.length.toLocaleString() + '</strong></div>';
    document.getElementById('wfInboxStats').innerHTML = statsHtml;
    // V5-PERF: cache full list for load-more, render only first PAGE
    window._wfInboxPagedList = list;
    window._wfInboxPagedShown = 0;
    tb.innerHTML = '';
    _wfInboxRenderNextPage();
  }).getWfTransactions(params);
}
function _wfInboxRenderNextPage(){
  if (!window._wfInboxPagedList) return;
  var tb = document.getElementById('wfInboxBody');
  var list = window._wfInboxPagedList;
  var from = window._wfInboxPagedShown;
  var to = Math.min(list.length, from + window._wfInboxPageSize);
  var slice = list.slice(from, to);
  // Remove any previous "load more" row
  var prevMore = document.getElementById('wfInboxLoadMore');
  if (prevMore) prevMore.remove();
  // Render the slice
  slice.forEach(function(t){
    var html = window._wfInboxRenderRow ? window._wfInboxRenderRow(t) : '';
    if (html) tb.insertAdjacentHTML('beforeend', html);
  });
  window._wfInboxPagedShown = to;
  // Add "load more" footer if there's more data
  if (to < list.length) {
    var remaining = list.length - to;
    tb.insertAdjacentHTML('beforeend',
      '<tr id="wfInboxLoadMore"><td colspan="12" style="text-align:center;padding:14px;background:#f8fafc;">' +
      '<button class="btn btn-secondary" onclick="_wfInboxRenderNextPage()">' +
      '<i class="fas fa-chevron-down"></i> تحميل المزيد (' + remaining.toLocaleString() + ' معاملة متبقية)</button>' +
      '</td></tr>');
  }
}
// V5: debounced search input listener (wires once)
window._wfSearchInputWired = window._wfSearchInputWired || false;
if (!window._wfSearchInputWired) {
  document.addEventListener('DOMContentLoaded', function(){
    var inp = document.getElementById('wfInboxSearch');
    if (!inp) return;
    var t;
    inp.addEventListener('input', function(){
      clearTimeout(t);
      t = setTimeout(function(){ window.wfPersistFiltersAndLoad(); }, 350);
    });
  });
  window._wfSearchInputWired = true;
}
// V5: bulk-action selection state
window._wfBulkSelected = window._wfBulkSelected || {};

// Single-row renderer used by both initial render + load-more.
window._wfInboxRenderRow = function(t){
  var dt = t.createdAt ? new Date(t.createdAt).toLocaleDateString('en-GB') : '';
  var canAct = t.status === 'pending' || t.status === 'in_progress';
  var idEsc = String(t.id || '').replace(/'/g, '&#39;');
  var actions = '<div class="wf-inbox-actions">' +
    '<button class="btn btn-sm btn-light" onclick="wfViewTxn(\'' + idEsc + '\')" aria-label="عرض"><i class="fas fa-eye"></i></button>';
  if (canAct) {
    actions += '<button class="btn btn-sm btn-success" onclick="wfTxnAction(\'' + idEsc + '\',\'approve\')" title="موافقة" aria-label="اعتماد"><i class="fas fa-check"></i></button>';
    actions += '<button class="btn btn-sm btn-danger" onclick="wfTxnAction(\'' + idEsc + '\',\'reject\')" title="رفض" aria-label="رفض"><i class="fas fa-times"></i></button>';
    actions += '<button class="btn btn-sm" style="background:#fef3c7;color:#92400e;" onclick="wfTxnAction(\'' + idEsc + '\',\'return\')" title="إرجاع" aria-label="إعادة"><i class="fas fa-undo"></i></button>';
    actions += '<button class="btn btn-sm" style="background:#f3e8ff;color:#7c3aed;" onclick="wfForwardTxn(\'' + idEsc + '\')" title="تحويل" aria-label="تحويل"><i class="fas fa-share"></i></button>';
  }
  actions += '</div>';
  // V5: status badge from shared TxnConst (with color contrast)
  var statusHtml = (window.TxnConst && window.TxnConst.statusBadge)
    ? window.TxnConst.statusBadge(t.status)
    : _wfStatBadge(t.status);
  // V5: bulk-action checkbox (only for actionable rows)
  var checkbox = canAct
    ? '<input type="checkbox" data-bulk-id="' + idEsc + '" onchange="wfBulkToggle(\'' + idEsc + '\', this)" '+(window._wfBulkSelected[t.id]?'checked':'')+' aria-label="تحديد المعاملة">'
    : '';
  return '<tr class="wf-inbox-row" data-txn-id="' + idEsc + '">' +
    '<td>' + checkbox + '</td>' +
    '<td>' + _wfImpBadge(t.importance||'medium') + '</td>' +
    '<td>' + statusHtml + '</td>' +
    '<td><span class="wf-txn-number" style="font-size:11px;font-family:monospace;">' + (t.txnNumber||'') + '</span></td>' +
    '<td><span class="badge badge-blue">' + (t.typeName||'') + '</span></td>' +
    '<td style="font-size:12px;">' + (t.branchName||t.branchCode||'—') + '</td>' +
    '<td style="font-size:12px;">' + (t.deptName||t.deptCode||'—') + '</td>' +
    '<td style="font-weight:700;max-width:220px;overflow:hidden;text-overflow:ellipsis;">' + (t.title || '') + '</td>' +
    '<td><span class="wf-txn-amount">' + (Number(t.amount)||0).toLocaleString('en',{minimumFractionDigits:2}) + '</span></td>' +
    '<td style="font-size:12px;"><div style="font-weight:700;color:#1e40af;">' + (t.currentAssignee||'—') + '</div>' +
    (t.currentRoleName ? '<div style="font-size:10px;color:#8b5cf6;font-weight:700;"><i class="fas fa-id-badge" style="font-size:8px;"></i> ' + t.currentRoleName + '</div>' : '') + '</td>' +
    '<td style="font-size:12px;color:#64748b;">' + dt + '</td>' +
    '<td>' + actions + '</td>' +
  '</tr>';
};

// V5: bulk actions wiring
window.wfBulkToggle = function(id, el){
  if (el && el.checked) window._wfBulkSelected[id] = true;
  else delete window._wfBulkSelected[id];
  _wfBulkUpdateBar();
};
window.wfBulkToggleAll = function(el){
  var rows = document.querySelectorAll('#wfInboxBody input[data-bulk-id]');
  rows.forEach(function(cb){
    cb.checked = !!el.checked;
    var id = cb.getAttribute('data-bulk-id');
    if (el.checked) window._wfBulkSelected[id] = true;
    else delete window._wfBulkSelected[id];
  });
  _wfBulkUpdateBar();
};
window.wfBulkClear = function(){
  window._wfBulkSelected = {};
  document.querySelectorAll('#wfInboxBody input[data-bulk-id]').forEach(function(cb){ cb.checked = false; });
  var sa = document.getElementById('wfInboxSelectAll'); if (sa) sa.checked = false;
  _wfBulkUpdateBar();
};
function _wfBulkUpdateBar(){
  var ids = Object.keys(window._wfBulkSelected);
  var bar = document.getElementById('wfBulkBar');
  var cnt = document.getElementById('wfBulkCount');
  if (cnt) cnt.textContent = ids.length;
  if (bar) bar.style.display = ids.length ? 'flex' : 'none';
}
// V5.7.2 — Developer-only: wipe ALL transactions in 4 stages with extreme safeguards.
//   Stage 1: confirm intent
//   Stage 2: dryRun preview shows exact counts (no destructive call yet)
//   Stage 3: type "DELETE-ALL-FOREVER" to confirm
//   Stage 4: execute + show summary
window.wfWipeAllTransactions = async function(){
  if (!((window.state && window.state.isDeveloper) || (typeof window._isDeveloperUser === 'function' && window._isDeveloperUser()))) {
    showToast('هذه العملية للمطور فقط', true);
    return;
  }
  // Stage 1
  if (!confirm('⚠ تحذير: هذه عملية حذف شاملة لكل المعاملات!\n\nسيتم محو كل المعاملات + كل الردود + كل المرفقات + كل السجلات + كل الإشعارات من النظام بشكل نهائي وعند جميع المستخدمين.\n\nهل تريد المتابعة لمعاينة العدد قبل التنفيذ؟')) return;
  // Stage 2: dry-run to get counts
  var token = localStorage.getItem('pos_token');
  var dryUrl = '/api/workflow/transactions/__wipe-all?dryRun=1';
  showToast('جاري حساب البيانات المتأثرة...');
  fetch(dryUrl, { method: 'DELETE', headers: { 'Authorization': 'Bearer '+token } })
    .then(function(r){return r.json();})
    .then(function(r){
      if (!r || !r.success) { showToast((r && r.error) || 'فشل التحقق', true); return; }
      var c = r.counts || {};
      if (!c.transactions) {
        alert('لا توجد معاملات في النظام للحذف.');
        return;
      }
      // Stage 3: show preview + ask for typed confirmation
      var preview =
        '📊 سيتم حذف ما يلي نهائياً:\n\n' +
        '• ' + (c.transactions||0) + ' معاملة\n' +
        '• ' + (c.transaction_steps_log||0) + ' سجل إجراء\n' +
        '• ' + (c.transaction_replies||0) + ' رد\n' +
        '• ' + (c.txn_attachments||0) + ' مرفق\n' +
        '• ' + (c.txn_recipients||0) + ' مستلم\n' +
        '• ' + (c.notifications||0) + ' إشعار\n' +
        '• ' + (c.payment_records_unlinked||0) + ' سند دفع (سيُفصل لا يُحذف)\n\n' +
        '⚠ هذا الإجراء نهائي ولا يمكن التراجع عنه.\n\n' +
        'اكتب: DELETE-ALL-FOREVER';
      var typed = prompt(preview);
      if (typed !== 'DELETE-ALL-FOREVER') {
        showToast('تم الإلغاء — لم تتطابق كلمة التأكيد', true);
        return;
      }
      // Stage 4: execute
      showToast('جاري التنفيذ... قد يستغرق ثوانٍ');
      fetch('/api/workflow/transactions/__wipe-all?confirm=DELETE-ALL-FOREVER', {
        method: 'DELETE',
        headers: { 'Authorization': 'Bearer '+token, 'Content-Type': 'application/json' },
        body: JSON.stringify({ confirm: 'DELETE-ALL-FOREVER' })
      })
        .then(function(rr){return rr.json();})
        .then(function(rr){
          if (rr && rr.success) {
            var summary = 'تم حذف ' + (rr.counts && rr.counts.transactions || 0) + ' معاملة + كل البيانات المرتبطة.';
            alert('✓ ' + summary + '\n\n' + (rr.message || ''));
            wfLoadInbox();
            // Refresh counters
            if (typeof wfLoadIncoming === 'function') try { wfLoadIncoming(); } catch(_){}
          } else {
            showToast((rr && rr.error) || 'فشل التنفيذ', true);
          }
        })
        .catch(function(err){ showToast('فشل الاتصال: ' + (err && err.message), true); });
    })
    .catch(function(err){ showToast('فشل التحقق: ' + (err && err.message), true); });
};

window.wfBulkAction = async function(action){
  var ids = Object.keys(window._wfBulkSelected);
  if (!ids.length) return;
  var actionLabel = (window.TxnConst && window.TxnConst.actionLabel(action)) || action;
  var note = '';
  if (action === 'reject') {
    note = window.WoModal
      ? (await window.WoModal.prompt({ title: 'سبب الرفض الجماعي', label: 'سيُطبَّق على ' + ids.length + ' معاملة', validate: function(v){ if (!v || v.trim().length < 10) return 'الحد الأدنى 10 أحرف'; } }))
      : (window.prompt('سبب الرفض الجماعي (10 أحرف على الأقل):') || '').trim();
    if (!note) return;
  } else {
    var ok = window.WoModal
      ? await window.WoModal.confirm({ title: actionLabel + ' جماعي', message: 'سيتم تطبيق "' + actionLabel + '" على ' + ids.length + ' معاملة. متابعة؟', danger: action !== 'approve' })
      : window.confirm('تطبيق "' + actionLabel + '" على ' + ids.length + ' معاملة؟');
    if (!ok) return;
  }
  var token = localStorage.getItem('pos_token');
  var done = 0, failed = 0;
  for (var i = 0; i < ids.length; i++) {
    try {
      var idemKey = 'bulk-' + action + '-' + ids[i] + '-' + Date.now();
      var resp = await fetch('/api/workflow/transactions/' + ids[i] + '/action', {
        method: 'POST',
        headers: { 'Authorization': 'Bearer '+token, 'Content-Type':'application/json', 'X-Idempotency-Key': idemKey },
        body: JSON.stringify({ action: action, username: currentUser, note: note || actionLabel + ' جماعي', idempotencyKey: idemKey })
      }).then(function(r){return r.json();});
      if (resp && resp.success) done++; else failed++;
    } catch(_) { failed++; }
  }
  var msg = '✓ ' + done + ' نجحت' + (failed ? ' • ✗ ' + failed + ' فشلت' : '');
  if (window.WoModal && window.WoModal.toast) window.WoModal.toast({ message: msg, kind: failed?'warning':'success' });
  else if (typeof showToast === 'function') showToast(msg, !!failed);
  window.wfBulkClear();
  setTimeout(function(){ if (typeof wfLoadInbox === 'function') wfLoadInbox(); }, 400);
};

// V5: filter persistence (sessionStorage) + search
window.wfPersistFiltersAndLoad = function(){
  try {
    sessionStorage.setItem('wf_inbox_filters', JSON.stringify({
      status: (document.getElementById('wfInboxStatusFilter')||{}).value || '',
      search: (document.getElementById('wfInboxSearch')||{}).value || ''
    }));
  } catch(_){}
  if (typeof wfLoadInbox === 'function') wfLoadInbox();
};
// On load, restore filter state
(function _wfRestoreFilters(){
  try {
    var raw = sessionStorage.getItem('wf_inbox_filters');
    if (!raw) return;
    var f = JSON.parse(raw);
    setTimeout(function(){
      var s = document.getElementById('wfInboxStatusFilter');
      var q = document.getElementById('wfInboxSearch');
      if (s && f.status) s.value = f.status;
      if (q && f.search) q.value = f.search;
    }, 800);
  } catch(_){}
})();

// V5: CSV export of currently visible (filtered) inbox
window.wfExportInboxCsv = function(){
  var list = window._wfInboxPagedList || [];
  if (!list.length) {
    if (typeof showToast === 'function') showToast('لا توجد معاملات للتصدير', true);
    return;
  }
  var headers = ['الرقم','الحالة','النوع','الفرع','القسم','العنوان','المبلغ','المسؤول','التاريخ'];
  var csv = '﻿' + headers.join(',') + '\n';   // BOM for Excel UTF-8
  list.forEach(function(t){
    var statusLbl = (window.TxnConst && window.TxnConst.statusLabel(t.status)) || t.status || '';
    var fields = [
      t.txnNumber || t.id || '',
      statusLbl,
      t.typeName || '',
      t.branchName || t.branchCode || '',
      t.deptName || t.deptCode || '',
      (t.title || '').replace(/"/g, '""'),
      Number(t.amount) || 0,
      t.currentAssignee || '',
      t.createdAt ? new Date(t.createdAt).toISOString().slice(0,10) : ''
    ].map(function(v){ return '"' + String(v).replace(/"/g, '""') + '"'; });
    csv += fields.join(',') + '\n';
  });
  var blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'transactions_inbox_' + new Date().toISOString().slice(0,10) + '.csv';
  document.body.appendChild(a); a.click();
  setTimeout(function(){ document.body.removeChild(a); URL.revokeObjectURL(url); }, 100);
  if (typeof showToast === 'function') showToast('✓ تم تصدير ' + list.length + ' معاملة');
};

// ───────────────────────── Helpers ─────────────────────────

// Quick Hijri approximation (Umm al-Qura is too heavy to ship). Deviation ±1 day ok.
function _gregToHijri(g) {
  var jd = Math.floor((g.getTime() + g.getTimezoneOffset()*60000)/86400000) + 2440588;
  var l = jd - 1948440 + 10632;
  var n = Math.floor((l - 1)/10631);
  l = l - 10631*n + 354;
  var j = (Math.floor((10985-l)/5316))*(Math.floor((50*l)/17719)) + (Math.floor(l/5670))*(Math.floor((43*l)/15238));
  l = l - (Math.floor((30-j)/15))*(Math.floor((17719*j)/50)) - (Math.floor(j/16))*(Math.floor((15238*j)/43)) + 29;
  var m = Math.floor((24*l)/709);
  var d = l - Math.floor((709*m)/24);
  var y = 30*n + j - 30;
  return y + '/' + String(m).padStart(2,'0') + '/' + String(d).padStart(2,'0');
}

