// ─── CSV import / export ─────────────────────────────────────────────────
window._faExportCsv = function() {
  var rows = _faCache.filtered || [];
  var headers = ['code','name','category','status','purchase_date','purchase_cost','salvage_value',
                 'useful_life_years','dep_start_month','current_value','dep_until_date',
                 'gl_asset_account_code','gl_dep_expense_account_code','gl_accum_dep_account_code',
                 'notes','cost_center_name','project_id','branch_name','serial_number','updated_at','created_at'];
  var headerLabels = ['رقم الأصل','الاسم','الفئة','الحالة','تاريخ الشراء','كلفة الشراء','قيمة الخردة',
                      'العمر الإنتاجي','شهر بدء الإهلاك','القيمة الدفترية','مستهلك لغاية',
                      'حساب الأصل','حساب الإهلاك','حساب المجمع',
                      'ملاحظات','مركز التكلفة','المشروع','الفرع','الرقم التعريفي','تم التعديل','تم الإنشاء'];
  var csv = '﻿' + headerLabels.join(',') + '\n';
  rows.forEach(function(r) {
    csv += headers.map(function(h) {
      var v = r[h] == null ? '' : String(r[h]);
      if (v.indexOf(',') !== -1 || v.indexOf('"') !== -1 || v.indexOf('\n') !== -1) {
        v = '"' + v.replace(/"/g,'""') + '"';
      }
      return v;
    }).join(',') + '\n';
  });
  var blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url; a.download = 'fixed-assets-' + new Date().toISOString().slice(0,10) + '.csv';
  a.click();
  setTimeout(function(){ URL.revokeObjectURL(url); }, 1000);
};

window._faImportCsv = function(file) {
  if (!file) return;
  var reader = new FileReader();
  reader.onload = function(e) {
    var text = e.target.result;
    if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);   // strip BOM
    var lines = text.split(/\r?\n/).filter(function(l){return l.trim();});
    if (lines.length < 2) { if (typeof showToast === 'function') showToast('الملف فارغ', true); return; }
    // Use first row as field map (must match backend field names)
    var fields = lines[0].split(',').map(function(s){return s.trim();});
    var promises = lines.slice(1).map(function(line) {
      var cells = _faParseCsvLine(line);
      var body = {};
      fields.forEach(function(f, i) { body[f] = cells[i] || null; });
      return fetch('/api/erp/work-orders/assets', {
        method: 'POST',
        headers: { 'Content-Type':'application/json', 'Authorization':'Bearer ' + (localStorage.getItem('pos_token')||'') },
        body: JSON.stringify(body)
      }).then(function(r){return r.json();});
    });
    Promise.all(promises).then(function(results) {
      var ok = results.filter(function(r){return r.success;}).length;
      if (typeof showToast === 'function') showToast('تم استيراد ' + ok + ' / ' + results.length + ' أصل', ok===0);
      erpLoadFixedAssets();
    });
  };
  reader.readAsText(file);
};
function _faParseCsvLine(line) {
  var cells = []; var cur = ''; var inQ = false;
  for (var i = 0; i < line.length; i++) {
    var c = line[i];
    if (inQ) {
      if (c === '"') { if (line[i+1] === '"') { cur += '"'; i++; } else inQ = false; }
      else cur += c;
    } else {
      if (c === ',') { cells.push(cur); cur = ''; }
      else if (c === '"') inQ = true;
      else cur += c;
    }
  }
  cells.push(cur);
  return cells;
}

// ═══ Profitability by dimension — enhanced ═══
window.erpProfReset = function() {
  ['profFrom','profTo','profDim','profSort'].forEach(function(id){
    var el = document.getElementById(id); if (!el) return;
    if (el.tagName === 'SELECT') el.selectedIndex = 0; else el.value = '';
  });
  document.getElementById('profBranded').style.display = 'none';
  document.getElementById('profBody').innerHTML = '<tr><td colspan="7" class="empty-msg">حدد البُعد والفترة</td></tr>';
};
function erpLoadProfitability() {
  if (!document.getElementById('profFrom').value) document.getElementById('profFrom').value = new Date(new Date().getFullYear(),0,1).toISOString().slice(0,10);
  if (!document.getElementById('profTo').value)   document.getElementById('profTo').value   = new Date().toISOString().slice(0,10);
  var from = document.getElementById('profFrom').value;
  var to   = document.getElementById('profTo').value;
  var dim  = (document.getElementById('profDim')||{}).value || 'brand';
  var sort = (document.getElementById('profSort')||{}).value || 'profit_desc';
  var dimLabels = { brand:'البراند', branch:'الفرع', cost_center:'مركز التكلفة' };
  document.getElementById('profBnFrom').textContent = from;
  document.getElementById('profBnTo').textContent = to;
  document.getElementById('profBnDim').textContent = 'حسب ' + (dimLabels[dim]||dim);
  document.getElementById('profBranded').style.display = 'flex';

  var qs = new URLSearchParams({ from, to, dimension: dim }).toString();
  document.getElementById('profBody').innerHTML = '<tr><td colspan="7" class="empty-msg"><i class="fas fa-spinner fa-spin"></i></td></tr>';
  _erpGet('/erp/reports/profitability?' + qs, function(r) {
    if (!r.success) { document.getElementById('profBody').innerHTML = '<tr><td colspan="7" class="empty-msg" style="color:#ef4444;">'+(r.error||'خطأ')+'</td></tr>'; return; }
    var rows = (r.rows || []).slice();
    if (!rows.length) { document.getElementById('profBody').innerHTML = '<tr><td colspan="7" class="empty-msg">لا توجد بيانات</td></tr>'; return; }
    // Apply sort
    if (sort === 'profit_asc')  rows.sort(function(a,b){ return (a.profit||0) - (b.profit||0); });
    else if (sort === 'margin_desc') rows.sort(function(a,b){ return (b.margin||0) - (a.margin||0); });
    else if (sort === 'revenue_desc')rows.sort(function(a,b){ return (b.revenue||0) - (a.revenue||0); });
    else rows.sort(function(a,b){ return (b.profit||0) - (a.profit||0); });
    // Compute max profit for visual bars
    var maxProfit = Math.max.apply(null, rows.map(function(x){ return Math.abs(x.profit||0); }));
    var fmt = function(v){ return Number(v||0).toLocaleString('en',{minimumFractionDigits:2,maximumFractionDigits:2}); };
    document.getElementById('profBody').innerHTML = rows.map(function(x, i){
      var pc = x.profit>=0?'#16a34a':'#ef4444';
      var barPct = maxProfit ? Math.round(Math.abs(x.profit||0) / maxProfit * 100) : 0;
      var medal = i < 3 ? '<span style="background:'+['#fbbf24','#d1d5db','#fb923c'][i]+';color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-weight:900;font-size:11px;">'+(i+1)+'</span>' : (i+1);
      return '<tr>' +
        '<td>'+medal+'</td>' +
        '<td style="font-weight:800;">'+(x.name||'')+'</td>'+
        '<td style="color:#16a34a;font-weight:700;">'+fmt(x.revenue)+'</td>'+
        '<td style="color:#ef4444;font-weight:700;">'+fmt(x.expenses)+'</td>'+
        '<td style="color:'+pc+';font-weight:900;font-size:13px;">'+fmt(x.profit)+'</td>'+
        '<td style="color:'+pc+';font-weight:800;">'+x.margin+'%</td>'+
        '<td style="min-width:100px;"><div style="background:#f1f5f9;border-radius:4px;height:8px;overflow:hidden;"><div style="height:100%;width:'+barPct+'%;background:'+pc+';border-radius:4px;"></div></div></td>'+
      '</tr>';
    }).join('');
  });
}

// ─── Inventory Valuation REPORT (separate from the Inventory-Method page) ───
// V5.9.6 — this function previously shared the name `erpLoadInventoryValuation`
// with the inventory-method page renderer at line ~3054. Function-declaration
// hoisting made THIS one win, so navigating to "نوع الجرد" called this report
// renderer by mistake — it then crashed setting `document.getElementById('ivSummary').innerHTML`
// because `ivSummary` only lives on the reports page. The error surfaced as a
// red toast and the inventory-method spinner stayed forever. Renaming this one
// (and its two call sites) lets the inventory-method renderer fire correctly.
function erpLoadRptInventoryVal() {
  _erpPopulateBrandOptions(['ivBrand']);
  _erpGet('/erp/warehouses-list', function(whs) {
    var opts = '<option value="">الكل</option>' + (whs||[]).map(function(w){return '<option value="'+w.id+'">'+(w.name||'')+'</option>';}).join('');
    var el = document.getElementById('ivWh'); if (el) el.innerHTML = opts;
  });
  var wh = (document.getElementById('ivWh')||{}).value || '';
  var brand = (document.getElementById('ivBrand')||{}).value || '';
  var qs = new URLSearchParams({ warehouse: wh, brand }).toString();
  _erpGet('/erp/reports/inventory-valuation?' + qs, function(r) {
    if (!r || !r.success) { showToast((r && r.error)||'خطأ', true); return; }
    var g = r.grand || {};
    var sumEl = document.getElementById('ivSummary');
    if (sumEl) sumEl.innerHTML =
      _erpKpi('عدد الأصناف', (g.itemCount||0), '#0ea5e9') +
      _erpKpi('إجمالي الكمية', _erpFmt(g.totalQty), '#64748b') +
      _erpKpi('إجمالي القيمة', _erpFmt(g.totalValue), '#16a34a');
    var bw = r.byWarehouse || [];
    var bwEl = document.getElementById('ivByWarehouse');
    if (bwEl) bwEl.innerHTML = bw.length ? ('<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;">' + bw.map(function(w){
      return '<div class="erp-rpt-card"><div><div class="lbl">'+(w.warehouseName||'')+' ('+w.itemCount+' صنف)</div><div class="val">'+_erpFmt(w.totalValue)+'</div></div></div>';
    }).join('') + '</div>') : '';
    var items = r.items || [];
    var bodyEl = document.getElementById('ivBody');
    if (bodyEl) bodyEl.innerHTML = items.length ? items.map(function(x){
      return '<tr><td>'+(x.itemName||'')+'<div style="font-size:10px;color:#94a3b8;">'+(x.sku||'')+'</div></td><td>'+(x.warehouseName||'')+'</td><td>'+_erpFmt(x.qty)+' '+(x.unit||'')+'</td><td>'+_erpFmt(x.avgCost)+'</td><td style="font-weight:700;">'+_erpFmt(x.value)+'</td></tr>';
    }).join('') : '<tr><td colspan="5" class="empty-msg">لا توجد أصناف</td></tr>';
  });
}
window.erpLoadRptInventoryVal = erpLoadRptInventoryVal;

